INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22114530916', 'Redken All Soft Mega Moisture Restore Leave-in 150ml', 'All Soft Moisture Restore Leave-In Treatment é um leave-in para cabelos secos que hidrata e adiciona brilho instantâneo. O resultado são cabelos macios e saudáveis. Formulado com Ácido Hialurônico, este tratamento sem enxágue funciona retendo as moléculas de umidade perdidas por ofensores como processos químicos, ferramentas de calor e exposição ao sol. Sua ação sela a cutícula dos fios com um pH ácido para reter a umidade e equilibrar o pH do cabelo. * RESULTADO: Nutrição Maciez * SUGESTÕES DE USO: Aplicar diariamente nos cabelos úmidos. Para melhores resultados, certifique-se de usar com o shampoo e condicionador All Soft. * OBSERVAÇÕES: Imagem Meramente Ilustrativa * ITENS INCLUSOS: 1 Redken All Soft Mega Moisture Restore Leave-in 150ml', 192.9, 166.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-22120-op7vhwx5bllvbd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F681570887%2F22114530916', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
