INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23798462842', 'Vazador De Aço Redondo 9mm Vonder Junta Papelao Couro Manual Furador Artesanato', 'O Furador Vazador 9mm Aço Couro Eva Junta Papelao Vonder é a ferramenta ideal para quem busca precisão e eficiência em seus projetos de artesanato e confecção. Com um diâmetro de perfuração de 9mm, este furador é perfeito para trabalhar com diversos materiais, como couro, papelão, EVA, lonas e cintos, proporcionando acabamentos profissionais em cada uso. Adicione o Furador Vazador 9mm Aço à sua coleção de ferramentas e leve suas criações a um novo nível de qualidade e sofisticação. Vazador De Aço Redondo 9mm Vonder Junta Papelao Couro Manual MARCA: VONDER ITENS INCLUSOS: 1un furador/vazador de aço 9mm MATERIAL: Aço Carbono MEDIDAS: - Diâmetro furação = 9mm - Comprimento total = 116mm IMPORTANTE: Indicado para perfurar couro, papelão e juntas. - Envia ainda hoje? Sim. Comprando até às 12:00 postaremos no mesmo dia. IMPORTANTE: No ato da compra, caso necessário, enviaremos uma mensagem confirmando algumas informações, como: ano, modelo e motor, para evitar enganos no envio e transtornos posteriores, caso não haja a confirmação, enviaremos conforme o anúncio que a compra foi feita. Os envios são realizados de segunda a sexta-feira.', 21.01, 21.01, NULL, 'Stationery > School & Office Equipment > Hole Punchers', 'https://cf.shopee.com.br/file/sg-11134201-7rfex-m9ko7yk4ytyka6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F938446605%2F23798462842', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
