INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23793810737', 'Óleo Capilar Finalizador Explosão de Óleos 55ml bn.Cachos', 'Óleo Finalizador BN Explosão - bn.Cachos 55ml Transforme seus cabelos com o Óleo Finalizador BN Explosão - bn.Cachos 55ml! Desenvolvido especialmente para cabelos crespos, cacheados e ondulados, este óleo proporciona nutrição intensa, controle do frizz e um brilho radiante, sem pesar os fios. Escolha a variação ideal para o seu cabelo: Abacate e Oliva Benefícios: Nutrição profunda, controle do frizz e proteção contra danos, garantindo fios macios e brilhantes. Jojoba e Argan Benefícios: Revitalização e reparação dos fios, proporcionando brilho e saúde sem pesar. Linhaça e Algodão Benefícios: Hidratação intensa, fortalecimento e definição dos cachos, além de um toque suave e sedoso. Destaques do Óleo Finalizador BN Explosão: Proteção Térmica: Protege os fios contra danos causados pelo calor de ferramentas térmicas. Aroma Agradável: Combinação de fragrâncias que deixam os cabelos perfumados. Fórmula Leve: Não pesa nos fios, garantindo movimento natural. Modo de Uso: Aplique uma pequena quantidade do óleo na palma das mãos, esfregue-as para aquecer o produto e distribua uniformemente nos cabelos úmidos ou secos, do comprimento às pontas. Pode ser utilizado antes ou após o uso de ferramentas térmicas. Garanta já o seu Óleo Finalizador BN Explosão e proporcione aos seus cabelos o cuidado que eles merecem!', 31.99, 19.89, NULL, 'Beauty > Hair Care > Hair Styling', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mbeas8dlp9fde3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1202663615%2F23793810737', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
