INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23994911123', 'ALBUM COPA DO MUNDO 2026 - CAPA BROCHURA + 5 ENVELOPES', 'ALBUM COPA DO MUNDO 2026 - CAPA BROCHURA + 5 ENVELOPES FIFA World Cup 2026™ As emoções do maior espetáculo esportivo do mundo eternizadas no maior álbum de figurinhas de todos os tempos! Uma coleção completa, com todas as seleções classificadas, cromos especiais e todos os detalhes para você acompanhar de pertinho a disputa pela taça da FIFA World Cup 2026™! O álbum tem 980 cromos, sendo 68 deles especiais, e contempla as 48 seleções que participam do Mundial de 2026, que acontece entre junho e julho no México, nos Estados Unidos e no Canadá. Este kit exclusivo inclui: Álbum Capa Brochura 5 Envelopes de figurinhas (7 cromos por envelope)', 71.9, 71.9, NULL, 'Books & Magazines > Books > Hobbies', 'https://cf.shopee.com.br/file/sg-11134201-81zvq-mmnkleln9rtb31', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F303956123%2F23994911123', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18299311053', 'VOU TE RECEITAR UM GATO - INTRINSECA', 'Best-seller japonês chega ao Brasil trazendo história comovente e inovadora sobre como o amor de um animal pode mudar a nossa vida No final de um beco escuro, há um prédio antigo onde funcionam vários estabelecimentos. Um deles é a Clínica Kokoro, um lugar que apenas as almas que mais precisam de ajuda conseguem encontrar. A misteriosa clínica oferece um tratamento exclusivo ― e um tanto estranho ― para aqueles que chegam até lá: gatos. Os pacientes muitas vezes ficam intrigados com essa prescrição nada convencional, mas quando “tomam” o animal pelo período recomendado, testemunham profundas transformações em suas vidas ― efeito colateral causado pelos gatinhos brincalhões, cativantes e de vez em quando bagunceiros. Graças ao remédio milagroso ― e muito fofo ― receitado pelo excêntrico dr. Nike e sua enfermeira mal-humorada, Chitose, um corretor de investimentos se depara com uma alegria inesperada após ser demitido; um homem de meia-idade encontra paz no trabalho e em casa; uma mãe cansada se reconecta com a filha; uma designer de bolsas aprende finalmente a relaxar; e uma gueixa abalada pela perda de sua gata descobre como seguir em frente. À medida que os pacientes da clínica lidam com seus conflitos internos e buscam soluções, os companheiros felinos os conduzem à cura e lhes mostram que, às vezes, tudo o que você precisa é do amor de um gato.', 53.9, 53.9, NULL, 'Books & Magazines > Books > Fantasy', 'https://cf.shopee.com.br/file/sg-11134201-7rask-ma8xzohi0t5677', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F303956123%2F18299311053', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23698327657', 'Alicate Bico Longo Ponta Meia Lua Oval P/ Automóveis Conectores Aço Carbono 11 Polegadas', 'Alicate Bico Meia Lua Longo 11 Polegadas Eda O Alicate Bico Meia Lua Longo 11 Polegadas é uma ferramenta profissional de alta qualidade, projetada para oferecer precisão e conforto no trabalho. Seu formato de bico curvado em meia lua facilita o manuseio de peças e fios em áreas de difícil acesso, tornando-o ideal para trabalhos de eletrônica, montagem e reparos. Características: > Possui longa durabilidade; > O alicate de bico longo oval é ideal para torcer fios, arames, segurar pequenas peças; > Podem ser usados para prender pequenas peças eletrônicas para solda, além outras utilidades. Especificações Técnicas: > Material: aço carbono; > Espessura: 11 polegadas; > Tipo: bico longo meia lua. - Marca: Eda - Garantia: 90 dias contra defeitos de fabricação Vantagens de comprar na Brester: - Produto a pronta entrega. - Produto novo, com garantia de fábrica. - Nota fiscal para Pessoa Física e Pessoa Jurídica.', 50.47, 37.35, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rd5g-m7i0nz7w7pytdc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442506479%2F23698327657', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
