INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19557323225', 'Modelador de Cachos X330 32mm X 130mm Vertix - Bivolt', 'O Modelador de Cachos X330 Vertix possui um design inovador e ergonômico. Crie cachos que duram mais tempo com a variedade de modeladores Vertix Professional. Ideais para você obter diferentes penteados, de curto a longos, dos cachos mais largos e naturais, aos cachos mais finos. Pode ser ligado nas tensões 127v e 220v sem a necessidade de troca de chave. Características: - Temperatura 210°c; - Aquecimento cerâmico; - Temperatura constante; - Deslize perfeito. Benefícios: - Temperatura constante; - Fácil manuseio; - Bivolt.', 269.87, 189.9, NULL, 'Beauty > Beauty Tools > Hair Tools', 'https://cf.shopee.com.br/file/sg-11134201-8259c-mr20krk8ahomad', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F683941545%2F19557323225', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22098856808', 'Kit Nivea Care Creme Hidratante Latinha Azul 29g + Hidratante Labial Melancia Shine 4,8g', 'O Kit Nivea Original Care + Creme Nivea Latinha Azul oferece hidratação completa para os lábios e para a pele. O Hidratante Labial Nivea Original Care garante até 24 horas de hidratação intensa, mantendo os lábios macios, protegidos e livres do ressecamento. Sua fórmula é enriquecida com óleos naturais, possui embalagem reciclável e é livre de óleos minerais. Já o Creme Nivea Latinha Azul é um clássico que protege e hidrata profundamente até as áreas mais ressecadas do corpo, proporcionando maciez e cuidado diário. Contém no kit: • Creme Hidratante Nivea Latinha Azul 29g - 1 Unidade • Hidratante Labial Nivea Melancia Shine 4,8g - 1 Unidade Benefícios: • Hidratação intensa dos lábios por até 24 horas • Fórmula com óleos naturais e embalagem reciclável • Lábios protegidos contra o ressecamento • Hidratação profunda para a pele com o Creme Nivea • Textura cremosa e alto poder de nutrição Modo de uso: • Aplique o hidratante labial nos lábios sempre que sentir necessidade. • Para o creme, espalhe sobre a pele limpa em regiões que necessitem de hidratação intensa, massageando até completa absorção. Sobre a marca: Marca nº 1 de cuidados com a pele no mundo, seu pioneirismo e sucesso fazem da NIVEA uma marca que sempre dita tendências de inovação. O cuidado com as pessoas, há mais de 100 anos, e a segurança do consumidor são as nossas prioridades. A NIVEA conta com mais de 500 itens em seu portfólio que valorizam a individualidade e necessidades de cada tipo de pele. • Para lábios e pele protegidos e hidratados por muito mais tempo!!', 42.5, 35.82, NULL, 'Beauty > Hand, Foot & Nail Care > Hand Care', 'https://cf.shopee.com.br/file/sg-11134201-824gz-mpl845q46ccjfd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F683941545%2F22098856808', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
