INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23398001922', 'Fita de LED Mangueira Neon 5 Metros 60W Flexível Com Fonte 12V | 8 Cores', '💡 FITA NEON LED 60W 5M - Iluminação Versátil e Colorida! 💡 ✅ Especificações Técnicas - Fita Neon LED: 💡 Potência: 12W/M = 60W ⚡ Tensão: 12V 📐 Ângulo de Abertura: 120° 🔄 Vida Útil: 12000 horas 🎨 IRC (Índice de Reprodução de Cor): 70 💦 Proteção contra Água e Poeira 🔒 Garantia: 1 ano 📏 Tamanho: 5m/rolo 🌟 Recursos e Benefícios - Fita Neon LED: ✨ Iluminação Vibrante: 8 Cores para ambientes dinâmicos. 🎮 Controle Remoto: Facilidade para ajustar as cores e modos. 🌐 Versatilidade: Adapta-se a diferentes ambientes e decorações. 💧 Proteção IP65: Segura para uso em áreas externas. 🌈 Vida Útil Prolongada: 12000 horas de iluminação duradoura. 🔒 Garantia de Qualidade: 1 ano de garantia para confiança. 🔌 FONTE ADAPTADORA - Potência Confiável para Sua Fita LED! 🔌 🌐 Garanta uma iluminação colorida e eficiente com a Fita Neon LED e a Fonte Adaptadora! Transforme seus espaços com cores vibrantes e iluminação personalizável. ✨💡 ATENÇÃO: ESSE ANÚNCIO CONTÉM FONTE INCLUSA!', 59.0, 28.9, NULL, 'Home & Living > Lighting', 'https://cf.shopee.com.br/file/sg-11134201-7rens-m24r3lzpcd30ff', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1137412789%2F23398001922', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23794023808', 'Payot Maternite Plus Creme Antiestrias 200ml', 'Payot Maternite Plus Creme Antiestrias 200ml Creme antiestrias. Payot Maternité Plus restaura a elasticidade e firmeza da pele, deixando uma aparência mais bonita. O Creme Antiestrias Payot Maternité Plus tem em sua composição óleos vegetais e pantenol que fortalecem as fibras elásticas e o colágeno. Garante uma hidratação e nutrição profunda da derme, deixando-a macia ao toque. Conselho de Aplicação Aplique o produto sobre a pele limpa e seca duas vezes ao dia, massageie suavemente até a absorção total do produto, principalmente nas áreas mais suscetíveis a estrias. É importante tratar as estrias logo no início, quando a capacidade de regeneração é maior. Ou seja, quando as suas marcas ainda estiverem vermelhas é o momento ideal. Isso porque a coloração indica inflamação, o que significa que elas estão no início do quadro.', 146.08, 91.9, NULL, 'Beauty > Skincare > Facial Moisturizer', 'https://cf.shopee.com.br/file/sg-11134201-7ratp-ma45xg40cycu1d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322434863%2F23794023808', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23392366911', 'Kit 2 Tapete Higiênico Ultra Secão 05 em 01 80x60 para Cães - 30 Unidades', 'Tapete Higiênico Ultra Secão 05 em 01 80x60 para Cães - 30 Unidades - Controle eficiente de odores: cheiros indesejados são neutralizados, mantendo o ambiente agradável; - Barreiras anti-vazamento: permite que a urina fique contida no tapete, facilitando a limpeza e descarte; - Desenvolvido com atrativo canino, ajuda a atrair o pet para usá-lo como área para realizar suas necessidades; - 5 camadas de proteção: maior resistência e desempenho, garantindo durabilidade e eficiência ao longo do tempo. Detalhes O Tapete Higiênico Ultra Secão 05 em 01 80x60 para Cães, possui uma capacidade de absorção incrível, podendo absorver até 1 litro de urina. É eficiente no controle de odores e as barreiras anti-vazamento evitam que o líquido escorra para fora do tapete, proporcionando uma proteção extra. Sua estrutura é composta por 5 camadas de proteção, o que o torna resistente e com um desempenho superior. Dicas Especiais Se houver um acidente fora do tapete higiênico, limpe imediatamente com um removedor de odores específico para animais de estimação. Isso ajudará a evitar que seu pet associe aquela área com um local apropriado para fazer as necessidades. Indicação: Cachorros Porte/Raça: Raças Pequenas, Raças Médias, Raças Grandes Idade: Filhotes, Adultos, Idosos Apresentação: 30 Unidades', 242.68, 132.9, NULL, 'Pets > Litter & Toilet > Dog Training Pads & Trays', 'https://cf.shopee.com.br/file/sg-11134201-7rbmk-llh5zbt6ms57a4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290073877%2F23392366911', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
