INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209720159', 'Sal Marinho Integral Fino BR Spices 500g', 'O Sal Marinho Fino da BR Spices é um sal integral, não refinado, originado das melhores produções do mundo, perfeito para substituir o sal comum e adicionar mais qualidade e sabor aos seus pratos. Nosso Sal Marinho nasce no encontro das águas no estuário do rio Mossoró, no Rio Grande do Norte. É obtido naturalmente através da ação do sol e dos ventos. Descubra um Sal puro e integral, que não passa por tratamentos termoquímicos e preserva seus minerais essenciais. Da natureza brasileira direto para o seu prato! Com granulação fina e textura leve, é ideal para o uso diário na sua cozinha: saladas, grelhados, massas, legumes e tudo mais que o seu paladar pedir! Experimente o Sal Rosa do Himalaia ou o Sal do Atacama, exclusividade no Brasil.', 6.99, 6.99, NULL, 'Food & Beverages > Cooking Essentials > Seasonings & Condiments', 'https://cf.shopee.com.br/file/sg-11134201-8259k-mqneliw6el1ebb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554977%2F58209720159', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20497752401', 'Aventura de uma gota d''''''''''''''''água', 'Você conhece os caminhos pecorridos pela água na natureza? Pois bem, este livro conta as aventuras de uma gota d´agua narradas por ela mesma, desde a sua formação nas nuvens até o seu destino final nos oceanos. Um longo caminho. Vai ser uma viagem incrível e você não pode perdê-la. Entre nessa aventura e saiba como nasce uma gota d´agua, como se formam os rios, quais os benefícios que a água traz e as agressões que ela sofre com todo tipo de poluição.', 78.05, 78.05, NULL, 'Books & Magazines > Books > Children''s Books', 'https://cf.shopee.com.br/file/sg-11134201-7rdyf-lxoc8p10kt0p8d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F20497752401', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
