INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23292567730', 'Flexível Freio Gm Vectra 1997 a 2005 - 105492 - 4071', 'Flexível Freio Gm Vectra 1997 a 2005 105492 4071 DIANTEIRO (FÊMEA/FURO - 440mm) É o componente que transmite a pressão hidráulica da tubulação para as rodas, permitindo o livre movimento das mesmas. Promover o controle do veículo em situações de baixo atrito entre pneu e solo, através da modulação da pressão hidráulica de frenagem impedindo assim o bloqueio das rodas. (Mangueira que tem a função de conduzir o fluído Hidráulico entre o cilindro mestre até a pinça de freio).', 51.54, 51.54, NULL, 'Automobiles > Automobile Spare Parts > Brake System', 'https://cf.shopee.com.br/file/br-11134201-820lc-mqy433cryadj13', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F23292567730', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19197668705', 'Sensor Posição Borboleta Ford Ka 1997 a 1999 - 122136 - 7264', 'Sensor Posição Borboleta Ford Ka 1997 a 1999 122136 7264 1.0 8v Endura - Giro Sentido Horário - 3 Pinos O Sensor de Posição da Borboleta (Throttle Position Sensor – TPS) é utilizado para monitorar a posição do acelerador em um motor de combustão interna. O sensor tem como finalidade informar a posição da borboleta do acelerador. Através do TPS, a UCE obtém informações instantâneas da posição da borboleta permitindo à central identificar a potência que o condutor está requerendo. Essas informações são utilizadas no auxílio do cálculo do tempo de injeção, avanço da ignição,etc...', 111.48, 111.48, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Injection', 'https://cf.shopee.com.br/file/sg-11134201-8258y-mr210h9kudjbda', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F19197668705', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
