INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22298338379', 'Pré Filtro Combustível Citroen C4 2018 a 2025 - 1354807 - T040209', 'Pré Filtro Combustível Citroen C4 2018 a 2025 1354807 T040209 Cactus 1.6 16v Flex - Sistema Bosch - Copo, filtro externo e internoO pré-filtro é um elemento confeccionado com filamentos trançados de abertura controlada. Essa “malha” tem a função de filtrar o combustível que entra na bomba e, assim, evitar que possíveis impurezas contidas no tanque ou no combustível comprometam o seu perfeito funcionamento. Está localizado dentro do tanque de combustível, geralmente na extremidade da bomba ou do “pescador”.', 51.19, 51.19, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-822xv-mo9vzlf3vitne7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22298338379', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22292528592', 'Flange Bomba Combustível Peugeot 208 2013 a 2017 - 509517 - T030040', 'Flange Bomba Combustível Peugeot 208 2013 a 2017 509517 T030040 MOTOR 1.5/1.6 FLEX (BOSCH) Flange é um elemento de plástico ou de metal que fixa o Módulo de Combustível ao tanque de combustível do veículo. Além da fixação, a Flange faz ligação hidráulica e elétrica do interior do tanque para o exterior, permitindo o acesso ao Módulo de Combustível (composto por bomba de combustível, sensor de nível, pré-filtro, regulador de pressão, tubo corrugado e guarnição) sem operação destrutiva ou de descarte, proporcionando o reparo necessário dos componentes inclusive da própria Flange.', 72.06, 72.06, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-823px-mok39s1qwd1e39', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22292528592', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '52358074309', 'Notebook Acer Aspire Go i5-13420H 8GB 256GB W11 15.6" - AG15-71P-5939', 'Notebook Acer Aspire Go i5-13420H 8GB 256GB W11 15,6'''' O Notebook Acer Aspire Go 15 é uma excelente escolha para quem busca desempenho, praticidade e ótimo custo-benefício no dia a dia. Equipado com o processador Intel Core i5-13420H, ele oferece desempenho superior para tarefas como estudos, trabalho, navegação, planilhas e até multitarefas mais exigentes. Com 8GB de memória RAM e SSD de 256GB, o notebook garante inicialização rápida do sistema, abertura ágil de programas e boa fluidez no uso cotidiano. A tela de 15,6 polegadas proporciona conforto visual para longos períodos de uso, sendo ideal para produtividade e entretenimento. Já com o Windows 11 instalado, o usuário conta com uma interface moderna, segura e pronta para uso imediato. Principais Características Processador Intel Core i5-13420H (alta performance) 8GB de RAM SSD de 256GB (mais velocidade) Tela de 15,6" Sistema Windows 11 Ideal para trabalho, estudos e uso diário Design moderno e leve Ficha Técnica: Marca: Acer Linha: Aspire Go Processador: Intel Core i5-13420H 8 núcleos (4 Performance + 4 Efficient) Frequência turbo até ~4.6 GHz Memória RAM: 8GB Armazenamento: 256GB SSD Tela: 15,6" Resolução: Full HD (1920 × 1080) Tipo: LED Placa de vídeo: Integrada (Intel UHD Graphics) Sistema operacional: Windows 11 Conectividade: Wi-Fi Bluetooth Portas: USB USB-C HDMI Áudio (P2) Teclado: Padrão ABNT2 Bateria: Longa duração (uso moderado) Cor: Preto/Cinza (varia por lote) Voltagem: Bivolt Itens Inclusos: 1 Notebook Acer Aspire Go i5-13420H; 1 Fonte/carregador; 1 Manual do usuário.', 5712.86, 4399.0, NULL, 'Computers & Accessories > Laptops', 'https://cf.shopee.com.br/file/br-11134207-820lg-mmjbtuzbetj85a', 'https://shope.ee/an_redir