INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '46606762691', 'Kit Filtros Gol G3 G4 1.0 8V Oleo Combustivel e Gasolina Tecfil Original', 'Kit Filtros VW Gol G3 G4 1.0 Tecfil Original Aplicação completa: - todos os modelos do Gol G3 e G4 1.0 8V Ano de aplicação: 2002 2003 2004 2005 2006 2007 2008 2009 2010 2011 2012 2013 Conteúdo do Kit: - 01 Filtro de óleo lubrificante - TM2 - 01 Filtro de combustível - GI08/1 tecfil - 01 Filro de ar - ARL6096 Filtros tecfil 1ª linha, maior fabricante de filtros do continente - Qualidade e Desempenho para Seu Veículo. Se você é um proprietário de veículo que preza pela manutenção e desempenho do motor, os filtros Tecfil são a escolha ideal. Nossos filtros são projetados para oferecer máxima eficiência, garantindo proteção e durabilidade para o motor do seu carro. Por que a Tecfil? - Qualidade Superior: - Desempenho Confiável: - Compatibilidade Garantida: Benefícios de Usar Filtros Tecfil: - Proteção do Motor: - Economia de Combustível: - Menor Desgaste: IMPORTANTE: Troque os filtros do seu veículo a cada troca de óleo, conforme recomendado pelo fabricante; Caso tenha interesse, temos todas as opções de kits completos para troca de óleo e higienização de ar condicionado, será um prazer receber a sua visita na nossa loja; Retire suas dúvidas antes de realizar a compra! ATENÇÃO: - Não nos responsabilizamos pelo mau uso ou instalação indevida do produto. - Recomendamos que a instalação seja realizada por um profissional especializado. - Algumas imagens ( fotos ) são meramente ilustrativas.', 78.2, 69.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/br-11134207-820lz-mohmsqcmnoxx76', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F560163381%2F46606762691', NULL, NULL, '2026-07-28T02:11:31