INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259114207', 'Panela Elétrica de Arroz DiamondTech 1,2L Oster Black', 'Tecnologia exclusiva DiamondTech Possui antiaderência que evita riscos e que os alimentos grudem. - Tampa de vidro refratário: Transparente e com ventilação que evita o cozimento excessivo. - 500W de potência: Garante mais agilidade no cozimento. - Sinalizador luminoso: Permite visualizar todas as funções durante o preparo. - Função manter aquecido: Mantém os preparos na temperatura ideal para servir. - Recipiente removível de 1,2 L: Capacidade para até 7 xícaras de arroz e cabo também removível. - Acessórios inclusos: copo medidor e colher: Acompanha acessórios úteis durante o uso.', 279.9, 249.9, NULL, 'Home Appliances > Kitchen Appliances > Multi-function Cookers', 'https://cf.shopee.com.br/file/sg-11134201-8258s-mqdcsr8p4wsh88', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1573223607%2F58259114207', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58200140205', 'COOLER OFICIAL CORINTHIANS 10 LATAS', 'COOLER CORINTHIANS TÉRMICO OFICIAL PARA 10 LATAS Mantenha suas bebidas sempre geladas com praticidade, qualidade e muito estilo. Este cooler térmico oficial é a escolha ideal para acompanhar você em momentos de lazer, churrascos, viagens, praia, festas e dias de jogo. Com capacidade para até 10 latas de 350ml, oferece excelente conservação térmica graças ao seu isolamento interno com chapa de isopor prensado. Seu design funcional conta com alça rígida articulável para facilitar o transporte e tampa com encaixe seguro, proporcionando mais comodidade no uso. Características do Produto • Capacidade para até 10 latas de 350ml • Conservação térmica eficiente para manter as bebidas geladas por mais tempo • Alça rígida articulável para transporte prático • Tampa móvel com encaixe firme • Isolamento interno com chapa de isopor prensado • Estrutura resistente e durável • Formato externo levemente cônico, proporcionando maior estabilidade Acabamento e Personalização • Impressão digital 360º de alta resolução • Cores vibrantes e excelente definição • Ótimo acabamento e alta durabilidade da personalização Informações Adicionais • Produto Oficial • Acompanha embalagem original do clube • Ideal para churrascos, praia, camping, viagens, festas, pescarias e eventos esportivos Excelente Opção de Presente Um item útil, resistente e indispensável para quem gosta de manter suas bebidas sempre na temperatura ideal, sem abrir mão da paixão pelo seu time. Adquira agora o seu e aproveite seus momentos de lazer com muito mais praticidade e estilo.', 149.9, 149.9, NULL, 'Sports & Outdoors > Sports & Outdoor Accessories > Others', 'https://cf.shopee.com.br/file/br-11134207-820lb-motun1vnmaytf2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1561205436%2F58200140205', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
