INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44359463684', 'Pedivela Triplo 24-34-42 Dentes em Aço', 'O pedivela triplo com coroas de 24, 34 e 42 dentes é indicado para bicicletas aro 24, 26 e 29, oferecendo versatilidade para terrenos variados e pedaladas confortáveis. Com braço em aço de 170 mm, proporciona boa resistência e ergonomia ao ciclista. Compatível com caixa de centro padrão de 34,7 mm e pedal com rosca inglesa de 9/16", é ideal para uso com eixo central de ponta quadrada. Fabricado em aço e PVC, alia durabilidade e leveza, com acabamento funcional e sem marcação de logo, atendendo necessidades técnicas e estéticas diversas. Especificações técnicas: Tipo: pedivela triplo Coroas: 24 / 34 / 42 dentes Braço: 170 mm em aço Compatibilidade: bicicletas aro 24, 26 e 29 Caixa do centro: 34,7 mm Rosca do pedal: inglesa 9/16" Fixação: eixo central ponta quadrada Material: aço e PVC Cor: natural aço / preto PVC Marca: GTA', 28.89, 28.89, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/sg-11134201-7rdwn-mci7uhyloitq5b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F990966849%2F44359463684', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
