INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23598220306', 'Conjunto com Blusa e Short para Menina Guloseima', 'Conjunto infantil para menina, com blusa em meia malha e short em moletinho. A blusa é adornada com uma estampa de glitter que traz o adorável rosto de um gatinho acompanhado pela divertida frase Meow World. O short completa o conjunto com um toque de conforto e praticidade.Tecido: Blusa: Meia malha | Short: MoletinhoComposição: Blusa: 96% Viscose e 4% Elastano | Short: 100% AlgodãoModelagem: AmplaComprimento Mangas: CurtaComprimento: CurtoForro: NãoDecote: Redondo', 94.9, 28.47, NULL, 'Baby & Kids Fashion > Girl Clothes > Suits & Sets', 'https://cf.shopee.com.br/file/sg-11134201-7rcdt-m6ige1p5bogr26', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F337974126%2F23598220306', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22093667633', 'Livro O talentoso Ripley Série Ripley Vol. 1, por Patricia Highsmith Intrínseca', 'Clássico de Patricia Highsmith marca o surgimento de um ícone da literatura policial Desde a publicação de O talentoso Ripley, em 1955, e as posteriores adaptações para o cinema — como a estrelada por Matt Damon, em 1999, e a por Andrew Scott, em 2024 —, Tom Ripley conquista fãs ao redor do mundo, sendo reconhecido como um dos maiores sociopatas da literatura. Neste primeiro volume da série de cinco livros que narra sua trajetória, ele tenta se estabelecer em Manhattan, após fugir de seu lar mais do que disfuncional. Bom de lábia, exímio imitador e piadista, praticante de furtos e pequenos golpes, Tom vê sua sorte mudar ao receber uma proposta inusitada. Ele deve ir a uma aldeia na Itália e convencer Dickie Greenleaf, o filho de um rico industrial, a voltar para casa e assumir os negócios da família. O problema é que o vigarista é seduzido pelo estilo de vida refinado do playboy. A relação de amizade entre os dois se complica com a interferência de Marge, a típica boa menina americana, rica e apaixonada por Dickie. Não demora para o fascínio de Tom pela vida de Dickie assumir contornos de obsessão. Quando este percebe o perigo e tenta se afastar, já é tarde demais: Tom vê na rejeição a motivação que faltava para dar vazão aos seus desejos mais sombrios e rouba não só o dinheiro do amigo, mas também sua vida e personalidade. Com O talentoso Ripley, Patricia Highsmith faz a introdução sangrenta e repleta de adrenalina dos percalços desse jovem capaz de tudo para manter seus novos privilégios. Matar ou se reinventar em diversas personalidades não serão empecilhos neste thriller eletrizante, repleto de cenas memoráveis e fugas inesperadas.', 69.9, 55.92, NULL, 'Books & Magazines > Books > Action, Crime & Thrillers', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m533rzcm507k9a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1208017249%2F22093667633', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
