INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22592659818', 'Saco para Lavar Roupa Delicada Pequeno Branco/Rosa Log Ordene', 'O Saco para Lavar Roupa Delicada Pequeno 30,5 x 39 cm Branco/Rosa Log Ordene possui zíper e permite que as roupas delicadas sejam lavadas sem danos. É perfeito para manter as peças protegidas da força da máquina, evita pelos e bolinhas indesejadas, além de garantir que elas fiquem sempre bonitas. É adaptável a qualquer máquina de lavar roupas.', 29.9, 27.9, NULL, 'Home & Living > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rffy-m9692237pf36c3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F816806234%2F22592659818', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22294974779', 'Salsicha Hot Dog Seara', 'A Salsicha Hot Dog Seara é produzida com carnes de qualidade e tem um sabor temperado no ponto certo, perfeita para o seu cachorro-quente e lanches rápidos! Modo de Preparo: Em uma panela, ferva água, após fervura, coloque as salsichas e deixe cozinhar por 3 minutos. Ingredientes: Carne mecanicamente separada de frango, carne suína, carne de frango, água, proteína de soja, pele de frango, fécula de mandioca, sal, dextrose, pimenta-branca, cebola, pimenta-da-Jamaica, açúcar, aromas naturais e aromas idênticos aos naturais, estabilizantes, realçador de sabor glutamato monossódico, antioxidante eritorbato de sódio, corantes: carmim de cochonilha e urucum, conservante nitrito de sódio.', 11.49, 11.49, NULL, 'Food & Beverages > Others', 'https://cf.shopee.com.br/file/sg-11134201-81zwt-miyqaa6s92bm30', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555128%2F22294974779', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23797715469', 'Kit c/6 pacotes de Fralda Descartável Turma Da Mônica Baby.', 'Anúncio referente a 01 pacote jumbinho de fraldas Turma da Mônica baby. Nova Fralda Turma da Mônica Baby com Possui um exclusivo sistema de canal que distribui mais rápido o xixi, barreiras antivazamento e uma fina camada extra que ajuda a manter o bebê sequinho por até 12 horas, além de ter cintura elástica, que proporciona um perfeito ajuste no corpinho, assim ele fica calmo, tranquilo e seguro durante o dia e a noite toda. Tamanhos e as quantidades por cada pacote: ( RN ) Recém nascido = 18 fraldas ( até 4,5 kg ) ( P ) Pequena = 20 fraldas (de 3 à 5 Kg ) ( M ) Média = 18 fraldas (de 4 à 9 Kg ) ( G ) Grande = 16 fraldas (de 7 à 11 Kg ) ( XG ) Extra Grande = 12 fraldas (de 9 à 13 Kg) ( XXG ) EXtra extra grande = 10 fraldas ( de 13 à 17 kg )', 179.8, 179.8, NULL, 'Mom & Baby > Diapering & Potty > Disposable Diapers', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lz4y7jpadq9163', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1295597776%2F23797715469', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13493574161', 'Maleta Mala Para Ferramentas Resistente Anti Impacto Linha Profissional Grande Reforçada Em Alumínio', 'COMERCIAL VIPASA DISTRIBUIDORA. MALETA PARA FERRAMENTAS PROFISSIONAL REFORÇADA ANTI-IMPACTO GRANDE 390X290X120MM A Maleta para Ferramentas Profissional Reforçada Anti-Impacto é a solução ideal para armazenar, organizar e transportar ferramentas com segurança, praticidade e excelente acabamento. Fabricada com estrutura reforçada e revestimento interno em espuma, protege seus equipamentos contra impactos durante o transporte, sendo indicada tanto para uso profissional quanto doméstico. Seu design moderno conta com cantoneiras reforçadas, alça resistente para transporte confortável e fechos de segurança que garantem maior proteção dos itens armazenados. O interior revestido em espuma permite melhor acomodação das ferramentas, reduzindo movimentações e ajudando a preservar equipamentos delicados. Com dimensões de 390 x 290 x 120 mm, oferece excelente espaço interno para ferramentas manuais, instrumentos de medição, equipamentos elétricos de pequeno porte, peças, acessórios e outros utensílios. Ideal para mecânicos, eletricistas, instaladores, técnicos em manutenção, profissionais da construção civil, marceneiros, hobbyistas e qualquer pessoa que necessite transportar ferramentas de forma organizada e segura. Características. Maleta profissional para ferramentas Estrutura reforçada e resistente Sistema interno Anti-Impacto com revestimento em espuma Cantoneiras arredondadas reforçadas Fechos metálicos de segurança Alça resistente para transporte Excelente acabamento Fácil de transportar Ideal para organização e proteção de ferramentas Especificações Técnicas Tipo: Maleta para ferramentas Modelo: Profissional Anti-Impacto Material: Placa de fibra de média densidade (MDF), PVC, metal e espuma Cor: Prata com detalhes em preto Sistema interno: Espuma protetora anti-impacto Fechos: Metálicos com trava Alça: Reforçada Dimensões Comprimento: 390 mm Largura: 290 mm Altura: 120 mm Indicações de Uso Indicada para armazenar e transportar: Ferramentas manuais Furadeiras e parafusadeiras compactas Alicates Chaves de fenda e Phillips Chaves combinadas Soquetes Instrumentos de medição Equipamentos eletrônicos Peças e acessórios diversos Benefícios Protege as ferramentas contra impactos Mantém os equipamentos organizados Facilita o transporte Estrutura resistente e durável Interior revestido em espuma para maior proteção Ideal para uso profissional e doméstico Excelente custo-benefício Conteúdo da Embalagem 1 Maleta para Ferramentas Profissional Anti-Impacto 390 x 290 x 120 mm COMERCIAL VIPASA DISTRIBUIDORA.', 249.99, 239.99, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-820m1-mmdps4zs3u9z44', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F408128510%2F13493574161', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
