INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23196626081', 'V-Floc Shampoo de pH Neutro Concentrado 1,5L Luva Microfibra', 'KIT CONTÉM: V-FLOC 1,5L LUVA DE MICROFIBRA JS ------------------------------------------------------- V-FLOC 1,5L - LAVA AUTOS SUPER CONCENTRADO DESCRIÇÃO: V-Floc é um lava autos de alta performance e de pH neutro. Sua fórmula contém agentes condicionadores e tensoativos especiais que proporcionam uma lavagem suave e eficiente. MODO DE USO: 1. Realizar a pré-lavagem do veículo para retirada do excesso de sujeira 2. Diluir aproximadamente 10ml de V-FLOC em 4 litros de água; Recomendamos ajustar a quantidade de produto de acordo com o nível de sujeira 3. Iniciar a lavagem com o auxílio de Luva de Microfibra, sempre começando pela parte superior do veículo 4. Mergulhar a luva na solução e esfregar suavemente, até completar todo o veículo 5. Enxaguar em seguida até a retirada de todo o produto 6. Recomendamos o uso da Toalha de Secagem para finalizar', 84.8, 84.8, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Shampoo', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lkjj6a2bgep4da', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316945044%2F23196626081', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22098397048', 'Multicortadora oscilante a bateria 20V Sem Bateria - SCT500B Stanley', 'Produto: Multicortadora oscilante a bateria 20V Sem Bateria - SCT500B Marca: Stanley Descrição: A Multicortadora oscilante a bateria 20V Sem Bateria SCT500B da Stanley é uma ferramenta perfeita para diversas aplicações com a mesma ferramenta como: cortar, lixar, desbastar entre outros aplicações." A SCT500B conta com empunhadura lateral de 360"° se adequando a aplicação, conta com troca rápida de acessórios sem chave para uma maior comodidade. Controle de velocidade 8.000-18.000 OPM facilitando o ajuste da velocidade de acordo com acessório, controle máximo sobre uma variedade de aplicações, oferece uma luz LED para iluminar a área de trabalho e melhorar a visibilidade. Características: • Empunhadura Lateral 360 "°: Posicione para se adequar Ã sua aplicação. Maior segurança e conforto para o usuário; • Potente Motor: Cortes mais rápidos para maior rendimento; • Luz Led: Para iluminar a área de trabalho e melhorar a visibilidade após o desligamento; • Mudança de Acessório Sem Chave: Troca rápida de acessório maior comodidade do usuário, melhora a produtividade; • Velocidade Variável 8.000-18.000 OPM: fácil de ajustar a velocidade de acordo com o acessório controle máximo sobre uma variedade de aplicações; • Bateria: 20v íon de lítio (não acompanha). Especificações: Velocidade sem carga: 8.000 - 18.000 OPM Ângulo de oscilação: 1,4 ou 2,8"° Indicador de carga: Sim (bateria) Ajuste de lâmina sem ferramenta: Sim. Não acompanha bateria e carregador. Dimensões (C x L x A): 28.00 x 8.50 x 22.00 centímetros Peso: 1.22 Kg', 652.25, 619.9, NULL, 'Home & Living > Tools & Home Improvement > Others', 'https://cf.shopee.com.br/file/sg-11134201-825a5-mr4x9l0ghds6cb', 'https://shope.ee/an_redir?origin_link=