INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209670950', 'Mini kibe Daki', 'O mini kibe Daki é uma pequena porção de carne moída temperada e trigo para quibe, com uma casca crocante e um recheio suculento e bem condimentado. Sua combinação de sabores inclui carne, cebola, hortelã e especiarias, resultando em uma mordida deliciosa que mistura texturas e aromas. Perfeito como aperitivo ou petisco em eventos, o mini kibe oferece uma amostra saborosa da culinária do Oriente Médio.', 10.99, 10.99, NULL, 'Food & Beverages > Fresh & Frozen Food > Frozen Processed Food', 'https://cf.shopee.com.br/file/sg-11134201-825ah-mqneksqnjw2332', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554945%2F58209670950', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
