INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22193353771', 'O massacre da família Hope', 'Em novo thriller, Riley Sager traz mistério instigante e repleto de reviravoltas sobre o assassinato sem solução de uma famíliaEm 1929, um crime bárbaro chocou o estado do Maine: A abastada família Hope foi brutalmente assassinada, restando apenas a filha mais velha, Lenora, que acabou se tornando a principal suspeita. Apesar de todos acreditarem que a garota foi a responsável pelo massacre, a polícia jamais encontrou provas disso. Daquele dia em diante, Lenora nunca mais falou sobre aquela noite e permaneceu isolada em Hope’s End, a famosa mansão onde o crime ocorreu.Décadas depois, quando a única lembrança do crime é apenas uma perturbadora cantiga infantil, Kit McDeere é designada como cuidadora de Lenora Hope, após a fuga da antiga enfermeira. Aos setenta anos e confinada a uma cadeira de rodas, Lenora perdeu a capacidade de falar, devido a uma série de derrames, e só consegue se comunicar com Kit datilografando frases em uma velha máquina de escrever. Até que, uma noite, Lenora escreve uma frase inesperada: Eu quero te contar tudo À medida que Kit ajuda Lenora a escrever sobre os eventos que levaram ao massacre da família Hope, fica claro que a história é mais complexa do que as pessoas imaginam. Mas quando a cuidadora descobre os detalhes que provocaram a fuga da antiga enfermeira, ela começa a suspeitar que talvez Lenora não esteja dizendo toda a verdade — e que a senhora aparentemente inofensiva sob seus cuidados pode ser muito mais perigosa do que ela pensava.', 62.9, 62.9, NULL, 'Books & Magazines > Books > Comics & Manga', 'https://cf.shopee.com.br/file/sg-11134201-7rdxd-m0eqgg00z4oqdd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F368398259%2F22193353771', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
