INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22898876335', 'Filtro ar Scania 112hw/113h', 'Filtro ar Scania 112hw/113h - Aplicação : O filtro de ar está posicionado na linha de admissão do motor – dentro do compartimento do cofre do motor, geralmente na caixa ou corpo do filtro de ar. Ele é responsável por purificar o ar que entra no motor, evitando o desgaste prematuro de componentes internos. Sempre recomendo que a instalação seja feita por um profissional qualificado para garantir a vedação correta e funcionalidade ideal Veículo : Scania P93H (motor DS9) — a partir de 1995 / Scania R112 EW / 112 HW (motor DSC14 ou DS11) — 1986 a ~1991 Scania R113 H / HK — a partir de 1991 / Scania T112 EW / HW — a partir de 1986 / Scania T113 H / HK — a partir de 1991 Códigos Compatíveis : AP1186 / AP1185 / XL2050 Atenção: Trabalhamos com vários lotes de filtros, onde as marcas podem variar dependendo do lote disponível no momento da compra, todos são de procedência garantida, e de marcas confiáveis, sendo de igual aplicação, apenas a marca que pode mudar mas as peças são de uso igual Acompanha o produto: • 01 un | Filtro ar Scania 112hw/113h', 406.9, 325.52, NULL, 'Spare Parts and Accessories for Vehicles > Heavy Duty and Boats > Spare Parts for Heavy Duty Vehicles', 'https://cf.shopee.com.br/file/sg-11134201-824g6-mea453u8zk0618', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F702541777%2F22898876335', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
