INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58250272017', 'O Morro dos Ventos Uivantes | HQ | Emily Brontë', 'Heathcliff era ainda bem jovem quando foi adotado pela família Earnshaw. Enquanto criava laços afetivos com a geniosa Catherine, era malvisto pelo outro filho do casal, Hindley que ao perder o pai passou a humilhar o irmão adotivo. De tanto sofrimento, a brutalidade e o rancor se tornaram características de Heathcliff. Até que o casamento da bela Catherine com o abastado Edgar Linton aflora os mais negativos sentimentos em Heathcliff, que decide dedicar sua vida a vingar-se daqueles que o maltrataram e o fizeram sofrer. Qual é o limite para uma vingança?96 páginas15,5x22,6 cm', 17.9, 14.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-821e8-mglp6b9l9ngs66', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F58250272017', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
