INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23297989173', 'Esmerilhadeira Angular 7'' EAV 2600 2600W 220V Vonder', 'Esmerilhadeira angular 7", 2.600 W, 220 V~, EAV 2600 VONDER Possui punho auxiliar com três posições de fixação que atua como apoio durante o manuseio da ferramenta, adaptando-se a diferentes situações e locais de uso, muitas vezes de difícil acesso. Conta também com botão de trava do eixo, interruptor com trava de segurança e trava do interruptor e empunhadura ergonômica, que confere maior conforto. Possui ainda dupla isolação, garantindo maior segurança ao operador. Indicada para corte, desbaste e acabamento em superfícies metálicas. Especificações: Modelo: EAV 2600 Potência: 2.600 W Capacidade da esmerilhadeira (disco): 7" - 180 mm Rosca do eixo: M 14 Tipo de velocidade: Fixa Rotação (rpm): 7.800/min Ajuste do cabo da esmerilhadeira: Fixo Número de posições de ajuste do punho: 3 posições Segue norma: ABNT NBR IEC 60745-1 e ABNT NBR IEC 60745-2-3 Tensão (V): 220 V~ Frequência (Hz): 50 Hz / 60 Hz Massa aproximada (peso) (kg): 6.63 kg Observação: Indicada para corte, desbaste e acabamento em superfícies metálicas Recomendações de segurança (avisos/alertas): Utilizar Equipamentos de Proteção Individual, como óculos de proteção, protetor auditivo, respirador para particulados, luvas e avental de raspa. Sempre fazer uma vistoria prévia da ferramenta para detectar possíveis fios desencapados ou alguma irregularidade. Conteúdo da Embalagem: 1 Esmerilhadeira angular. Acompanha: 1 capa de proteção, 1 punho auxiliar e 1 chave dois pinos.', 904.99, 682.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m32974isfaol7e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939446263%2F23297989173', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
