INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22793542498', 'Total Black Bellinzoni | Ativador De Cor Nero Marquina Óleo + Cor marmore e granito cera', 'Total Black Bellinzoni Ativador De Nero Marquina O super ativador de cor Total Black é um poderoso produto de cor preta com alta capacidade de penetração na superfície de mármores ou granito pretos ou escuros. Ativa intensamente a cor do material, eliminando o aspecto cinzento ou “russo” através de uma profunda penetração de pigmentação preta que age rapidamente apenas com a aplicação feita com uma estopa. Proporciona escurecimento de cristais componentes de alguns materiais, dando mais uniformidade à sua cor natural. Protege contra água, óleo e gordura. Restaura ACM Limpa Madeira Total Black Superfícies de Aplicação Bancadas Rodapés Pisos Alisares Finalidade O super ativador de cor Total Black é um poderoso produto de cor preta com alta capacidade de penetração na superfície de mármores ou granito pretos ou escuros. Ativa intensamente a cor do material, eliminando o aspecto cinzento ou “russo” através de uma profunda penetração de pigmentação preta que age rapidamente apenas com a aplicação feita com uma estopa. Proporciona escurecimento de cristais componentes de alguns materiais, dando mais uniformidade à sua cor natural. Protege contra água, óleo e gordura. Instruções de Uso Aplique o Total Black na superfície totalmente limpa, seca, livre de ceras e poeiras, com auxílio de uma estopa ou pano. Espalhe bem o produto de maneira uniforme, no mesmo sentido, cobrindo toda a área a ser tratada. Em caso de excesso, proceda a remoção com flanela, pano ou estopa limpa e seca. Recomenda-se um teste em pequena área antes do uso. Uma vez aplicado o produto, não é possível remover o que a pedra absorveu. Descubra o nosso marketplace - a sua solução para compras online simplificadas! Encontre tudo o que precisa em um único lugar, com conveniência, variedade e qualidade garantidas. Junte-se a nós e comece a explorar agora mesmo!', 657.09, 427.11, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/sg-11134201-7repx-m2tke2mct4ll15', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1190424233%2F22793542498', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
