INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259658410', 'Desinfetante Multisuperficies Veja Power Action Lavanda', 'O desinfetante Veja Power Action Lavanda é um produto de limpeza profunda que vai muito além de apenas perfumar o ambiente. Ele é rigorosamente formulado com ativos de alta eficácia que garantem a eliminação de 99,9% das bactérias e fungos, assegurando um ambiente doméstico verdadeiramente higienizado e protegido para toda a família. Sua ação desengordurante facilita a remoção de sujeiras pesadas em diversas superfícies, como pisos, pias, ralos e vasos sanitários. Além do grande poder germicida, ele deixa no ar uma fragrância de lavanda intensa e prolongada, transformando o clima da casa. A embalagem de 1 litro é ideal para o uso frequente em faxinas completas ou manutenções pesadas.', 14.79, 14.79, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/sg-11134201-8258f-mqneky7zk8ozd3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555041%2F58259658410', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209662248', 'Sabão em Pó Omo Lavagem Perfeita', 'Omo Lavagem Perfeita garante máxima limpeza e cuidado para suas roupas! Sua fórmula com pó ultrafino de rápida dissolução remove as manchas de primeira, sem desgastar os tecidos e ainda cuida das cores. * Garante uma brancura imbatível. * Possui ingredientes biodegradáveis e não possui fosfato. * Embalagem 100% reciclável.', 38.79, 27.9, NULL, 'Home & Living > Home Care Supplies > Laundry Care', 'https://cf.shopee.com.br/file/sg-11134201-82598-mqnekyzlr18gee', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555041%2F58209662248', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
