INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21998089836', '02 Calotas Tampa Central Brw 560 Prata Com Emblema VW', '**Calotas Tampa Central BRW 560 Prata com Emblema VW - Conjunto 02 Unidades** Renove o visual do seu carro com as Calotas Tampa Central BRW 560 Prata, perfeitas para quem busca qualidade, estilo e resistência. Projetadas especialmente para rodas BRW 560, essas calotas oferecem um acabamento impecável e a elegância da cor prata, destacando-se com o emblemático logo VW. **Características:** - **Modelo:** BRW 560 - **Cor:** Prata - **Emblema:** VW (Volkswagen) - **Material:** Plástico de alta qualidade, resistente e durável - **Compatibilidade:** BRW modelo 560 - **Conjunto:** 02 Unidades **Vantagens:** - Design moderno e sofisticado - Facilidade de instalação - Aumenta o apelo estético do seu veículo - Protege a área central da roda contra sujeira e danos Não perca a oportunidade de dar um toque de personalidade ao seu carro com as Calotas Tampa Central BRW 560 Prata com Emblema VW. Perfeitas para quem busca praticidade e estilo. Aproveite agora e renove o visual do seu veículo! **Compre já e transforme o visual das suas rodas!**', 79.99, 79.99, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Wheel Cover', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m79r1ct60xn069', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322429563%2F21998089836', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19254584411', 'Cafeteira Nespresso New Lattissima One Branca para Café Espresso - F121-BR', '19 Bars, Café em Cápsulas, 1 Litro de Capacidade, prepara 08 xícarasA Lattissima One foi pensada para que você desfrute deliciosas receitas com leite, como Cappuccino e Latte Macchiato no conforto de sua casa, com a praticidade que você precisa para o seu momento único com café. Possui um sistema inteligente para preparo da espuma de leite cremosa que leva a simplicidade à um novo patamar. Basta completar o reservatório de leite com a quantidade que deseja em sua bebida, pois a máquina prepara automaticamente o leite cremoso na medida exata e extrai o café na sequência, tudo com apenas um botão. Fácil de limpar, o reservatório de leite pode ser lavado também na máquina de lavar louças. Além disso é a primeira solução de leite extremamente compacta, perfeita para sua cozinha, com design moderno e a praticidade que você precisa para o dia a dia. Características Tipo: Espresso Automática Tipo de Café: Cápsula Capacidade do Reservatório: 01 litro Pressão: 19 Bars Quantidade de Xícaras: 08 Tipos de bebidas: Café Sistema Corta Pingos Bandeja para Resíduos Trava na Tampa Indicador do nível de água Reservatório Removível Desligamento Automático Luz Indicadora de Funcionamento Seletor de Quantidade de Café Tempo de Preparo: 1-2 Min Material: Plástico Especificações Técnicas Modelo: F121-BR-WH-NE (110V) / F121-BR3-WH-NE (220V) Cor: Branco Potência: 1300W (110V) / 1350W (220V) Voltagem: 110V ou 220V (Não é Bivolt) EAN: 7630477884655 (110V) / 7630477884631 (220V) Garantia: 12 meses Dimensões e Peso Dimensões do Produto (AxLxP): 256x154x324 mm Peso do Produto: 4,20 kg Itens Inclusos 01 Cafeteira New Lattissima One 01 Kit de Cápsulas para degustação', 2442.7, 2442.7, NULL, 'Home Appliances > Kitchen Appliances > Coffee Machines & Accessories', 'https://cf.shopee.com.br/file/sg-11134201-22100-7fdqwh78omiv64', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F854082976%2F19254584411', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
