INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18798944594', 'Filtro Ar Condicionado Renault Fluence CES 2109', 'Filtro Ar Condicionado Renault Fluence Qual a importância de trocar o filtro de ar condicionado? A necessidade de trocar o filtro não só existe como é de extrema importância. Afinal, o ar que você respira dentro do carro passa por ali e, quanto mais sujo ou velho ele estiver, pior será a qualidade do ar no interior do carro. O filtro tem a função de reter poeira, fuligem e eliminar qualquer tipo de impureza do ar.', 24.99, 24.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/br-11134207-7r98o-luqpo5trtpidff', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1021060335%2F18798944594', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
