INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '4944336247', 'Pistola De Pintura Hvlp 827 Bico 1.4mm Kit Com 3 Wwsoldas', 'PISTOLA PROFISSIONAL IDEAL PARA PINTURA DE AUTOMÓVEIS E PINTURAS EM GERAL Pistola de Pintura HVLP - MARCA WWSOLDAS Modelo W827 - Permita a seus trabalhos perfeito acabamento, com baixo consumo de ar e economia de tinta. - Bico 1,4mm - Não temos bico extra ou em tamanho diferente - Peças de reposição encontradas, facilmente em assistências e lojas do ramo. - Corpo forjado de alta resistência - Caneca com 600 ml em PVC especial - Com o melhor custo benefício em pistola - Regulagem e cobertura de leque perfeito - Gatilho leve, regulagens macias e tudo durável - Ergonômica, proporciona conforto ao operador - Consumo de ar entre 10 pés cúbicos/minuto - Cobertura perfeita e uniforme das peças pintadas - Trabalha com 30 a no máximo 50 libras de pressão - Baixo consumo de ar com alta produção de pintura - Trabalha com qualquer tipo de compressor acima de 6 pés - Regulagem de abertura e fechamento de leque muito durável - Capa de ar, Bico e Agulha fabricados com material de primeira - Cromada para fácil limpeza, aparência de nova por muito tempo - No primeiro aperto libera apenas ar -No aperto mais forte libera a tinta, duplo estágio Acompanha: - Peneirinha para tinta - 8 furos na base que abrem o leque - 6 furos no bico que estabilizam o leque - 15 furos na capa que organizam todo ar que sai Dimensões: - Altura 35 cm - Largura 10 cm - Comprimento 16 cm - Peso: 650 gramas Garantia de 03 meses contra defeitos de fabricação', 366.45, 299.0, NULL, 'Home & Living > Tools & Home Improvement > Wall Paints & Coatings', 'https://cf.shopee.com.br/file/c73a7b241b7128be35db5ab742c2712a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F283838689%2F4944336247', NULL, NULL, '2026-07-28T02:11:31