INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21198091756', 'Talha Manual de Alavanca 3 Toneladas 3m', 'Talha Manual de Alavanca 3 Ton x 3m – Eficiência e Resistência! A Talha Manual de Alavanca 3 Ton x 3m da Nagano é a escolha perfeita para quem busca desempenho, segurança e durabilidade na elevação de cargas pesadas. Com estrutura robusta em aço de alta resistência, essa ferramenta é essencial para ambientes industriais e operações exigentes. Principais Benefícios: Capacidade de 3 toneladas, ideal para cargas pesadas. Alcance de elevação de 3 metros, ampliando as possibilidades de uso. Design compacto e portátil, perfeito para locais de difícil acesso. Operação eficiente com menor esforço físico do operador. Baixa necessidade de manutenção, reduzindo custos operacionais. Versatilidade para uso em diversos ângulos e condições. Aplicações Indicadas: Construção Civil e Naval Portos e Usinas Mineração e Telecomunicações Indústrias e Manutenção Aumente sua produtividade e trabalhe com mais segurança com a Talha Manual de Alavanca Nagano! Adquira já a sua e garanta eficiência no seu dia a dia! Capacidade: 3TON Elevação: 3M Carga de Teste (kN): 45 Esforço de Acionamento (N): 325 Número de Colunas de Corrente de Carga: 1 Diâmetro da Corrente (mm): 10', 582.8, 582.8, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rd5z-m7kzzbl0tno47e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F427153374%2F21198091756', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
