INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23899312136', 'Kit Cronograma Capilar Para Cabelos Frágeis 500gr Haskell', 'Kit Cronograma Capilar Haskell para Cabelos Frágeis – Hidratação, Nutrição e Reconstrução | 3 Máscaras de 500g O Kit Cronograma Capilar Haskell para Cabelos Frágeis oferece um tratamento completo e intensivo para recuperar, fortalecer e nutrir fios sensibilizados. Com três máscaras poderosas, esse cronograma capilar promove saúde, resistência e beleza aos cabelos, devolvendo vitalidade desde a primeira aplicação. Etapas do Cronograma Capilar para Cabelos Frágeis: HIDRATAÇÃO: Máscara de Tratamento Mandioca – 500g Hidrata profundamente, repõe a água dos fios e melhora a elasticidade. Enriquecida com extrato de mandioca e vitaminas, é ideal para restaurar o brilho e a maciez dos cabelos frágeis. Use na etapa de: hidratação NUTRIÇÃO: Máscara de Tratamento Tutano Vegetal – 500g Nutrição profunda com ação emoliente. Fortalece e repõe os óleos essenciais perdidos, deixando os fios mais resistentes, alinhados e macios sem pesar. Use na etapa de: nutrição RECONSTRUÇÃO: Máscara de Tratamento Cavalo Forte – 500g Reconstrói a fibra capilar e fortalece os fios danificados. Com biotina, pantenol e queratina, aumenta a resistência e auxilia no crescimento saudável dos cabelos frágeis. Use na etapa de: reconstrução Benefícios: • Cabelos mais fortes e resistentes à quebra • Hidratação profunda sem pesar os fios • Nutrição que repõe os lipídios e melhora a maleabilidade • Reconstrução da estrutura capilar • Ideal para cabelos enfraquecidos por agressões químicas, térmicas ou ambientais', 253.7, 253.7, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-8262k-mkb1kfygh7gm13', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1562135680%2F23899312136', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
