INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23799308663', 'Mangueira Do Esguicho Gol Fox Spacefox Orig.Vw Volkswagen', '5Z0955751A Mangueira Do Esguicho Gol Fox Spacefox Orig.Vw Volkswagen. GARANTIA: 90 DIAS - Enviando Normalmente para todo Brasil. Somos a Concessionária DISCAUTOL VEICULOS Autorizada Volkswagen em Campo Grande MS * CONSULTE A COMPATIBILIDADE COM SEU VEÍCULO * Antes de efetuar a compra, envie numero do CHASSI do veículo no campo de perguntas. # O CHASSI é o código de identificação do veículo (como um CPF), que identifica todas as peças compatíveis, composto por 17 caracteres entre letras e números. # Encontre o CHASSI nos vidros, no RENAVAM e / ou próximo ao motor, na carroceria.', 49.73, 49.73, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rdxr-mbwwcq53hb18a4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1663927767%2F23799308663', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18899558513', 'Shampoo Demolidor Cadillac Lavagem Automotiva 500ml', 'DEMOLIDOR 500ML CADILLAC DESCRIÇÃO: Demolidor é o produto perfeito para fazer a pré-lavagem de veículos com sujeira pesada. Este poderoso limpador MOL substitui produtos ácidos e alcalinos, tornando a lavagem muito mais segura. Além disto, seu pH balanceado não agride as superfícies em que será utilizado, aliado a sua espuma de alta densidade remove facilmente sujeiras pesadas, como barro, contaminação ferrosa, fuligem, óleos e gorduras. CARACTERISTICAS: - Espetacular para remoção de sujeiras pesadas. - Diluição de até 1:200. - Substitui produtos ácidos e alcalinos. - Espuma imbatível. MODO DE USO: 1. Agite antes de usar. 2. Com o veículo frio e na sombra, preparar a solução conforme a barra de diluição presente no rótulo. 3. Remover o excesso de detritos com um jato de água. 4. Aplicar a diluição do produto com uma luva, toa miclha derofibra ou canhão de espuma e fazer a esfregação. 5. Enxaguar totalmente e secar', 49.92, 49.92, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Shampoo', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m2e6rujzqztidd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316945044%2F18899558513', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23793011068', 'Vonixx Pano Toalha de Microfibra Automotiva 600gsm Azul', 'TOALHA DE MICROFIBRA 2 LADOS VONIXX DESCRIÇÃO: A Toalha de microfibra 2 lados 600gsm Vonixx possui alta gramatura e proporciona um excelente acabamento. Seu tecido remove camadas de ceras, selantes, aplicação de ceras spray e finalização do polimento sem riscar a pintura TAMANHO: 40x40cm GRAMATURA: 600GSM - NÃO RISCA - SUPER MACIA - ALTA ABSORÇÃO', 55.92, 55.92, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Towels', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lvep05pqprtzbb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316945044%2F23793011068', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
