INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '47402626821', 'ST KUNKKA A-Z Colar Pingente com Letra do Alfabeto Moda Feminina Joias Presente para Aniversário Natal', '👋Bem-vindo à sua próxima declaração de moda! Este deslumbrante colar com pingente de letra em metal é perfeito para presentear ou para seu próprio estilo, adicionando um toque elegante a qualquer roupa!❤️✨ 💎Detalhes do Produto: Feito de liga de metal de alta qualidade, este colar é trabalhado com precisão. O comprimento da corrente é de 45cm + 5cm, adequado para diversos estilos. Escolha qualquer letra de A a Z para um toque único que mostra sua individualidade!😍💖 🎉Adequado para: Seja um presente doce para seu parceiro ou uma surpresa atenciosa para um amigo, este colar é ideal para aniversários, feriados ou gestos do dia a dia. Todos irão apreciar sua intenção sincera!🎁💕 🛒Instruções de Compra: As cores podem variar ligeiramente do produto real. Se você encontrar algum problema, como defeitos ou atrasos, sinta-se à vontade para entrar em contato com nosso atendimento ao cliente—estamos aqui para ajudar!👩‍💻💌', 4.75, 4.0, NULL, 'Fashion Accessories > Necklaces', 'https://cf.shopee.com.br/file/sg-11134201-822ys-mhzrl0wd5q10be', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1672861664%2F47402626821', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
