INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259700526', 'Geladeira Duplex Consul 332 Litros CRD37MB Cycle Defrost Branco - 110V', 'Geladeira Duplex Consul 332 Litros CRD37MB Cycle Defrost Branco - 127VÉ a escolha ideal para quem busca eficiência, organização e praticidade no dia a dia. Com capacidade total de 332 litros, ela oferece espaço interno bem distribuído para armazenar alimentos e bebidas com mais facilidade, atendendo perfeitamente famílias que desejam funcionalidade aliada a um design moderno. Seu acabamento em cor branca combina com diferentes estilos de cozinha, proporcionando um ambiente mais harmonioso e elegante. Equipada com a tecnologia Cycle Defrost, essa geladeira reduz o acúmulo de gelo no freezer, facilitando a limpeza e tornando a manutenção muito mais simples. O modelo conta com freezer superior espaçoso, ideal para manter congelados sempre organizados, além de prateleiras resistentes e removíveis, que permitem melhor aproveitamento interno e adaptação conforme a necessidade. Os compartimentos na porta ajudam a manter garrafas, condimentos e itens de uso frequente sempre ao alcance. Além disso, a Geladeira Consul CRD37MB 127V oferece eficiência energética, contribuindo para economia na conta de luz sem abrir mão do alto desempenho de refrigeração. Seu sistema de resfriamento mantém a temperatura estável, preservando melhor os alimentos por mais tempo. Se você procura uma geladeira duplex confiável, com ótimo espaço interno e recursos que facilitam a rotina, este modelo é uma excelente opção para transformar sua cozinha com mais praticidade e organização.', 2009.78, 2009.78, NULL, 'Home Appliances > Kitchen Appliances > Refrigerators', 'https://cf.shopee.com.br/file/sg-11134201-820mx-mnkf3uoocidcac', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1398462025%2F58259700526', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10401642383', 'Módulo Amplificador Taramps MD 8000 . 1 / 1 Canal 2 Ohms 8000 Watts RMS', 'Mais potência e controle para elevar o desempenho do seu som automotivo. - Envio rápido e produto novo. - Compra segura com garantia de fábrica. - Desenvolvido para quem busca potência, eficiência e excelente qualidade sonora. Benefícios - 8000 Watts RMS: potência elevada para projetos de alto desempenho. - Full Range: reproduz graves, médios e agudos com ampla resposta de frequência. - Classe D: excelente eficiência energética com menor aquecimento. - Ajustes completos: HPF, LPF, Gain e Bass Boost para melhor configuração do sistema. - Proteções eletrônicas: contra curto-circuito, baixa impedância, tensão e superaquecimento. Especificações Técnicas - Marca: Taramps - Modelo: MD 8000.1 - Versão: 2 Ohms - Classe de operação: D - Número de canais: 1 (Mono) - Potência nominal: 8000W RMS em 2 Ohms @12,6V - Resposta de frequência: 10Hz a 10kHz (-3dB) - Sensibilidade de entrada: 220mV - Relação sinal/ruído: superior a 90dB - Eficiência: 87% - Alimentação: 9VDC a 16VDC - Sistema de proteção: curto na saída, baixa impedância, proteção térmica e tensão alta/baixa - Dimensões: 228 × 70 × 419 mm - Peso: 6,10 kg Você receberá 1 Módulo Amplificador Taramps MD 8000.1 2 Ohms Produto novo Manual do fabricante Embalagem segura Garanta agora o seu e monte um sistema de som automotivo com potência e desempenho de alto nível.', 1352.7, 1352.7, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/sg-11134201-825bb-mqdozwxelhxdb2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341544056%2F10401642383', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
