INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22598194858', 'Ventilador de Coluna Ventisol Steel 50cm Preto - Bivolt', 'Ventilador de Coluna Ventisol Steel 50cm Preto Bivolt Descubra a combinação perfeita entre design e eficiência com o Ventilador de Coluna Ventisol Steel 50cm Preto Bivolt. Equipado com um motor turbo potente e hélices de 6 pás, este ventilador oferece um fluxo de ar poderoso e silencioso, ideal para manter a sua casa fresca e confortável durante os dias mais quentes. Sua altura ajustável permite que você direcione o vento na altura ideal, enquanto a função oscilante garante uma distribuição uniforme do ar em todo o ambiente. A estrutura robusta com grades em aço não apenas proporciona durabilidade e segurança, mas também confere um toque de sofisticação ao design. Com a opção de regulagem de velocidade, você pode personalizar a intensidade do vento de acordo com suas preferências e necessidades. Seja para uma noite tranquila de sono ou para um dia agitado, o Ventilador de Coluna Ventisol Steel é a escolha perfeita para uma experiência de resfriamento eficiente e estilosa.', 346.32, 346.32, NULL, 'Home Appliances > Large Household Appliances > Cooling', 'https://cf.shopee.com.br/file/sg-11134201-7rdwt-mdbrwjbqrbkk4a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1398462025%2F22598194858', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22093949136', 'Quintessencia | A Lei da Atração Acelerada | William Sanches', 'VOCÊ NÃO TEM COMO FUGIR!A Lei da Atração está agindo com ou sem você saber ou mesmo acreditar nela.Você tem duas escolhas agora: entender e fazer o uso correto dessa Lei Universal ou continuar permitindo que seu inconsciente crie a realidade que você não quer viver!Neste livro, William Sanches desvenda todos os segredos da Lei da Atração e ensina como acelerar esse processo para que você alcance os seus objetivos o quanto antes.Imagine que você pode escolher fazer uma viagem longa de ônibus ou pegar um avião. Com qual deles você chega mais rápido?Este livro é sua passagem de avião rumo aos seus desejos!Quintessência: Lei da Atração Acelerada desvenda cinco princípios poderosos para conquistar qualquer sonho em tempo recorde!Acredite: a vida dos seus sonhos é possível e já está disponível!O caminho para isso você encontra aqui! 23x16 cm 424 Páginas', 57.9, 53.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7reoo-m8s827sbk0ntf9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F22093949136', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49054135203', 'Journal da Garota Corajosa | Um Guia Prático para sua Caminhada de Fé | Capa Dura', 'Enquanto as histórias apresentadas em Corajosas 1 e Corajosas 2 revelam, por meio da ficção, o que nós, Arlene, Queren, Maria e Thaís, aprendemos a respeito de Cristo e como esse aprendizado impacta e molda nossa vida, neste journal damos um passo ainda mais ousado e significativo. As lições das princesas transformam-se, aqui, em exemplos práticos que ajudarão você a descobrir como ter coragem para: Conhecer sua fé e viver por ela Ser quem Deus criou você para ser Proteger seu coração Abraçar seu propósito Gostar do que vê no espelho Viver bons relacionamentos Enfrentar os desafios de um mundo nada encantado Perseverar nessa longa jornada chamada vida Este não é um guia com respostas prontas, mas um convite para reflexão e aprendizagem. É como sentar à mesa com uma amiga em uma cafeteria. O café soltando fumacinha, as canetas coloridas escapando do estojo, caderninhos abertos e uma conversa que faz o coração ficar quentinho. Vamos lá? Livro capa dura, páginas internas totalmente coloridas e seções interativas com espaço para anotação. Contém duas cartelas de adesivos. 24X16 CM 208 Páginas', 71.9, 62.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-81zvs-mj2lzw16go3l99', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F49054135203', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
