INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58203128930', 'Ar Condicionado Split Inverter 12000 BTUs Midea IA Ecomaster Quente/Frio 42EZVQA12M5 - 220V', 'Ar Condicionado Split Inverter Hi Wall Midea IA Ecomaster 12000 BTUs Quente/Frio 42EZVQA12M5 - 220V O Ar Condicionado Split Inverter Hi Wall Midea IA Ecomaster 12.000 BTUs Quente/Frio 42EZVQA12M5 é a escolha ideal para quem deseja uma climatização eficiente e econômica o ano inteiro. Com 12.000 BTUs de potência, ele é perfeito para ambientes de tamanho médio, oferecendo tanto resfriamento no verão quanto aquecimento no inverno. A tecnologia Inverter proporciona um ajuste contínuo da velocidade do compressor, resultando em menor consumo de energia e um funcionamento mais silencioso. Além de sua eficiência energética, o Midea IA Ecomaster 42EZVQA12M5 se destaca pelo design moderno e compacto, que se adapta facilmente a diferentes tipos de ambientes. Seu funcionamento silencioso garante um clima confortável e agradável, sem perturbar o ambiente. Ideal para residências, escritórios e pequenos estabelecimentos comerciais, este ar-condicionado proporciona o máximo de conforto durante todas as estações. A instalação e manutenção do Ar Condicionado Midea 12.000 BTUs Quente/Frio são práticas e simples, garantindo conveniência e durabilidade. Sua excelente relação custo-benefício, somada à sua versatilidade e desempenho superior, fazem deste modelo uma opção inteligente para quem busca um sistema de climatização que alie conforto, eficiência e economia. O Midea IA Ecomaster 42EZVQA12M5 é a solução ideal para um ambiente agradável e controlado em todas as estações.', 3042.39, 3042.39, NULL, 'Home Appliances > Large Household Appliances > Cooling', 'https://cf.shopee.com.br/file/sg-11134201-8260z-mjeamw803c3le0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%