INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21699884756', 'Mangueira Pressostato Conector Reto 100cm 1/4 Sae Hulter', 'Mangueira Pressostato Conector Reto 100cm 1/4 Sae HulterMangueira Pressostato Conector Reto 100cm 1/4 SAE Hulter é um acessório indispensável para garantir segurança e eficiência em sistemas de refrigeração e ar-condicionado. Com 100cm de comprimento, ela oferece flexibilidade ideal para a instalação, manutenção e medições, assegurando um encaixe preciso e confiável. Seu modelo 1/4 SAE é compatível com diversos equipamentos, proporcionando praticidade e desempenho de alto nível. Produzida com materiais de qualidade, a mangueira Hulter foi desenvolvida para suportar as condições exigidas durante o trabalho, mantendo a durabilidade e evitando vazamentos. O conector reto facilita o manuseio em espaços reduzidos, tornando as operações mais ágeis e seguras. Além disso, o projeto garante estanqueidade e preserva o funcionamento adequado dos equipamentos, reduzindo riscos de falhas e retrabalhos. Com garantia de 3 meses, a Mangueira Pressostato Hulter 1/4 SAE é uma escolha confiável para quem deseja praticidade e desempenho.', 69.9, 69.9, NULL, 'Home Appliances > Large Household Appliances > Cooling', 'https://cf.shopee.com.br/file/sg-11134201-824je-mf4dbd49cxzjd6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1398462025%2F21699884756', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
