INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23593742875', 'Mulherzinhas | Louisa May Alcott', 'Jo, Beth, Meg e Amy são quatro irmãs que moram em Massachusetts e passam o primeiro Natal sem o pai, que está servindo na Guerra Civil Americana. Enfrentando dificuldades financeiras, a mãe, Marme e March, sustenta a família. Em meio a desafios, as irmãs, que são tão diferentes entre si, precisam se unir para aprenderem juntas. Enquanto os anos passam, elas ingressam na vida adulta e lutam, cada uma, por seus sonhos e ambições. É um romance que não foge do cotidiano, mas o aborda com firmeza, humor e sensibilidade, defendendo as virtudes, o protagonismo da mulher e as realizações pessoais. Mulherzinhas é o primeiro de uma série de quatro livros que acompanham a vida das irmãs March, seguido por Boas Esposas, Rapazinhos e Os meninos de Jo. 16x23cm 256 Páginas', 19.35, 14.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rd6n-m6txfxsuzpec0f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F23593742875', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22199039768', 'Sherlock Holmes | um Escândalo na Boêmia | Capa Dura', 'A Scandal in Bohemia é um conto policial de Sir Arthur Conan Doyle protagonizado por Sherlock Holmes e publicado pela primeira vez na Strand Magazine em Julho de 1891. É conhecido por ser o primeiro caso que Sherlock Holmes perdeu. 14x21cm 94 Páginas', 14.9, 11.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-824ip-mfp9a3cz9afj29', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F22199039768', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22092409521', 'Cárdia: o Resgate das Virtudes Perdidas | Paulo Debs', 'Uma terra misteriosa; uma terrível maldição; um povo em busca de um herói. Prepare-se para fazer parte desta aventura que poderá custar sua própria vida. Enigmas, desafios e grandes batalhas serão vividos por aquele que se aventurar por Cárdia. Então, bravo leitor, preparado para enfrentar o mal que domina esta terra? O verdadeiro herói é aquele que muda o curso de uma história.', 39.9, 35.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rbke-lls146snseux93', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F22092409521', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '5250993853', 'Microfone sem fio Duplo de Mão Vokal vws20 Plus', 'Somos Loja Especializada em Instrumentos Musicais a mais de 10 anos no mercado. Nosso Lema é qualidade e preço justo. Nosso portfólio é cuidadosamente selecionado para oferecer os melhores produtos do mercado. Venha fazer parte da nossa História, será sempre um prazer te atender. Com os seus microfones Vokal você descobrirá uma nova maneira de capturar e transmitir áudio. Além disso, você poderá melhorar suas funções e dar-lhe um uso conveniente com seus acessórios incluídos. Compacto e eficiente Este produto destaca-se pela sua versatilidade e adaptação: grava o som da sua voz com excelente qualidade e sensibilidade. Um formato a sua medida Seu dinamismo o torna ideal para vocalistas e instrumentos. É leve para uso manual e se encaixa em todos os tipos de pés ou suportes. Sem necessidade de fonte de alimentação, ele lhe dará um alto grau de autonomia para uso externo e interno. Desenho eficiente Seu padrão polar cardioide oferece maior sensibilidade aos sons frontais, o que evita o ruído proveniente das costas. Características principais Marca Vokal Modelo VWS-20 Plus Outras características Formatos: De mão Tipos de microfone: Dinâmico Padrões polares: Cardióide Quantidade de microfones: 2 É sem fio: Sim Frequência mínima - Frequência máxima: 40 Hz - 20 kHz Inclui acessórios: Sim Acessórios incluídos: Recibidor Conectores de saída: Jack 6.3 mm', 336.17, 336.17, NULL, 'Audio > Microphones', 'https://cf.shopee.com.br/file/9a223559f248e06dc9e187c1f3ccf294', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F302241610%2F5250993853', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '53307516118', '52 Reflexões sobre Como parar de se preocupar e começar a viver | Dale Carnegie', 'A PREOCUPAÇÃO É UMA LADRA SILENCIOSA DE ENERGIA, SONO E ALEGRIA. Inspirado no clássico de Dale Carnegie, este livro apresenta 52 reflexões para libertar a mente do excesso de ansiedade e reencontrar o equilíbrio interior. Com uma leitura simples e transformadora, Sam Buttler adapta os princípios de Carnegie à vida moderna: viver um dia de cada vez, aceitar o inevitável, cultivar fé, gratidão e coragem diante das incertezas. A vida acontece hoje. Escolha viver o presente com leveza e propósito. 15x22cm 96 Páginas', 16.9, 12.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-82600-mm3is51yt0xwe5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F53307516118', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10185627236', 'Por Que Sou Cristão | John Stott', 'Muitos anos atrás, um garoto solitário foi a uma pequena e escura capela em busca de Deus. Mais tarde, entregou a sua vida a Cristo. Essa acabou sendo a decisão mais importante de toda a sua vida. Se não fosse por Cristo — ele reflete — sua vida seria mais uma na lata de lixo das vidas perdidas e descartadas. Em vez disso, sua vida tem sido usada para conduzir muitos outros à nova vida e a um entendimento mais profundo daquele que deu a sua vida para que nós vivêssemos. Agora ele conta a sua história espiritual e dá as razões da sua mudança de vida, do seu primeiro passo de fé no caminho que tem seguido desde então. Para John Stott, não foi ele que encontrou Cristo, mas Cristo o encontrou. Ele tornou-se cristão não porque a fé cristã é atrativa, mas porque é verdadeira; não porque merecesse ser salvo, mas porque Cristo tomou os seus pecados — e os de cada um de nós — sobre si mesmo. Por Que Sou Cristão mostra que a resposta para o paradoxo existente no coração humano e a chave para a verdadeira liberdade e plenitude só podem ser encontradas em Cristo. E ele faz o maior de todos os convites a cada um de nós e espera pacientemente a nossa resposta. 14x21cm', 35.9, 35.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/ae115a8f68b36dd4042404457c1abc70', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F10185627236', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
