INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18798341667', 'Par de Amortecedores Tras Gás Onix 16/19 19526953 ACDelco', 'LOJA OFICIAL NOVA CHEVROLET GM NOVA CHEVROLET, QUALIDADE E CONFIANÇA AO SEU ALCANCE! Especificação Técnica: Garantia: 90 dias Marca: ACDelco Código de referência: 19526953 Valor: Unitário Produto: Novo Aplicação do produto: Chevrolet Onix (2016-2019) Conteúdo da Embalagem: 1 par de amortecedores traseiros a gás Importante: A Garantia da Nova Chevrolet não cobre má instalação ou mau uso do produto. Recomendamos que a instalação seja feita por um profissional especializado. Compre no CPF, pois no CNPJ terá o custo de ICMS por conta do comprador. Observações e Condições da Loja: Antes de comprar, tire suas dúvidas nas perguntas. Todos os nossos produtos são novos e acompanham garantia. Todas as vendas incluem nota fiscal eletrônica. Confirme as aplicações técnicas com seu mecânico. Não entregamos em Caixa Postal dos Correios. Compre no CPF, pois no CNPJ terá o custo de ICMS pago pelo cliente. Mantenha seus dados pessoais atualizados no site. Receba o produto garantido ou dinheiro de volta. Economize adicionando vários produtos no carrinho. Todos os produtos anunciados têm pronta entrega. O vendedor não tem autonomia sobre as entregas. Compra errada não tem troca, apenas devolução.', 410.96, 410.96, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mg2asbffa8ef04', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F422105437%2F18798341667', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
