INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22891684233', 'Par Amortecedor Porta Malas Tampa Traseira Amortecedores Traseiros Para Kwid 2018 A Diante', 'O amortecedor de porta malas é um item de extrema importância para os veículos, tanto para sua comodidade ao colocar bagagens no porta malas, quanto para sua segurança. Não hesite em fazer a substituição desse item, pois sua instalação pode ser feita com muita facilidade. ****A MARCA DA MERCADORIA VAI DE ACORDO COM A DISPONIBILIDADE EM NOSSO ESTOQUE (CINOY OU APX)**** Características do produto: - Compatível com Parati G2, G3, G4 de 1996 em diante - Comprimento: 59CM Especificações Gerais: - Fabricado em aço e ferro; - Mola (pressurização) a gás; - Força de expansão ou abertura 40 kg. Conteúdo da Embalagem: - 2 Amortecedores de Porta Malas Parati G2, G3, G4 de 1996 em diante Avisos Importantes: - Garantia: 3 meses; - Valor do Par; - Imagens Meramente Ilustrativas. Dúvidas Frequentes: • Os produtos são novos? R: Só trabalhamos com produtos novos e com garantia. • Como funciona a garantia? R: Nossos produtos têm uma etiqueta de garantia para nosso controle interno, com essa etiqueta verificamos se o produto é nosso mesmo, portanto NÃO tire a etiqueta do produto. • O produto está disponível a pronta entrega? R: Sim, todos os nossos produtos estão no nosso estoque preparado para ser embalado e enviado pra você!', 89.9, 85.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/br-11134207-7qukw-lisobkvo2vjpa6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341544056%2F22891684233', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
