INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23799160417', 'Alarme Automotivo Positron Cyber FX360', 'Quando pensamos em segurança automotiva para proteção do veículo, a primeira coisa é ter um alarme de qualidade, o Cyber FX 360 trás diversas funcionalidades e com tecnologia de ponta para você. Vale o destaque na função modo assalto por presença, onde em caso de assalto você pode ativar o alarme com a ignição ligada, deixando o veículo se afastar do controle remoto. As setas do veículo piscarão e a sirene dispara, e acontece o bloqueio progressivo do motor de partida ou bomba de combustível. A Pósitron é referência em alarmes e segurança para seu carro! Conhecida pela inovação em seus produtos, serviços e referência no desenvolvimento de soluções tecnológicas em rastreamento e segurança eletrônica. Especificações Técnicas: - Compatível 100% com veículos - Função modo assalto por presença - Bloqueio progressivo do motor de partida ou bomba de combustível - Função pânico - Sistema Pósitron anticlonagem - Exclusiva Tecnologia PAN (Pósitron Area Network) - Exclusivo controle remoto com tecnologia ASIC (Application Specific Integrated Circuit) - Sirene com volume de som mais alto - Desativação temporária dos sensores de ultrasom Conteúdo da embalagem: - 2 Controles PXN72 - 1 Sirene - 1 Módulo - 1 Botão Secreto - 1 Manual de Instalação', 460.5, 322.35, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Safety > Alarms and Accessories', 'https://cf.shopee.com.br/file/sg-11134201-821e1-mgsa6jn6w170b7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1452490205%2F23799160417', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
