INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22994076387', 'New Show Pinça Aço Reta De Alta Precisão Para Cílios De Inoxidável Ponta Curva/ROSA/Profissionalismo', 'Descrição do produto BEM VINDO NewShow Oficial A ponta reta e extrafina oferece maior precisão no momento de isolar os pelos, assim você consegue selecioná-los com rapidez evitando colar em pelos indesejados, garantindo que seu trabalho fique perfeito. Essa pinça é feita de aço inoxidável, que tem alta resistência a oxidação e pode ser higienizada com álcool 70%. Higienize com delicadeza para evitar que a cor descasque e guarde as pinças separadamente em um estojo. Apesar de ser uma ferramenta profissional robusta, evite ao máximo quedas para que a pinça não perca sua precisão. INFORMAÇÕES TÉCNICAS: - Marca: NewShow - Modelo；Flamingo - Cor: Furta cor; - Tamanho: 12,5cm; - Material: Aço inoxidável. qualquer duvida chamar no chat.', 20.0, 10.99, NULL, 'Beauty > Beauty Tools > Hair Removal Tools', 'https://cf.shopee.com.br/file/br-11134207-7r98o-md215jt1vfaq62', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1430626556%2F22994076387', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
