INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22698410968', 'Kit Elseve Shampoo 375ml + Condicionador 170ml Liso dos Sonhos', 'Kit Elseve Shampoo 375ml + Condicionador 170ml Liso dos SonhosO Kit Elseve Liso dos Sonhos, da L''Oréal Paris, é ideal para quem deseja fios longos, alinhados e sem frizz. Composto por shampoo e condicionador, sua fórmula com Queratina Vegetal Líquida e Manteiga de Cacau trata o cabelo da raiz às pontas, proporcionando hidratação, maciez e controle do frizz por até 48 horas.Benefícios:- Controle de frizz por até 48h- Efeito desmaia fios- Hidratação e nutrição intensa- Fios alinhados e macios- Ideal para cabelos lisos e longosModo de uso:Aplique o shampoo nos cabelos molhados, massageie suavemente e enxágue. Se necessário, repita. Em seguida, aplique o condicionador no comprimento e pontas, deixe agir por alguns minutos e enxágue completamente.', 51.06, 51.06, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7ren9-m8mfmg4gfbm964', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F22698410968', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
