INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23296962834', 'Condicionador Forever Liss Desmaia Cabelo 300g', 'O Condicionador Ultra Hidratante Desmaia Cabelo de Forever Liss, é anti frizz e redutor de volume. Age deixando as cutículas seladas com a porosidade reduzida dos fios, possui consistência emoliente, garantindo brilho e maciez devido aos ativos D-Pantenol, Keratina brasileira, Colágeno e Sinergia de Aminoácidos. Modo de uso: Após o uso do Shampoo, aplique o Condicionador nos cabelos molhados, massageando-os. Deixe agir por 2 minutos. Enxague completamente, retire o excesso de água. Deixe secar naturalmente ou se preferir secar os fios com ondas de calor (secador ou prancha).', 44.88, 44.88, NULL, 'Beauty > Hair Care > Hair and Scalp Conditioner', 'https://cf.shopee.com.br/file/sg-11134201-7rblo-lm63052s9k15e3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F23296962834', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
