INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23994278255', 'Ar Condicionado Split Smart Inverter Hi Wall LG + IA 12000 BTUs Frio S3UQ12JA31E.EB2GAM1 - 220V', 'Ar Condicionado Split Hi Wall LG AI Smart Inverter Voice 12000 BTUs Frio S3UQ12JA31E.EB2GAM1 - 220VO Ar Condicionado Split Hi Wall LG AI Smart Inverter Voice 12000 BTUs é a escolha ideal para quem busca tecnologia, economia e praticidade em um único aparelho. Com inteligência artificial integrada, ele aprende os hábitos de uso e ajusta automaticamente a temperatura e a velocidade do vento, proporcionando um ambiente sempre agradável e adaptado às suas preferências. Além disso, seu baixo nível de ruído garante conforto e bem-estar durante qualquer atividade, seja para dormir, trabalhar ou relaxar. Outro grande diferencial está na conectividade avançada, já que o modelo conta com Wi-Fi integrado e pode ser controlado pelo aplicativo LG ThinQ, além de oferecer compatibilidade com os principais assistentes de voz, como Google Assistente e Amazon Alexa. Assim, você pode ajustar as funções do ar-condicionado com apenas um comando de voz ou diretamente pelo smartphone, trazendo muito mais comodidade para o seu dia a dia. Para completar, este aparelho foi projetado para garantir durabilidade e eficiência. Ele possui proteção anticorrosiva GoldFin, que aumenta a vida útil mesmo em regiões litorâneas, além de um gabinete de metal resistente e sistema de proteção contra picos de energia de até 450V. Com o Controle de Energia 4 em 1, é possível reduzir o consumo em diferentes níveis, permitindo climatização de qualidade com economia. Tudo isso faz do LG AI Smart Inverter uma solução confiável, moderna e inteligente para o seu ambiente.', 3042.39, 3042.39, NULL, 'Home Appliances > Large Household Appliances > Cooling', 'https://cf.shopee.com.br/file/sg-11134201-7rdw6-mbqdfmnf6