INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23794235296', 'Jogo Lanche 3 Peças Oxford Flat Ônix', 'Linha Flat da Oxford, perfeita para empratamentos criativos com maior área de uso. As peças foram inspiradas na pedra Ônix. Peças com acabamento acetinado podem apresentar marcas superficiais de uso. Para removê-las, recomenda-se a limpeza com o lado abrasivo da esponja, com movimentos suaves e detergente neutro. Conteúdo da embalagem: 1 Tigela Flat de 600ml e 16,5 cm de diâmetro / 1 Prato Sobremesa 20Cm / 1 Caneca 350Ml - Garantia: 3 Meses para Defeitos de fabricação - Marca: Oxford - Tipo da embalagem: Papelão pardo - Material: Cerâmica - Cor: Preto - Nome do Desenho: Ônix - Forma: Redondo - Tipo: Lanche - Linha: Flat - Modelo: Ônix - Unidades por kit: 3 - É apto para lava-louças: Sim - É Apto para microondas: Sim - Formato de venda: Kit - Código universal de produto: 7891361334087 - SKU: KIT192 - Utilizações Seguras: Resistente ao micro-ondas, Resistente a lava-louças - Condição do item: Novo - Unidades por kit: 3 - É kit: Sim - Tipo de garantia: Garantia do fabricante - País de origem: Brasil - Duração de garantia: 3 meses - É kit de fábrica: Sim ATENÇÃO: Para compras de pessoa jurídica,cadastreosdados exatamente como consta em seu cartão do CNPJ', 148.17, 148.17, NULL, 'Home & Living > Kitchenware > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rdx5-mci6vc7zz63783', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1075271269%2F23794235296', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58200217640', 'Kit De Tratamento Murumuru Haskell 500g | Nutrição Intensa', 'Kit Haskell Murumuru Nutrição Intensa – para Cabelos Muito Secos Contém: Shampoo 500ml + Condicionador 500ml + Manteiga Nutritiva 500g O Kit Profissional Haskell Murumuru Nutrição Intensa é a escolha ideal para cabelos extremamente secos, desidratados e sem vida. Com ativos naturais da Amazônia, como o poderoso Murumuru, este kit foi desenvolvido para restaurar profundamente a saúde dos fios, garantindo nutrição completa desde a raiz até as pontas. Sua fórmula rica em ácidos graxos e vitaminas penetra na fibra capilar, promovendo reposição lipídica, brilho intenso e maleabilidade, enquanto combate o ressecamento e devolve a vitalidade dos fios. A versão profissional com embalagens maiores é perfeita para uso prolongado ou para salões de beleza. Benefícios: Nutrição profunda e duradoura Brilho intenso e maciez Redução do ressecamento extremo Fortalecimento da fibra capilar Cabelos com mais balanço e vitalidade O Kit Contém: Shampoo Murumuru 500ml: limpeza eficaz com reposição de nutrientes e vitaminas essenciais para fios saudáveis. Condicionador Murumuru 500ml: ação hidratante que sela as cutículas e nutre profundamente. Manteiga Nutritiva Murumuru 500g: tratamento intensivo com alto poder de nutrição, elimina o aspecto opaco e ressecado dos fios. Indicação: cabelos muito secos Direção olfativa: oriental, frutal, amadeirado, ambarado', 209.8, 209.8, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-821fd-mgi2q77mkr2n71', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1562135680%2F58200217640', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
