INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23791200430', 'Kit 3 Jogo De Talheres Tramontina Churrasco Jumbo 12 Peças', 'Jogo De Talheres Tramontina Churrasco Jumbo 36 Peças Para saborear aquele churrasco especial com a família e os amigos, conte com o jogo para churrasco Tramontina Dynamic com lâminas em aço inox e cabos de madeira natural 36 peças. Desenvolvido para lhe proporcionar praticidade e beleza à sua mesa, ele tem peças produzidas com lâminas em aço inox, onde as facas tem maior durabilidade em seu fio de corte devido ao tratamento térmico e os garfos contam com maior resistência devido a estampagem. Seus cabos são em madeira natural e contam com rebites de alumínio que os deixam com um belíssimo design. Escolha seu corte de carne preferido e compartilhe sua mesa com a Tramontina! Descrição do produto Composição: 18 Garfos e 18 Facas Lâminas de aço inox As lâminas das facas têm maior durabilidade do fio devido ao tratamento térmico As lâminas dos garfos conta com maior espessura e uma estampagem do aço que garante maior resistência, evitando deformações Cabos de madeira natural Rebites de alumínio Antes da primeira utilização, lave bem as peças e seque-as Tenha cuidado ao manusear produtos cortantes e perfurantes e mantenha-os fora do alcance de crianças Para maior durabilidade dos produtos, recomenda-se secar bem antes de guardar Para descarte dos produtos e embalagens siga as orientações de reciclagem vigentes Peso Líquido: 2,1 kg. Peso Bruto: 3 kg. Dimensões Embalagem (Compr. X Larg. X Alt.): 445x 270x 120 mm Imagens meramente ilustrativas, todos os itens que a', 722.06, 449.38, NULL, 'Home & Living > Dinnerware > Cutleries', 'https://cf.shopee.com.br/file/sg-11134201-7qve5-lgpewmd696kg02', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F638399297%2F23791200430', NULL, NULL,