INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22094204528', 'Forno Elétrico Fogatti 50 Litros Preto I50 220V', 'Qualidade e design à altura da sua cozinha.Com capacidade de 50 litros, este forno elétrico é ideal para quem busca praticidade, desempenho e um visual moderno para a cozinha. Compacto e funcional, possui acabamento interno com revestimento antiaderente, painel manual e porta com abertura frontal em 2 estágios, que oferece mais segurança no manuseio. Acompanha bandeja interna que pode ser usada como assadeira e grade com 3 níveis de ajuste de altura, proporcionando mais versatilidade no preparo das suas receitas. Capacidade: 50 Litros Tipo de instalação: bancada Painel manual Design moderno, prático e compacto Porta com abertura frontal em 2 estágios para maior segurança Bandeja interna multifuncional (pode ser usada como assadeira) Luz piloto: indica se o forno está ligado Função Grill / Dourador Termostato com controle de temperatura até 250 °C Controle automático de temperatura Isolamento térmico Bandeja para resíduos Pés antiderrapantes Timer de até 120 minutos Chave seletora com 4 funções Revestimento interno antiaderente Grade com 3 níveis de ajuste de altura Especificações Técnicas I50-220: Tensão: 220 V Corrente: 8 A (220 V) Frequência: 60 Hz Potência resistência superior: 700 W Potência resistência inferior: 1000 W Potência total: 1700 W Consumo: 1,2 kWh Cor: Preto Dimensões externas (L x A x P): 52,0 x 37,8 x 43,7 cm Dimensões internas (L x A x P): 40,0 x 32,0 x 37,3 cm Dimensões da embalagem (L x A x P): 57,0 x 43,5 x 47,5 c Peso bruto: 9,92 kg Peso líquido: 8,36 kg Tomada para fornos 220 V: 10 A Espaço interno: 40 Litros Itens Inclusos:1 Forno Elétrico, 1 Grade Interna, 1 Bandeja Interna, 1 Bandeja para Resíduos e 1 Manual de Instruções.', 469.0, 469.0, NULL, 'Home Appliances > Kitchen Appliances > 