INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23997554614', 'Kit 40 und Sabonete Lux Botanicals Buquê De Jasmim 85g', 'Lux Sabonete em Barra Buquê De Jasmim : Fragrância Floral para uma Experiência Luxuosa Descrição do Produto: Lux Sabonete em Barra Buquê De Jasmim é formulado com glicerina e extratos naturais de rosas, proporcionando uma limpeza delicada e eficaz, enquanto deixa a pele suavemente perfumada com a fragrância luxuosa de rosas francesas. Cada barra é envolvida em um delicado envoltório, garantindo sua qualidade e frescor até o momento de uso. Benefícios para a Pele: Fragrância envolvente:A fragrância floral proporciona uma experiência sensorial única durante o banho, deixando a pele perfumada e revigorada. Hidratação suave:A fórmula enriquecida com glicerina ajuda a manter a pele hidratada e macia, mesmo após o uso. Limpeza delicada:Os ingredientes suaves garantem uma limpeza eficaz sem ressecar a pele, deixando-a limpa e refrescante. Envoltório protetor:Cada barra de sabonete é cuidadosamente envolvida em um envoltório protetor, garantindo sua integridade e frescor até o momento de uso. Instruções de Uso: Massagear Sobre A Pele Molhada Até Formar Espuma. Enxágue Em Seguida. Advertências Importantes: Uso externo. Mantenha fora do alcance de crianças. Evite o contato com os olhos. Em caso de contato, enxágue abundantemente com água. Em caso de irritação, suspenda o uso e consulte um médico. Composição: Sodium stearate, sodium oleate, sodium palmitate, sodium linoleate, sodium laurate, sodium myristate, aqua, glycerin, parfum, sodium citrate, sodium chloride, citric acid, titanium dioxide, tetrasodium EDTA, etidronic acid, DMDM hydantoin, CI 12490, sericin, jasminum officinale flower extract, rosa gallica flower extract, nelumbium speciosum flower oil, prunus amygdalus dulcis oil, cymbopogon martini oil, mentha arvensis leaf oil, alpha-isomethyl ionone, citronellol, coumarin, geraniol, hexyl cinnamal. Linalool.', 120.9, 120.9, NULL, 'Beauty > Bath & Body Care > Body Wash & Soap', 'https://cf.shopee.com.br/file/sg-11134201-7rd3w-lw34ao0h629yd8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045085918%2F23997554614', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
