INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '9544456820', 'Kit 2 Borracha De Porta Gol Quadrado 1980 Até 1987.', 'Detalhes do Produto: Kit 02 Borracha De Porta Tipo Original Gol Parati Voyage Quadrado 1980 Até 1994, Saveiro 1982 Até 1997, Monza 1982 Até 1990, Apollo 1990 Até 1992 Santana e Quantum 1984 Até 1990, Chevette 1983 Até 1994, Marajó 1983 Até 1994, Chevy 1983 Até 1994, Escort 1983 Até 1992, Verona 1983 Até 1992 Os veículos possuem componentes de borracha nas portas, vidros e no teto que tem por função evitar a infiltração de água e também no caso das Canaletas e Pestanas formam o trilho do vidro. A avaliação periódica desses componentes é recomendada, para que eventuais infiltrações não comprometam a lataria, provocando sua corrosão e molhando o interior do veiculo. Compatível com veículos: Gol Quadrado 1980 1981 1982 1983 1984 1985 1986 1987 1988 1989 1990 1991 1992 1993 1994 Parati Quadrada 1980 1981 1982 1983 1984 1985 1986 1987 1988 1989 1990 1991 1992 1993 1994 Voyage Quadrado 1980 1981 1982 1983 1984 1985 1986 1987 1988 1989 1990 1991 1992 1993 1994 Saveiro 1982 1983 1984 1985 1986 1987 1988 1989 1990 1991 1992 1993 1994 1995 1996 1997 Monza 1982 1983 1984 1985 1986 1987 1988 1989 1990 Apollo 1990 1991 1992 Santana e Quantum 1984 1985 1986 1987 1988 1989 1990 Chevette 1983 1984 1985 1986 1987 1988 1989 1990 1991 1992 1993 1994 Marajó 1983 1984 1985 1986 1987 1988 1989 1990 1991 1992 1993 1994 Chevy 1983 1984 1985 1986 1987 1988 1989 1990 1991 1992 1993 1994 Escort 1983 1984 1985 1986 1987 1988 1989 1990 1991 1992 Verona 1983 1984 1985 1986 1987 1988 1989 1990 1991 1992 Especificação Técnica: Alta resistência e durabilidade Qualidade padrão original Borracha casco de cobra Impede a entrada de pó e outros materiais Impede a infiltração de água Reduz o nivel de ruídos externos Evita correntes de ar, perda de