INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '27692007138', 'Sandália Feminina Salto Bloco Fivela Laço Confortável 6230', 'Sandália feminina com salto bloco e tira frontal com laço delicado, perfeita para quem busca unir conforto e charme em um só calçado. O fechamento no tornozelo garante ajuste ideal e segurança ao caminhar, enquanto o design moderno torna o modelo versátil para diversas ocasiões, desde looks casuais até produções mais elegantes. Principais características: • Salto bloco médio que proporciona conforto e estabilidade. • Tira frontal com detalhe em laço, trazendo um toque feminino e delicado. • Fechamento no tornozelo com fivela ajustável. • Palmilha macia que garante bem-estar durante o uso. • Solado com boa aderência. • Modelo versátil, ideal para compor diferentes estilos de looks. • Altura do Salto: 5,5 cm •••• TABELA DE MEDIDAS •••• 34 ------------- 23,5 cm 35 ------------- 24,0 cm 36 ------------- 24,6 cm 37 ------------- 25,1 cm 38 ------------- 25,8 cm 39 ------------- 26,5 cm 40 ------------- 27,1 cm', 119.99, 69.99, NULL, 'Women Shoes > Heels', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mezs1jv5eupyd1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F367507085%2F27692007138', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
