INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43369273515', 'Difusor de Aromas Ar 100ml Secar', 'Difusor de Aromas Ar 100ml Secar Este elegante difusor proporciona uma fragrância suave e refrescante, ideal para criar uma atmosfera acolhedora em qualquer ambiente. Ele não apenas perfuma, mas também decora, trazendo um toque de natureza para sua casa ou escritório. A duração do produto é diretamente influenciada pelas condições climáticas como calor, frio e exposição ao sol. Em ambientes grandes, pode ser necessário dois ou mais difusores. Indicação de Uso: - É recomendado não deixar próximo a saídas de ar-condicionado, janelas e cortinas. Fragrância: Lírio e Rosa Embalagem: 01 Difusor de 100ml', 36.54, 36.54, NULL, 'Home & Living > Home Fragrance & Aromatherapy > Diffusers, Humidifiers & Oil Burners', 'https://cf.shopee.com.br/file/sg-11134201-824ja-meqa45ijedqce3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F946161700%2F43369273515', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18797633102', 'Kit Jogo Faqueiro 84 Peças Talheres Luxo Inox Banhado a Ouro 24k Maleta de Senha e Couro Sintético', 'Faqueiro Estilo Versace 84 Peças – Maleta de Couro, Luxo e Sofisticação Apresentamos o Faqueiro Estilo Versace, um conjunto completo de 84 peças em aço inoxidável 18/10 com detalhes banhados a ouro 24k, ideal para elevar o requinte da sua mesa. Acompanha maleta de couro com tranca e senha, garantindo armazenamento seguro e elegante. Características do Produto: Conjunto completo para 12 pessoas Facas temperadas, seguras para pratos de porcelana Maleta de couro projetada com gavetas e espaço individual para cada peça Design luxuoso e sofisticado, com delicados filetes dourados em todas as peças Produto novo, de alta qualidade e durabilidade Conteúdo do Faqueiro: 12x Colheres principais 12x Garfos principais 12x Facas principais 12x Garfos de sobremesa 12x Colheres de sobremesa 12x Colheres de café 1x Espátula para bolo 2x Garfos para peixe 1x Concha grande 1x Concha pequena 1x Colher para açucareiro 1x Pegador 2x Colheres para servir 2x Colheres para salada Diferenciais: Peças em aço inoxidável 18/10, espessura 3mm Acabamento espelhado e detalhes dourados Elegância e sofisticação em cada refeição Ideal para ocasiões especiais e para impressionar seus convidados Observação: As imagens são meramente ilustrativas. As cores podem sofrer pequenas variações conforme iluminação e configuração do monitor. Garantia do vendedor: 3 meses', 699.0, 529.35, NULL, 'Home & Living > Dinnerware > Cutleries', 'https://cf.shopee.com.br/file/br-11134207-820ll-mqi1o6yzqh34bf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1177369665%2F18797633102', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
