INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '29842277139', 'Kit 6un Biscoitos Cookie De Goiaba E Goiabinha Piraquê', 'Kit com 6 unidades: 3 unidades de Biscoito Cookie Original Goiabinha Piraquê Pacote 80g: Ingredientes:Farinha de trigo enriquecida com ferro e ácido fólico, gordura vegetal, goiabada em cubos (açúcar, polpa de maçã, polpa de goiaba, água, espessante pectina, acidulante ácido cítrico, aromatizante, conservador sorbato de potássio, corante: ponceau 4R), açúcar, creme de goiaba (polpa de goiaba, açúcar, acidulante ácido cítrico e conservador benzoato de sódio), soro de leite em pó, extrato de malte, sal, fermentos químicos: bicarbonato de amônio, bicarbonato de sódio e difosfato dissódico, emulsificante lecitina de soja e aromatizantes. 3 unidades de Biscoito Recheio Goiabinha Original Piraquê Pacote 75g: Ingredientes:Farinha de trigo enriquecida com ferro e ácido fólico, goiabada (goiaba, açúcar, estabilizante pectina e acidulante ácido cítrico), açúcar, gordura vegetal, amido de milho*, soro de leite em pó, açúcar invertido, extrato de malte, sal, leite em pó integral, emulsificantes: lecitina de soja e estearoil lactilato de cálcio, estabilizante polidextrose, fermentos químicos: bicarbonato de sódio, fosfato monocálcico e bicarbonato de amônio, conservador propionato de cálcio, aromatizantes e melhorador de farinha metabissulfito de sódio. Prepare-se para algo totalmente novo! Chegou o Cookies Goiabinha, trazendo a crocância irresistível dos cookies com o sabor clássico da goiabinha que você adora. Feito com pedacinhos de goiabada, é um produto inovador e único no mercado, perfeito para transformar qualquer momento em uma experiência deliciosa. Não tem como resistir a essa novidade! #AReceitaÉSerOriginal.', 31.6, 31.6, NULL, 'Food & Beverages > Snacks > Biscuits, Cookies & Wafers', 'https://cf.shopee.com.br/file/sg-11134201-824ji-mf4i8goa64uh4e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F590473480%2F29842277139', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '6286347705', 'Borracha Porta Malas Tipo Original Gol; Voyage; Parati/95 Escort; Verona, Logus, Apollo', 'Detalhes do Produto: Borracha Porta Malas Tipo Original Gol; Voyage; Parati/95 Escort; Verona Os veículos possuem componentes de borracha nas portas, vidros e no teto que tem por função evitar a infiltração de água e também no caso das Canaletas e Pestanas formam o trilho do vidro. A avaliação periódica desses componentes é recomendada, para que eventuais infiltrações não comprometam a lataria, provocando sua corrosão e molhando o interior do veiculo. Compatível com veículos: Borracha Porta Malas Tipo Original Gol; Voyage; Parati/95 Escort; Verona; Logus; Apollo Especificação Técnica: Alta resistência e durabilidade Qualidade padrão original Borracha casco de cobra Impede a entrada de pó e outros materiais Impede a infiltração de água Reduz o nivel de ruídos externos Evita correntes de ar, perda de climatização Na cor preta Tamanho: 4,20m Importante: Garantia da borracha: 02 anos contra defeito de fabricação Valor unitário Imagens meramentes ilustrativas Recomendamos que a instalação seja feita sempre por um profissional A Nolascoshopnão se responsabiliza por mal instalação ou uso indevido do produto Itens Inclusos: 01 Borracha para o porta malas (02 anos de garantia)', 69.9, 69.9, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Others', 'https://cf.shopee.com.br/file/fda2b4fc357f5bf30286ea6fd3fde082', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F391224294%2F6286347705', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
