INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23494436063', 'New Show Conjunto de 1 Super Cola Salon Pro 30ml+1 Caixa Com Cílios postiços 6D MINK-Tufinhos Sem Nó', 'Product Description New Show Conjunto de 1 Super Cola Salon Pro 30ml+1 Caixa Com Cílios postiços 6D MINK-Tufinhos Sem Nó Cílios Postiços 6D MINK - Tufos sem Nó Os cílios em tufos podem ser aplicados em toda extensão da pálpebra ou na parte externa para realçar o olhar. Ideal para concluir, consertar falhas e dar volume aos cílios naturais! Mink Sintético (Leve similar a seda) Cola para extensão de cílios e cabelo (lace e peruca) Contém: 01 unidade Capacidade: 30ml Cor da cola: Preta A cola Salon pro é uma cola para extensão de cílios com uma duração de em média de 15 a 20 dias após aplicação (Mantendo todos os cuidados) A cola de fixação salon pro possui uma fórmula única ideal para a colagem, perfeita na fixação Prazo de validade Indeterminado, Manter fora do alcance de criança ** Siga as instruções da Loção Removedora Salon Pro para evitar a quebra de cabelo, Não puxe. INGREDIENTES: Látex de borracha natural, água (Aqua), terpolímero de poliacrilato, hidróxido de amônio. ATENÇÃO: Devido as configurações do monitor/ou luz, pode haver pequena diferença no tom das cores. Custom Product:Yes Region of Origin:Mainland China Quantity:2', 50.0, 24.99, NULL, 'Beauty > Beauty Tools > Makeup Accessories', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mf5iu6jgqk1wa8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1430626556%2F23494436063', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58253178119', 'Kit Truss Nutri Infusion Home Care Duo (2 Produtos)', 'Kit com shampoo e condicionador para cabelos ressecados. Truss Nutri Infusion Home Care Duo devolve a vitalidade e a maciez dos fios. O Kit Truss Nutri Infusion Home Care Duo oferece um tratamento intensivo para os fios, combatendo o ressecamento extremo e reparando danos causados por químicas e calor. Este kit restaura a vitalidade dos cabelos, deixando-os mais fortes, saudáveis e radiantes. Nenhum produto TRUSS é testado em animais, ou seja, este item possui selo Cruelty Free. Contém: Truss Nutri Infusion - Shampoo 300ml: é Capaz de limpar, enquanto nutre as camadas mais profundas e necessitadas da fibra, resgatando a nutrição natural dos fios e revitalizando os cabelos altamente ressecados. Truss Nutri Infusion - Condicionador 300ml: Penetra nas camadas mais profundas da fibra capilar, retendo os lipídios essenciais e criando uma barreira contra a perda de hidratação, para um cabelo saudável e luminoso. Como Usar: Shampoo: Aplique nos cabelos molhados, massageando suavemente o couro cabeludo até formar espuma. Deixe agir por 2 minutos e depois enxágue. Reaplique se necessário. Condicionador: Após o uso do shampoo, retire o excesso de água dos fios e distribua o condicionador no comprimento e pontas. Massageie, desembarace, deixe agir por 2 minutos e enxágue. **** IMPORTANTE: Não vendemos para contas CNPJ, evite que seu pedido seja cancelado! ****', 259.8, 259.8, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-8261j-mjfkrmkyht6s53', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1674883556%2F58253178119', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23993090796', 'Defletor Calha de Chuva Transit 2022 2 Portas Ecoflex', 'Defletor Calha de Chuva Transit 2022 2 Portas Ecoflex A Ecoflex possui uma vasta linha de calhas defletores automotivas para os mais diversos modelos. Utiliza matéria-prima de primeira, 100% acrílico, com tecnologia 3M e instalação simples. Os produtos comercializados pela Ecoflex têm como objetivo trazer conforto e segurança em seu automóvel nos dias de chuva. Com a calha de chuva a água da chuva não entrará no interior do veículo e evita que os vidros embacem. Compatibilidade: • Transit 2022 2 Portas Especificações: • 100% Acrílica; • Proteção e Design; • Contra chuva e sol; • Fixada por Fita Dupla Face 3M; • Não deixa os vidros embaçarem. Conteúdo da Embalagem: • 2 Calhas Defletores de Chuva • 1 Primer (anti-aderente) Garantia: • 5 Anos (defeito de fabricação) Se tiver alguma dúvida a equipe Triangulo Auto Parts estará pronta para lhe atender.', 146.94, 135.9, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rd3n-lwilv1b5thwo43', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1276072791%2F23993090796', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
