INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22493824750', 'Panela de Pressão 7 Litros Panelux Alumínio Polido', 'A Panela de Pressão 7 litros Classic Polida é produzida pela maior fabricante de panelas de pressão das américas, a Panelux. Possui características com alto padrão de qualidade que vão desde a escolha da matéria prima até o processo de montagem com componentes que oferecerão segurança e um melhor desempenho na sua cozinha. Além do pino central controlador de pressão, possui uma válvula de segurança em silicone. Ambas trabalham em conjunto para um melhor controle interno da pressão, evitando acidentes e proporcionando um cozimento rápido e na temperatura ideal. Tanto o cabo e a alça são fabricados em baquelite, material durável e que resiste a altas temperaturas, característica que além de proporcionar uma maior vida útil para a panela trará mais segurança. Tudo fica bem mais fácil com a Panelux! Informações Técnicas Material: AlumínioCompatível com fogão por indução: NãoAcabamento: Alumínio polidoAcabamento Externo: PolidoCapacidade: 7 litrosAcabamento interno: Não possuiLavável em lava-louças: sim Conteúdo da Embalagem 1 Panela de pressão 7 litros em alumínio polido', 140.9, 111.99, NULL, 'Home & Living > Kitchenware > Pots', 'https://cf.shopee.com.br/file/sg-11134201-7rd6p-m79sxywdcm6wb5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826682830%2F22493824750', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58253929844', 'Boneco Articulado Montável Blokees Jurassic World Terraventure TS 01 Colecionável Model Kit', 'BLOKEES JURASSIC WORLD TERRAVENTURE TS 01 - DINOSAUR CAPTURE OPERATION | MODEL KIT DETALHES - Licença Genuína - Textura de Pele Detalhada - Articulação Multi-ângulo - Variantes Chase 1/144 - Acessórios Diversos de Personagem - Montagem sem Ferramentas Embarque em uma aventura emocionante com Terraventure TS-01 Operação de Captura de Dinossauros, onde dinossauros lendários como Tiranossauro Rex, Velociraptor e Espinossauro ganham vida. Cada conjunto contém 12 modelos, com 9–20 peças para montagem. Cada kit de modelo apresenta articulações articuladas para poses de ação dinâmicas. Descubra variantes Ultra-Raras (1/144) e variantes Raras (5/144). Complete a coleção com o exclusivo Combo Esqueleto de Tiranossauro Rex, disponível apenas no conjunto completo. Com montagem sem ferramentas, esta série oferece uma aventura imersiva de captura de dinossauros, levando você de volta à era Jurássica com cada caixa. CONTEÚDO DA EMBALAGEM Cada Surpresa Individual Contém: - Kit de Modelo*1 - Cartão (com instruções no verso)*1 - Moeda Comemorativa (apenas em caixas com Esqueleto de T.Rex) - Partes de Esqueleto Dispersas (apenas em variantes específicas) Composição da Série: 12 Kits de Modelo (Variante rara garantida e o conjunto combo) ESPECIFICAÇÕES - Tipo: Brinquedos de personagens para montar - Série do Item: Jurassic World Terraventure TS 01 - Idade Recomendada: 9 anos ou mais - Material: Plástico ABS ecologicamente correto - Observação: A embalagem da caixa individual contém um kit de modelo. Pode ser aleatoriamente um kit de modelo básico ou um kit de modelo especial. Distribuído por Polibrinq As imagens são meramente ilustrativas. As cores, dimensões e detalhes do produto podem