INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15356783947', 'Disco de Corte Bosch Standard for Metal 115x1mm Reto', 'Os discos de corte Standard for Metal possuem ótimo desempenho em cortes em metal. São produzidos com grãos abrasivos de óxido de alumínio de alta qualidade que dão rendimento e velocidade em suas aplicações, além das telas de fibra de vidro feitas com precisão e simetria que trazem alta estabilidade para o disco. São fabricados sob alto padrão de qualidade em conformidade com as normas internacionais (EN 12413) trazendo máxima segurança durante sua aplicação. São indicados para corte de metais ferrosos e não ferrosos e ferro fundido e utilização em esmerilhadeiras manuais. Características: - Para cortar - Metais ferrosos e não ferrosos, ferro fundido - Alto rendimento no corte de metal - Mais desempenho para sua ferramenta. Acessórios Profissionais Bosch. - Alta velocidade de corte - Fabricado sob normas internacionais (EN12413) trazendo máxima segurança nas aplicações - Produzidos com telas de fibra de vidro feitas com precisão e simetria que trazem grande estabilidade para os discos e máxima segurança na aplicação Tipo de Embalagem: Caixa de papelão Público Alvo: Serralheiros, Metalúrgicos, Manutenção Industrial, Fabricantes de Máquinas, Construção Civil Diferenciais Técnicos: Os discos de corte Standard for Metal possuem ótimo desempenho em cortes em metal. São produzidos com grãos abrasivos de óxido de alumínio de alta qualidade que dão rendimento e velocidade em suas aplicações, além das telas de fibra de vidro feitas com precisão e simetria que trazem alta estabilidade para o disco. São fabricados sob alto padrão de qualidade em conformidade com as normas internacionais (EN 12413) trazendo máxima segurança durante sua aplicação. São indicados para corte de metais ferrosos e não ferrosos e ferro fundido e utilização em esmerilhadeiras manuais. Especificações técnicas: - Diâmetro do disco: 115mm - Diâmetro do furo: 22,23mm - Espessura: 1,0mm - RPM Máximo: 13.300 RPM - Para cortar - Metais ferrosos e não ferrosos, ferro fundido - Alto rendimento no corte de metal - Mais desempenho para sua ferramenta. Acessórios Profissionais Bosch. - Alta velocidade de corte - Fabricado sob normas internacionais (EN12413) trazendo máxima segurança nas aplicações - Produzidos com telas de fibra de vidro feitas com precisão e simetria que trazem grande estabilidade para os discos e máxima segurança na aplicação', 10.23, 7.59, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/20b2cd0ad579db963e5917d7b97de390', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F15356783947', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18476811676', 'Odorizante Aromatizador Breeze Gel Carro Novo 60 mL Cheirinho Veículos e Ambientes - Proauto', 'Os Breeze Gel Proauto agora estão de cara nova!Sua formulação permite a emissão de um perfume duradouro e agradável. E além disso, não derrama. Com o novo pote, o Breeze Gel conta com uma regulagem de emissão de perfume, fazendo com que o odorizante dure por mais tempo. Excelente para odorizar veículos, e ambientes domésticos, tais como: salas, escritórios, quartos, banheiros, sapateiras, etc. Fragrância: Carro Novo.', 12.96, 12.96, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Treatments', 'https://cf.shopee.com.br/file/sg-11134201-7qvdw-leq643jz3p6b51', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F18476811676', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
