INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '4186351867', 'Borracha De Porta Tipo Original Ford Ka 2001 2002 2003 2004', 'Detalhes do Produto: Borracha De Porta Tipo Original Escort e Verona 1983 Até 1992, Escort Hobby, Logus e Pointer 1993 Até 1996 e Ford Ka 1997 Até 2008 Os veículos possuem componentes de borracha nas portas, vidros e no teto que tem por função evitar a infiltração de água e também no caso das Canaletas e Pestanas formam o trilho do vidro. A avaliação periódica desses componentes é recomendada, para que eventuais infiltrações não comprometam a lataria, provocando sua corrosão e molhando o interior do veiculo. Compatível com veículos: Escort 1983 1984 1985 1986 1987 1988 1989 1990 1991 1992 Escort Hobby 1993 1994 1995 1996 Ford Ka 1997 1998 1999 2000 2001 2002 2003 2004 2005 2006 2007 2008 Logus 1993 1994 1995 1996 Pointer 1993 1994 1995 1996 Verona 1983 1984 1985 1986 1987 1988 1989 1990 1991 1992 Especificação Técnica: Alta resistência e durabilidade Qualidade padrão original Borracha casco de cobra Impede a entrada de pó e outros materiais Impede a infiltração de água Reduz o nivel de ruídos externos Evita correntes de ar, perda de climatização Na cor preta Importante: Garantia da borracha: 02 anos contra defeito de fabricação Valor unitário (serve para todas portas) Imagens meramentes ilustrativas Recomendamos que a instalação seja feita sempre por um profissional A Nolascoshopnão se responsabiliza por mal instalação ou uso indevido do produto Itens Inclusos: 01 Borracha de porta (02 anos de garantia)', 73.16, 73.16, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/fda2b4fc357f5bf30286ea6fd3fde082', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F391224294%2F4186351867', NULL, NULL, '2026-0