INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58202345499', 'Jogo De Cama 300 Fios Satinée Kacyumara Fend Stone', 'O Jogo de Cama 300 Fios Satinée da Kacyumara é ideal para quem busca uma cama posta elegante, confortável e com acabamento impecável, elevando a experiência do quarto com sofisticação e bem-estar. Confeccionado em 100% algodão egípcio 300 fios, oferece toque suave acetinado, maciez superior e excelente respirabilidade. Seu tecido conta com tratamento antipilling, garantindo maior durabilidade e mantendo o visual bonito por muito mais tempo, sem formação de bolinhas. O lençol com elástico proporciona ajuste perfeito ao colchão, com caimento firme e alinhado, contribuindo para uma cama sempre organizada e com visual de hotelaria em casa. Um conjunto pensado para quem valoriza conforto, estética e qualidade no enxoval. Diferenciais do produto Tecido 300 fios com toque suave acetinado 100% algodão egípcio Tratamento antipilling para maior durabilidade Caimento elegante e ajuste perfeito ao colchão Ideal para cama posta sofisticada Conforto superior para uso diário Qualidade e tradição Kacyumara Conteúdo da embalagem (conforme tamanho escolhido) Solteiro 1 Lençol com elástico 1 Lençol com vira 1 Fronha 50 x 70 cm Casal / Queen / King 1 Lençol com elástico 1 Lençol com vira 2 Fronhas 50 x 70 cm Medidas Lençol com elástico Solteiro: 0,98 x 2,03 x 0,40 m Casal: 1,40 x 1,90 x 0,40 m Queen: 1,60 x 2,00 x 0,45 m King: 1,93 x 2,03 x 0,45 m Lençol com vira Solteiro: 1,80 x 2,60 m Casal: 2,20 x 2,60 m Queen: 2,40 x 2,60 m King: 2,80 x 2,60 m Fronhas 50 x 70 cm Solteiro: 1 unidade Casal, Queen e King: 2 unidades Composição 100% Algodão Egípcio 300 Fios Cuidados Lavar à máquina em modo suave, sem excesso de peso Não misturar cores, principalmente escuras Não deixar de molho Não usar cloro Não secar em tambor Secar à sombra Não passar Utilizar sabão neutro e seguir as instruções da etiqueta Informações importantes As cores do produto podem apresentar variações sutis de acordo com o lote de fabricação e/ou configurações de tela.', 579.9, 579.9, NULL, 'Home & Living > Bedding > Bedsheets, Pillowcases & Bolster Cases', 'https://cf.shopee.com.br/file/sg-11134201-81zud-miklham8z476ba', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1516596857%2F58202345499', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22994394884', 'Correia Micro-V 6PK1875 Gates P/ Troller T4 de 2000 até 2005', 'Correia de acessórios Micro-V 6PK1875 Gates. As correias Gates Micro V oferecem uma operação extremamente suave e possui características importantes para seu uso contínuo. Capacidade de força extremamente alta por friso rib, maior durabilidade em virtude da alta capacidade de suportar cargas. Transmissões mais compactas. Os micro canais truncados garantem a flexibilidade. O composto de borracha de alta qualidade protege a correia contra o calor, o ozônio, óleo e a luz solar. O corpo da correia é reforçado com fibras, o que melhora ainda mais a estabilidade da correia, os cordonéis de Poliéster vulcanizados na borracha como uma única peça, proporcionam alta resistência à tração, suportando a fadiga e as cargas de choque. Especificações: - Marca: Gates - Código do Fabricante: 6PK1875 - Modelo: Alternador, Ar condicionado, Bomba D''agua, Direção Hidráulica, Virabrequim. - Quantidade de Lâminas: 6 - Garantia: 12 meses Obs: Este produto requer um profissional capacitado para realizar a instalação. Não nos responsabilizamos por má instalação ou uso indevido do produto. Aplicações: - BMW Série 1 120i de 2007 até 2015 - Chevrolet S10 STD de 2000 até 2005 - Chevrolet Blazer Colina de 2000 até 2009 - Troller T4 de 2000 até 2005.', 129.35, 97.02, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-22110-ce2p2v9rlnjvc2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1452490205%2F22994394884', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22896016919', 'Defletor Calha de Chuva Fiat 500 (Cinquecento) 2 Portas Ecoflex', 'Defletor Calha de Chuva Fiat 500 (Cinquecento) 2 Portas Ecoflex A Ecoflex possui uma vasta linha de calhas defletores automotivas para os mais diversos modelos. Utiliza matéria-prima de primeira, 100% acrílico, com tecnologia 3M e instalação simples. Os produtos comercializados pela Ecoflex têm como objetivo trazer conforto e segurança em seu automóvel nos dias de chuva. Com a calha de chuva a água da chuva não entrará no interior do veículo e evita que os vidros embacem. Compatibilidade: • Fiat 500 (Cinquecento) 2 Portas Especificações: • 100% Acrílica; • Proteção e Design; • Contra chuva e sol; • Fixada por Fita Dupla Face 3M; • Não deixa os vidros embaçarem. Conteúdo da Embalagem: • 2 Calhas Defletores de Chuva • 1 Primer (anti-aderente) Garantia: • 5 Anos (defeito de fabricação) Se tiver alguma dúvida a equipe Renovaccio estará pronta para lhe atender.', 162.38, 139.9, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Others', 'https://cf.shopee.com.br/file/sg-11134201-7qve2-li0q37lp2bfp19', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1013208711%2F22896016919', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
