INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58201106647', 'Engate Reboque Fixo Virtus 2018 a 2025 700 Kg - Brucke VW5038', 'Engate Reboque Volkswagen Virtus 2018 a 2025 Fixo 700 Kg Marca: Brucke Modelo: VW5038 - Compatibilidade: Volkswagen Virtus 2018 Volkswagen Virtus 2019 Volkswagen Virtus 2020 Volkswagen Virtus 2021 Volkswagen Virtus 2022 Volkswagen Virtus 2023 Volkswagen Virtus 2024 Volkswagen Virtus 2025 O Engate Reboque para o Volkswagen Virtus de 2018 a 2025 Fixo da marca Brucke é a solução ideal para quem busca robustez e confiabilidade. Com uma capacidade de reboque de até 700 Kg, este modelo com ponteira Fixo tem resistência testada e garantida, garantindo que você possa transportar cargas pesadas com segurança! É compatível com carretinhas, trailers, transbikes. - Atributos do Produto: Tipo de ponteira: Fixo Medidas: 20 x 66 x 102 cm, 8kg. Capacidade de reboque tração: Até 700 Kg Capacidade de peso sobre a bola: Até 40 kg Material: Fabricado em Aço carbono Pintura: Acabamento em pintura eletrostática a pó na cor preta Homologação: Produto homologado pelo INMETRO (012587/2022) e regularizado conforme a resolução nº 197 do Contran. Acompanha bola de engate, tomada e acabamento (quando necessário) como nas imagens. Código interno: 887 Instalação: Instalação simples nas furações originais do veículo, sem necessidade de furos ou adaptações. A instalação deve ser feita por um profissional.', 543.43, 489.09, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Hitch', 'https://cf.shopee.com.br/file/sg-11134201-8227d-mhjmw7dyfabq17', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1625011375%2F58201106647', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
