INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44073420226', 'Ancinho Metálico Leve Curvo 16D Sem Cabo (77101/164) - Tramontina', 'O Ancinho Metálico Leve Curvo 16D Sem Cabo (77101/164) - Tramontina, é uma ferramenta indispensável para agricultura e jardinagem, oferecendo eficiência e durabilidade excepcionais. Possui um design curvo que facilita a movimentação do solo, tornando-o ideal para a preparação de canteiros e afofamento da terra. Os dentes proporcionam uma excelente capacidade de remoção de detritos e aeração do solo, promovendo condições ideais para o crescimento saudável das plantas. Além disso, a leveza do produto garante facilidade de manuseio sem comprometer a resistência. Invista neste ancinho Tramontina para garantir uma experiência de jardinagem eficaz e confortável. Descrição do Produto: • O ancinho é temperado em todo o corpo da peça, proporcionando maior resistência e menor desgaste durante o uso. • Fabricado em aço carbono especial de alta qualidade. • Possui 2 mm de espessura. • Possui 16 dentes. • Possui olho de 26 mm de diâmetro. • Recebe pintura eletrostática a pó, que tem uma melhor apresentação visual e maior proteção contra oxidação. • A tinta utilizada na pintura é isenta de metais pesados na sua composição, o que minimiza o impacto ambiental. Referência: 77101/164. Cód. de Fábrica: 77101/164. Marca: Tramontina.', 25.37, 25.37, NULL, 'Home & Living > Gardening > Gardening Tools', 'https://cf.shopee.com.br/file/sg-11134201-824j5-mfmws8njta8ac8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F44073420226', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
