INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58202863982', 'Da Terrinha Goma de Tapioca', 'A Goma de Tapioca Da Terrinha é perfeita para um lanche rápido e saudável, feita com mandioca, uma rica fonte de carboidratos. Já vem pronta para uso, sem necessidade de peneirar ou adicionar água. Livre de glúten e lactose, ideal para quem possui restrições alimentares. Modo de Preparo: * Aqueça uma frigideira em fogo baixo. * Espalhe cerca de 100g de goma pronta para tapioca Da Terrinha. * Aqueça por cerca de 2 minutos até se soltar da borda. * Coloque o recheio de sua preferência. * Dobre a tapioca sobre o recheio e aguarde por 30 segundos. * Agora é só servir! Bom apetite!', 11.99, 11.99, NULL, 'Food & Beverages > Bakery > Others', 'https://cf.shopee.com.br/file/sg-11134201-8262y-mj72o5m3t4p2ff', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554792%2F58202863982', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
