INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '17227034588', 'Par Amortecedor Dianteiro Corolla 2014 2015 2016 2017 2018 Original Kayaba', 'PRECO REFERENTE AO PAR (02 PECAS) AMORTECEDOR DIANTEIRO (DIREITO/ESQUERDO) - 339824 / 339825 ORIGINAL KAYABA - NOVO NA CAIXA PRINCIPAIS APLICACOES: VEICULO: TOYOTA COROLLA Toyota Corolla Sedan Gli 1.8 16v 2zrfe Vvti L4 Flex 2014 - 2018 Toyota Corolla Sedan Gli Upper 1.8 16v 2zrfe Vvti L4 Flex 2016 - 2018 Toyota Corolla Sedan Gli Upper Black 1.8 16v 2zrfe Vvti L4 Flex 2017 - 2018 Toyota Corolla Sedan Std 2.0 16v 3zrfbe Vvti L4 Flex 2014 - 2018 Toyota Corolla Sedan Xei 2.0 16v 3zrfbe Vvti L4 Flex 2014 - 2018 Toyota Corolla Sedan Xli 1.8 16v 1zzfbe Vvti L4 Flex 2014 - 2018 Pecas novas, marca KYB (KAYABA) Qualidade original de montadora LINHA EXCEL-G: AMORTECEDORES PRESSURIZADOS As valvulas patenteadas e o gas de nitrogenio pressurizado do amortecedor Excel-G KYB sao os responsaveis pelo conforto da conducao e reducao radical na vibracao. Alem disso, possui maior resistencia mecanica, o que contribui para que o desempenho ideal do equipamento seja mantido por mais tempo. DIFERENCIAIS: Recupera o desempenho do equipamento original; A valvula antiespuma de um sentido reduz a formacao de espuma e a diminuicao de desempenho; Valvulas duplas de tres fases; Pistao da valvula revestido com teflon; Haste do pistao cromada e resistente; Mancais e luvas soldados; Fluido mantem a viscosidade constante, independentemente das temperaturas externas; Almofada de rebote prolonga a vida. ****Recomendamos que os produtos sejam instalados por profissionais especializados***', 827.14, 827.14, NULL, 'Automobiles > Automobile Spare Parts > Shocks, Struts & Suspension', 'https://cf.shopee.com.br/file/f2b8d892e802a088de141f4656e8f945', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%