INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22894967672', 'Junta Carter Cortiça Monza Kadett 1.6 Gasolina 1.8 Álcool', 'JUNTA CARTER CORTIÇA FURO 7MM GM MONZA KADETT 1.6 1.8 8V OHC ÁLCOOL GASOLINA 82/86 Descrição do produto: Junta do cárter em cortiça de alta vedação, desenvolvida para garantir estanqueidade do sistema de lubrificação do motor, evitando vazamentos de óleo e proporcionando excelente encaixe. Produto de qualidade Juntas Bastos, com boa resistência a óleo e temperatura. Aplicação: Monza 1.6 8V Álcool 1982 a 1986 Monza 1.6 8V Gasolina 1982 a 1986 Monza 1.8 8V FI Álcool 1983 a 1986 Monza 1.8 8V FI Gasolina 1983 a 1986 Kadett 1.6 / 1.8 8V OHC 1982 a 1986 Codigos Similares: Não informado Especificações: Material: Cortiça Furo: 7 mm Numero Original(OEM): Não informado Garantia: Garantia de 3 meses contra defeitos de fabricação. Importante: Recomendamos que a instalação seja realizada por um profissional qualificado. Verifique a compatibilidade antes de efetuar a compra. Caso tenha dúvidas, informe a placa ou chassi do veículo no campo de perguntas para confirmação. A Grupo JIT eCommerce é uma loja especializada em peças automotivas, com ampla variedade de produtos para diversos veículos. Atuamos há muitos anos no mercado, sempre prezando pela qualidade, procedência e atendimento eficiente. Somos vendedores com selo de confiança no Shopee, oferecendo mais segurança e tranquilidade na sua compra. Conte com o Grupo JIT eCommerce para encontrar as peças certas com rapidez, seriedade e ótimo custo-benefício.', 25.85, 19.39, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-822z3-mo8lc53ukxdv53', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F494445158%2F22894967672', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
