INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58208510621', 'Tênis Rainha Masculino Slip On Relax II', 'O Tênis Rainha Relax II é a escolha perfeita para quem busca conforto, praticidade e estilo em um único produto. Seu design slip-on oferece calce rápido e ajuste flexível, enquanto o cabedal em knit com elastano proporciona uma sensação de ajuste anatômico, acompanhando os movimentos naturais dos pés. O tecido, desenvolvido com poliéster, poliamida e elastano, conta com estrutura bi ou tridimensional, que envolve o pé de forma confortável e adaptável, elevando a sensação de bem-estar durante o uso. Para completar, a palmilha Comfortmax com espuma de alta densidade em PU garante maciez e conforto prolongado, enquanto o solado em EVA distribui o impacto a cada passada, oferecendo leveza e absorção de impacto no dia a dia. Garanta o seu Rainha Relax II e experimente o equilíbrio perfeito entre conforto e estilo!', 249.89, 179.88, NULL, 'Men Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-81zvq-mmufu5rsinluf6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920605202%2F58208510621', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
