INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18298544605', 'VINHO ASSOBIO DOURO ROSE 750ML', 'Respeitando a tradição vitivinícola da mais antiga região demarcada do mundo, são vinhos produzidos com base nas suas variedades autóctones, concebidos para expressar o aroma vibrante das castas mais tradicionais do Douro e mostrar o seu potencial para fazer vinhos equilibrados e de grande aptidão gastronômica. Aspecto límpido, cor rosada com reflexos azuláceos. Aroma de fruta fresca, com apontamentos de cerejas pretas. Paladar fresco, equilibrado e persistente.', 99.9, 99.9, NULL, 'Food & Beverages > Alcoholic Beverages > Wine & Champagne', 'https://cf.shopee.com.br/file/sg-11134201-7qvdm-lh595ca3m2oc97', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F661273874%2F18298544605', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22622756314', 'VINHO CASILLERO DEL DIABLO CABERNET SAUVIGNON 375ml', 'Um dos grupos vinícolas mais importantes do planeta, a Viña Concha y Toro foi fundada em 1883 pelo empresário chileno Don Melchor Concha y Toro. A empresa possui 10.800 hectares de vinhedos no Chile, Argentina e Estados Unidos, sendo a segunda maior do mundo em vinhedos próprios. Don Melchor é seu tinto mais prestigiado, cuja primeira colheita aconteceu em 1987 sob a consultoria do enólogo francês Jacques Boissenot. Atualmente, seu filho Eric Boissenot ao lado do enólogo chileno Enrique Tirado são os guardiões do Don Melchor. Carmín de Peumo, Gravas del Maipo, Amelia, Marques de Casa Concha e a linha Terrunyo são outros vinhos de alto nível produzidos pela Concha y Toro. A vinícola também elabora ótimos tintos e brancos para o dia a dia, entre os quais, os mundialmente famosos Casillero del Diablo. O Vinho Casillero del Diablo Cabernet Sauvignon Reserva é um dos rótulos mais populares do Brasil! Elaborado por um dos maiores nomes no mundo do vinho, Viña Concha y Toro. Produzido com a uva Cabernet Sauvignon, oriunda de vinhedos no Vale Central, no Chile. De coloração rubi intensa, revela aromas de frutas vermelhas maduras, como cereja, ameixa e groselha, notas tostadas e um toque de baunilha. Um Vinho Tinto elegante e frutado. Em boca apresenta taninos elegantes e um final longo e persistente. Esse é um Vinho Chileno perfeito para o dia a dia, com ótimo custo-benefício! Produzido 100% com a uva Cabernet Sauvignon, oriunda de vinhedos na região vitivinícola do Vale Central, no Chile. A fermentação é realizada em tanques de aço inox, sob temperatura controlada. O vinho estagia em barricas de carvalho americano.', 39.9, 39.9, NULL, 'Food & Beverages > Alcoholic Beverages > Wine & Champagne', 'https://cf.shopee.com.br/file/br-11134207-7qukw-livn82f9gb5r49', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F661273874%2F22622756314', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22593279585', 'Kit 2x Condrigen HA Colágeno Tipo II + Ácido Hialurônico 60Cápsulas Maxinutri', 'Kit 2x Condrigen HA Colágeno Tipo II + Ácido Hialurônico 60Cápsulas Maxinutri O condrigen HA é um suplemento inovador,com tecnologia avançada,que associa a ácido hialurônico biodisponível com o colágeno não hidrolisado tipo II com a tecnologia UC-II® associados às vitamina C,90 d3 e o mineral manganês. UC-II® é um colágeno tipo II não hidrolisado,o mesmo encontrado em nossas cartilagens,que age para manter as articulações saudáveis,promover maior mobilidade e flexibilidade e prevenir lesões,sendo capaz de dessensibilizar o sistema imunológico,prevenindo o "ataque" autoimune às cartilagens. O ácido hialurônico está naturalmente presente em tecidos e articulações porém com o tempo,sua presença diminui. Sua reposição é importante pois promove a manutenção da saúde articular através da hidratação e lubrificação devido a sua capacidade de atrair grandes quantidades de água para os tecidos. As vitaminas C,D e o mineral manganês tem um papel muito importante na manutenção da saúde articular,agindo juntamente com o UC-II® e o ácido hialurônico. Ingerir 1 cápsula com água pela manhã em jejum. NÃO CONTÉM GLÚTEN', 259.8, 259.8, NULL, 'Health > Food Supplement > Well Being', 'https://cf.shopee.com.br/file/sg-11134201-7rdvx-m036yvjo7ge282', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341217898%2F22593279585', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
