INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22693988914', 'Volante Caminhão Volvo NL10 NL EDC NL12E 360 NL12 340 FH12', 'Oferecemos durabilidade e resistência incomparáveis. Nossos volantes foram projetados para oferecer máxima segurança, garantindo aderência firme e conforto, proporcionando controle absoluto em todas as suas viagens. CONTEÚDO DA EMBALAGEM: • Volante Esportivo Personalizado; • Diâmetro de 370mm; • Cubo Adaptativo; • Emblema; • Parafusos para instalação. COMPATIBILIDADES: • Volvo NL • Volvo EDC EXCLUSIVIDADE • Qualidade superior em poliuretano: Volantes com toque macio, controle preciso e resistência excepcional, graças ao poliuretano de alta tecnologia e cubos metálicos que garantem segurança e durabilidade. • Personalização única: Volantes em diversas cores e compatibilidades, ideais para realçar o estilo e a personalidade do seu carro. • Atendimento especializado: Se não encontrar seu modelo em nossa descrição, entre em contato com nossa equipe e nós ajudaremos a encontrar a solução ideal para você. IMPORTANTE: • Verifique a compatibilidade do anúncio com seu veículo. Tire suas dúvidas ANTES da compra. • Entrega rápida: Compras realizadas hoje serão despachadas no próximo dia útil. • Recomendamos a instalação por um profissional. • A instalação dos nossos volantes resulta na perda da funcionalidade do airbag. Eleve a experiência ao dirigir com nossos volantes', 281.24, 227.81, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Internal Parts', 'https://cf.shopee.com.br/file/sg-11134201-7rfi6-m9uaxrs4nc4667', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F955071389%2F22693988914', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
