INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22219127292', 'Barra de Chocolate Cobertura Fracionada Mais Ao Leite 1,01kg Sicao', 'Mais sabor, mais rendimento. A Cobertura Sabor Chocolate Ao Leite Sicao Mais traz o verdadeiro sabor do chocolate, contém liquor de cacau em sua formulação, e a presença de leite a torna mais cremosa. Tem excelente fluidez, brilho marcante e o melhor rendimento do mercado. Alérgicos: Contém leite, e soja. Contém lactose. Contém glúten. Ingredientes: Açúcar, Gordura vegetal, Leite em pó desnatado, massa de cacau, soro de leite em pó, leite em pó integral, lecitina de soja, ésteres de ácido ricinoleico, e Aromatizantes. Somos uma loja especializada em artigos de festa, confeitaria, embalagens e atacado em doces com lojas físicas no estado de São Paulo, desde 2002. Imagens meramente ilustrativas, de acordo com nossos fornecedores que nos fornecem. Todas as Informações divulgadas são de responsabilidade do fabricante/fornecedor. Todos nossos produtos são muito bem embalados para não chegarem danificados. Não se preocupe, os chocolates chegam em perfeito estado, não derretem no transporte.', 48.99, 48.99, NULL, 'Food & Beverages > Snacks > Chocolate', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m0sv35hl2mhpc1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F318555124%2F22219127292', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '6960232672', 'Chocolate Prestígio Tradicional C/30 Unidades 33g Cada Nestlé', 'Prestigio é o clássico que nunca sai de moda! A Nestlé acertou em cheio quando nos trouxe a deliciosa combinação de chocolate com um recheio delicioso de coco, que ganhou o coração de todos os brasileiros. Prestigio é perfeito para tudo, para comer sozinho ou com os amigos, vcai bem em cestas e kits de doces também, você pode utilizá-lo na decoração de receitas e muito mais! Peso líquido do display: 990 gramas Peso líquido da unidade: 33 gramas Quantidade: 30 unidades Ingredientes: Açúcar, coco ralado, liquor de cacau, xarope de glicose, gordura vegetal, licquor de cacau, lactose, manteiga de cacau, gordura anidra de leite, cacau em pó, umectante glicerol, emulsificantes lecitina de soja e poliglicerol polirricinoleato e aromatizante. ALÉRGICOS: CONTÉM DERIVADOS DE LEITE E SOJA. PODE CONTER AMENDOIM, AMÊNDOA, AVELÃ, CASTANHA-DE- CAJU, OVO, TRIGO, CEVADA E AVEIA. Somos uma loja especializada em artigos de festa, confeitaria, embalagens e atacado em doces com lojas físicas no estado de São Paulo, desde 2002. Imagens meramente ilustrativas, de acordo com nossos fornecedores que nos fornecem. Todas as Informações divulgadas são de responsabilidade do fabricante/fornecedor.', 134.99, 134.99, NULL, 'Food & Beverages > Snacks > Chocolate', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mjlb590d5nnn1b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F318555124%2F6960232672', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22393339153', 'Pó Para Preparo de Cobertura Glacê Real 500g Mavalério', 'Para decoração e acabamentos de bolos e doces; Para suspiros; Aceita corante em gel. CONTÉM DERIVADOS DE OVOS. PODE CONTER SOJA, TRIGO, LEITE, CEVADA, CENTEIO E AVEIA. INGREDIENTES: Açúcar, amido de milho (Bacillus thuringiensis, Streptomyces viridochromogenes, Agrobacterium tumefaciens, Zea mays, Sphingobium herbicidovorans, Dicossoma sp., Diabrótica virgifera, Thermoccocales spp., Bacillus subtilis), clara de ovo em pó, regulador de acidez ácido cítrico (INS 330) e aromatizante. Armazenar fechado em local fresco, seco, limpo e inodoro. Evitar exposição ao sol. Após aberta a embalagem, recomenda-se o consumo do produto em até 30 dias e que ela seja guardada bem fechada em local fresco e seco. Este produto pode se compactar durante o transporte e armazenamento, no entanto o volume corresponde ao peso líquido indicado.', 21.99, 21.99, NULL, 'Food & Beverages > Baking Needs > Baking Decoration', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m0ezal0cymxs78', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F318555124%2F22393339153', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22992583975', 'Conector DC Jack para Notebook Dell Inspiron 5458', 'Conector DC Jack compatível com Dell Inspiron 5458 Este é um DC Jack bringIT compatível com o notebook Dell Inspiron 5458. Ele é ideal para acabar com os problemas de alimentação de energia em um notebook. O DC Jack — ou DC Power Jack — é um conector interno responsável por intermediar a alimentação de energia entre a fonte (carregador) e o laptop. Este produto é um de alta qualidade e cumpre todas as especificações de segurança dos notebooks. Para evitar problemas de compatibilidade, compare as fotos deste anúncio com seu equipamento original. Assim você consegue verificar as principais informações de compatibilidade e demais especificações do seu notebook. Atenção: Esse é um dc jack bringIT, portanto não é um produto original da fabricante Dell. Caso seja necessário, todo o suporte e garantia do produto serão oferecidos pela nossa equipe. Informações Técnicas Tamanho do Conector: 4.5mm x 3.0mm Cabo: Com Cabo Garantia: 3 meses de garantia contra defeitos de fabricação Referência: DC112-DE-0005', 33.23, 31.57, NULL, 'Computers & Accessories > Desktop & Laptop Components > Others', 'https://cf.shopee.com.br/file/sg-11134201-825b1-mqsk554k0glq83', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F392651618%2F22992583975', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
