INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21370349694', 'Lanterna Lateral Carreta Vermelha LED 12V 24V', 'Lanterna lateral para carreta ou Luz de placa cor Vermelha LED 12V 24V Chegou a hora de você economizar e ter qualidade de vida comprando Lanterna Lateral Carreta / Luz de Placa Cristal LED 12V 24V da H3 componentes automotivos. Aplicação - Carreta Randon - LED interno (1 LEDS) - Carreta Facchini - Carreta Noma - Carreta Guerra - Carreta Rodotecnica - Todas as Carretas... - Trailer - Reboque - Trator - Bivolt 12v -24v O que acompanha - 01 Lanterna Lateral Carreta / Luz de Placa Vermelha LED 12V 24V Cor - Preto Material - Plástico / LED Dimensões - Medidas (AxLxP): 3 x 3 x 7 cm Peso - 0,016 kg Fabricante - H3 componentes automotivos Código Fabricante - H37146 Outros diferenciais - Cor: Vermelha - LED interno - Longa Duração - Selada a prova d''água - Bivolt (12/24V) - Com fios para instalação - Alta qualidade - Perfeito acabamento - Base metalizada - Lente em Acrílico Ultra-Resistente - Fácil instalação e substituição', 23.83, 23.83, NULL, 'Spare Parts and Accessories for Vehicles > Heavy Duty and Boats > Spare Parts for Heavy Duty Vehicles', 'https://cf.shopee.com.br/file/sg-11134201-23010-46epmjhkgvlv9c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F908791545%2F21370349694', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '5884891927', 'Filtro De Fox 1.6 Gol 1.6 Polo 1.6 HLT6098', 'filtro de ar fox 1.6 polo 1.6 gol 1.6 trapezio Filtro de ar de motor Sujeira pode comprometer a força do motor ao alterar a queima do combustível O filtro de ar impede que as impurezas existentes na atmosfera entrem e fiquem incrustadas dentro do motor. Essa sujeira pode comprometer a sua força, danificar seus componentes e piorar o consumo. Quanto mais limpo for o conteúdo aspirado, mais eficiente será a queima de combustível. Qual a função do filtro de ar do motor? O filtro de ar serve para evitar que as partículas de impureza do ar cheguem à câmara de combustão do motor. Com ele em dia reduz-se o desgaste em componentes como pistões e bielas, além de reduzir o consumo de combustível.', 29.99, 29.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/br-11134207-820lz-mnlhsvmkog7675', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F414229824%2F5884891927', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13707674824', 'Repelente de Insetos Off! Aerossol 165ml', 'OFF Family Aerossol possui fórmula não oleosa, com aloe vera. Repele mosquitos que podem transmitir Zika, Dengue, Chikungunya e Febre amarela. Garante proteção por até 6h. Ideal para atividades ao ar livre. Pode ser usado em crianças acima de 12 anos. Agite bem antes de usar. Proteger os olhos durante a aplicação. Posicione a uma distância de 15cm do corpo e aplique com movimentos circulares. Pode ser aplicado diretamente à pele ou à roupa. Não aplique o produto excessivamente ou por baixo de roupas.', 41.09, 41.09, NULL, 'Beauty > Skincare > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rbkf-lmqfl2p0ud6zb9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F13707674824', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
