INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23997766808', 'Avião Planador Voa Para Kit Festa Aniversario dia da Criança Prenda Lembrancinha Brinquedo Infantil', '***ATENÇAO, ESCOLHA O MODELO NA VARIAÇAO*** ITEM ANUNCIADO: 1 AVIAO ( 1 UNIDADE ) Traga sorrisos e diversão para seus pequenos com nossos brinquedos. Garanta momentos de alegria hoje mesmo! Vem se divertir no nosso mundo☺️ Planadores Avião Radicais De Brinquedo Do Filme Aviões Da Disney kit lembrança Aviões Modelos, para se divertir com suas crianças, chegou nossos modelos com os personagens mais queridos da criançada, Dusty, Skipper, Ripslinger vão animar mais o seu dia-a-dia.. pratica montagem BENEFÍCIOS: - Desenvolve a atenção e concentração - Estimula a interação social com amigos - PRODUTO RESISTENTE CARACTERÍSTICAS DO PRODUTO: MEDIDAS APROXIMADAS 23CM DE LARGURA X 7CM DE ALTURA X 21 CM DE COMPRIMENTO MATERIAL: ISOPOR VALIDADE: INDETERMINADA PODEM SER USADOS COMO, LEMBRANCINHAS DE FESTAS DECORAÇÃO QUALQUER DUVIDAS ESTAMOS A DISPOSIÇÃO PARA ESCLARECER BOLINHA MÁGICA.', 10.99, 8.79, NULL, 'Mom & Baby > Toys > Toy Vehicles', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m21fd0q4dh7j4d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045133925%2F23997766808', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
