INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23594654937', 'Solução Antisséptica Bucal Malvona 100ml', 'Solução para Diluição Malvona 100ml Malvona é uma solução para Diluição, composto por Benzocaína 0,20mg/ml, cloreto de cetilpiridínio 1,00mg/ml, boraro de sódio 60,00mg/ml. Malvona deve ser utilizada exclusivamente por via oral, através de bochechos ou gargarejos. Portanto, não deve ser ingerida. Diferenciais do Malvona: Rápido Alívio para: - Dor de Garganta - Afecções de Boca - Aftas.', 41.86, 41.86, NULL, 'Health > Personal Care > Oral Care', 'https://cf.shopee.com.br/file/sg-11134201-82588-mg38mfk130uk20', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1467864110%2F23594654937', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20797806740', 'Kit Sapata Lona Freio Traseiro Original Frasle New Ecosport Sigma 2013 2014 2015 2016 2017 a 2019', 'Seja Bem-vindo(a)!! É um prazer imenso tê-lo em nosso anuncio. Abaixo algumas informações sobre o Produto e Aplicação. Por fim, conheça um pouco mais sobre a nossa loja. Produtos: 1 Jogo de Sapatas de Freio Traseira Marcas: Frasle Aplicação: Veiculo: Nova Ecosport Motor: 1.6 2.0 Ano: 2013 2014 2015 2016 2017 2018 2019 Garantia: 90 dias. É novo, e acompanha nota fiscal Sim! Todos nossos produtos são novos acompanhados de nota fiscal. Sobre a Loja: Somos uma empresa que trabalha exclusivamente com o setor de peças para veículos leves e médios, sendo eles nacionais ou importados. Oferecemos peças com qualidade, prazo de entrega, parcerias com as melhores marcas e eficiência no atendimento. Temos uma equipe de profissionais qualificados para orientar o cliente nas suas mais variadas necessidades relacionadas à manutenção do seu veículo. Oferecemos também um amplo estoque de peças e envios diários. Visamos constantemente o aperfeiçoamento e melhoria dos serviços para a satisfação total do cliente. ATENÇÃO Para garantia de AMORTECEDORES, só serão aceitas mediante apresentação do certificado enviado junto ao produto. Sem esse documento, não será possível efetuar a garantia do produto. Em caso do não recebimento do certificado, favor nos enviar assim que receber a mercadoria e notar a ausência.', 426.38, 426.38, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Brakes', 'https://cf.shopee.com.br/file/sg-11134201-7rdw1-m01mit5ou23y13', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373135807%2F20797806740', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22894662532', 'Vinil The Who - Live At The Oval 1971 (2LP) - Importado', 'Vinil The Who - Live At The Oval 1971 (2LP) - Importado Com 35.000 pessoas presentes, em 18 de setembro de 1971, The Who foi a atração principal do Goodbye Summer: A Rock Concert em apoio à ajuda contra a fome para o povo de Bangladesh, no campo de críquete The Oval, em Kennington, no sul de Londres. Novamente mixado a partir das fitas multicanal analógicas de 8 faixas originais, este concerto mostra The Who continuando sua dominância como a melhor banda de rock ao vivo da era. A apresentação extraordinária culmina com Pete Townshend e Keith Moon destruindo seu equipamento em um grande final. Tracklist: LP 1 – LADO A 1. So Glad To See Ya 2. Summertime Blues 3. My Wife 4. Love Ain’t For Keeping 5. I Can’t Explain 6. Substitute LP 1- LADO B 1. Bargain 2. Behind Blue Eyes 3. Won’t Get Fooled Again LP 2 - LADO C 1. Baby Don’t You Do It 2. Pinball Wizard 3. See Me, Feel Me / Listening To You LP 2 -LADO D 1. My Generation 2. Naked Eye 3. Magic Bus', 399.9, 399.9, NULL, 'Hobbies & Collections > Vinyl Records', 'https://cf.shopee.com.br/file/sg-11134201-825bb-mqnko1rke6fiad', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1356917260%2F22894662532', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10906266953', 'Chicote para CD 35/D8 - Chevrolet Spin / Cobalt / Prisma / Onix', 'CHICOTE PARA CD 35/D8 Agora você poderá trocar sua central multimídia sem precisar cortar a fiação do veículo. Ele faz a conexão do chicote de sua multimídia com o chicote do seu carro, sem a necessidade de corte na fiação e possíveis perdas de garantia de seu veículo, além da compatibilidade com o rádio. Carros Compatíveis: - Onix - Cobalt - Prisma - Spin Conteúdo da Embalagem: - 1 Chicote para CD 35/D8 Não nos responsabilizamos pelo mal uso do produto', 24.37, 24.37, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Others', 'https://cf.shopee.com.br/file/7ca332ef9db5c082eafb2dc5472c14aa', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F288113309%2F10906266953', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10482418669', 'Caneta rollerball 0.5 Vision Elite UB-205 Preta Uni-Ball', 'A uni-ball Vision Elite UB-205 é uma caneta rollerball desenvolvida para oferecer uma escrita extremamente suave, precisa e confiável em qualquer situação. Equipada com ponta de 0,5 mm, proporciona traços finos e uniformes, ideais para anotações, assinaturas, documentos, estudos e uso profissional. Seu exclusivo sistema de fluxo contínuo garante uma escrita consistente até a última gota de tinta, enquanto a tecnologia Airplane Safe foi projetada para resistir às variações de pressão atmosférica, evitando vazamentos durante viagens aéreas. A tinta pigmentada uni-ball é resistente à água, de secagem rápida e possui propriedades antifraude, proporcionando maior segurança e durabilidade para documentos importantes. A ponta de aço inoxidável oferece excelente desempenho e suavidade durante a escrita. Reconhecida mundialmente pela qualidade de escrita, a Vision Elite é uma das rollerballs preferidas de profissionais, executivos, estudantes e viajantes frequentes. Principais Benefícios " Ponta rollerball de 0,5 mm para escrita fina e precisa " Sistema de fluxo contínuo para traços uniformes " Tecnologia Airplane Safe contra vazamentos em voos " Tinta resistente à água " Secagem rápida " Tinta antifraude de alta segurança " Escrita extremamente suave e confortável " Ideal para documentos, estudos e uso profissional " Qualidade e confiabilidade uni-ball Detalhes do Produto Marca: uni-ball Linha: Vision Elite Modelo: UB-205 Tipo: Caneta rollerball Espessura da ponta: 0,5 mm Material da ponta: Aço inoxidável Tinta: Pigmentada líquida Características: Antifraude, resistente à água e secagem rápida Tecnologia: Airplane Safe (anti-vazamento em voos) Aplicação: Escrita, assinaturas, documentos, estudos e uso profissional A uni-ball Vision Elite UB-205 combina precisão, segurança e desempenho superior, proporcionando uma experiência de escrita suave e confiável em qualquer lugar do mundo.', 35.4, 30.09, NULL, 'Stationery > Writing & Correction > Pens & Inks', 'https://cf.shopee.com.br/file/sg-11134201-8259c-mqyz6lpe7jetc7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400736454%2F10482418669', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23093819950', 'Bico de Mamadeira Ortodôntico Kuka N°2 Transparente 1 Unidade', 'Com furo G, para liquidos pastosos, o bico Big ortodôntico Kuka foi desenvolvido para uso exclusivo das mamadeiras Big Kuka de 150ml, 240ml e 330ml. O bico Big ortodôntico em silicone encaixa perfeitamente na boca do bebê, auxiliando no desenvolvimento natural da sucção e da mandíbula devido ao seu formato; O bico Big também possui sistema anti cólica através do respiro que se abre quando o bebê suga, evitando a ingestão de ar. • Somente para mamadeiras Big Kuka.• Bico Nº2, para bebês maiores de 6 meses. • Furo G, para liquidos pastosos.• Sistema Anti Cólica. • Bico 100% em silicone macio, atóxico, antialérgico, esterilizável, inodoro, não mela e é resistente à fervura. • Livre de BPA.', 39.34, 39.34, NULL, 'Mom & Baby > Maternity Accessories > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rd67-m76u80mxo42i74', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1467864110%2F23093819950', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15913258833', 'Caneta hidrográfica Fine Point 88/19 Bordô Stabilo', 'A Caneta Stabilo Point 88 Fine Point 0,4mm é a escolha ideal para estudantes, profissionais, artistas e amantes de papelaria que buscam máxima precisão em seus traços. Reconhecida como a fineliner número 1 do Brasil, ela combina qualidade, conforto e um design icônico para proporcionar uma experiência de escrita e desenho incomparável. Seu famoso design hexagonal listrado é conhecido mundialmente e oferece excelente ergonomia durante o uso. A ponta extrafina de 0,4 mm permite criar linhas nítidas, detalhadas e precisas, sendo perfeita para escrita, desenhos técnicos, lettering, anotações, mapas mentais, contornos e ilustrações. A ponta revestida de metal garante maior resistência e durabilidade, além de permitir o uso com réguas, estênceis e outros instrumentos de precisão. Outro grande diferencial é sua alta proteção contra secagem: a caneta pode permanecer destampada durante o uso sem comprometer a qualidade da tinta. Disponível em uma ampla variedade de cores vibrantes, a Stabilo Point 88 é referência em desempenho, versatilidade e confiabilidade para o dia a dia. Principais Benefícios Traço extrafino de 0,4 mm para máxima precisão Fineliner número 1 do Brasil Design hexagonal listrado reconhecido mundialmente Ideal para escrita, desenho, lettering e trabalhos detalhados Ponta revestida de metal para maior resistência Compatível com réguas e estênceis Alta proteção contra secagem sem tampa Tampa ventilada para maior segurança Tampa com encaixe na extremidade da caneta Cores vibrantes e excelente desempenho Detalhes do Produto Modelo: Point 88 Fine Point Tipo: Caneta Fineliner Espessura do Traço: 0,4 mm Ponta: Revestida de metal Tampa: Ventilada e com encaixe traseiro Aplicação: Escrita, desenho, ilustração, lettering, estudos e trabalhos técnicos A Stabilo Point 88 é a caneta perfeita para quem busca precisão, durabilidade e acabamento profissional em cada traço. INMETRO 006320/2013,', 21.88, 21.88, NULL, 'Stationery > Writing & Correction > Pens & Inks', 'https://cf.shopee.com.br/file/sg-11134201-823q8-mozvzmy1dc7h56', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400736454%2F15913258833', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14757018120', 'Aditivo para limpeza de bico luxcar gasclean 200ml', 'Somos a Go! Mec Auto Peças, estamos no ramo de autopeças para veículos nacionais e importados há quase duas décadas, nosso estoque conta com uma variedade de 45000 itens. Todos os nossos produtos são novos, originais e com garantia. Este anúncio contém os seguintes produtos: O GasClean Luxcar promove uma limpeza completa do sistema de combustível para motores etanol, gasolina ou flex. O sistema de combustível do seu carro é composto pelo tanque, tubos, filtros, válvulas, bomba de combustível e bicos injetores, com o passador tempo tendem a acumular resíduos e formam depósitos. Uma das principais causas é a qualidade duvidosa dos combustíveis. Usando o Tratamento Ultra Concentrado GasClean Luxcar a limpeza começa no bocal do tanque e termina nos bicos injetores. Ele melhora o desempenho, prolonga a vida útil da bomba, fazendo ela trabalhar com uma menor carga de trabalho, remove resíduos dos bicos injetores e carburadores, remove todos os tipos de depósito e contaminantes e reduz as emissões do sistema de exaustão. Vantagens: • Fácil de usar. • Lubrifica, limpa e mantém os bicos injetores limpos. • Elimina falha nas partidas por mau funcionamento dos bicos. • Melhora o desempenho e o coeficiente energético. • Protege o sistema contra corrosão. • Menos gasto com manutenções corretivas. • Limpeza profissional feita por você mesmo. • Seguro para bombas, válvulas, sensores e filtros. Modo de usar: Agite bem a embalagem antes de usar. Em um tanque com no mínimo 20 litros de combustível (álcool ou gasolina), despeje todo o conteúdo da embalagem. Atenção para o produto não escorrer na lataria. Recomenda-se reaplicar o produto a cada 2 tanques ou 1000 km. Validade 24 meses.', 34.0, 34.0, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Additive and Lubricant', 'https://cf.shopee.com.br/file/f828636fa18b466e3d550d264b5487d9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F549478150%2F14757018120', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19299650356', 'Mordedor Rosa com Chocalho da Nina - TurmaTube | Dentição e Estímulo Sensorial para Bebês', 'O Mordedor Rosa com Chocalho da Nina é uma verdadeira experiência sensorial para o seu bebê, estimulando os cinco sentidos de maneira divertida e acolhedora. Para trabalhar a audição, balance o mordedor e ouça o barulhinho suave do chocalho. Passe a mãozinha do bebê nas texturas divertidas para que ele sinta o toque macio e desenvolva o tato. E, para uma experiência olfativa, ele conta com um cheirinho suave e acolhedor, escolhido especialmente por Viih Tube, semelhante ao cheiro gostoso de talco de bebê. ✨ Características do Produto: Atóxico e livre de BPA – 100% seguro para o bebê, sem substâncias prejudiciais. Texturas massageadoras – Ideais para aliviar a gengiva durante o processo de dentição. Chocalho com som suave – Acompanha o desenvolvimento auditivo do bebê com um barulhinho delicado e agradável. Design encantador da personagem Nina – A personagem dinossaurinha Nina traz mais magia ao momento de brincadeira e alívio. Formato anatômico – Fácil de segurar e manusear pelas mãozinhas do bebê. 🌟 Benefícios do Produto: Estimula os sentidos do bebê – A combinação de texturas, som e cheiro estimula a visão, tato, audição e olfato. Alívio para a gengiva – As texturas macias proporcionam alívio nas gengivas do bebê, especialmente durante a dentição. Seguro e divertido – Além de ajudar na fase da dentição, o mordedor é uma diversão para o bebê, com o som suave do chocalho e o design interativo. 🔧 Idade recomendada: A partir de 4 meses. 💜 TurmaTube – Fazemos parte da sua rede de apoio, cuidando de você e do seu bebê em cada etapa da jornada materna.', 85.9, 49.9, NULL, 'Mom & Baby > Toys > Baby & Toddler Toys', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m9rnnv3xx8opcb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1245828786%2F19299650356', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41722554411', 'Serra Mármore Worker 1300W', '***PRODUTO A PRONTA ENTREGA COM ENVIO IMEDIATO*** Serra Mármore Worker 4.3/8" 127 V ou 220 V reúne potência de 1300 W, velocidade de 12.000 RPM e base com ajuste de profundidade para entregar cortes rápidos e padronizados em cerâmica, pisos e alvenaria. O formato compacto melhora a condução, a compatibilidade com discos de 110mm amplia as aplicações e a isolação dupla agrega segurança no uso profissional e em reformas. ESPECIFICAÇÕES TÉCNICAS: Marca: Worker Tipo: Serra mármore 4.3/8" Potência: 1300 W Tensão: 127V ou 220V Frequência: 50/60 Hz Diâmetro do disco: 110 mm Recursos: Ajuste de profundidade | base de apoio | empunhadura auxiliar Aplicações: Cortes retos e rasgos em materiais minerais com disco adequado Uso Recomendado: Profissional e profissional leve, ciclos intermitentes CONTEÚDO DA EMBALAGEM: 1 Serra Mármore Worker 1300W. 1 Jogo de Escovas (carvão). 1 Chave Hexagonal. Manual do usuário.', 279.9, 249.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-824j0-mfb9f2e3ha19d7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F445163047%2F41722554411', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '40910861286', 'CHENXIAOHONG Mochila para Laptop Grande Impermeável', '📏 Tamanho: Comprimento 32cm (X) Largura 14cm (X) Adequado para segurar até 17 "Laptops, livros, diários, roupas e essenciais diários. 🎒 Espaço rico e organização: ✔️ Compartimento Principal Espaçoso Espaçoso, Perfeito Para Armazenar Notebooks, Material Escolar E Itens Pessoais. ✔️ Bolsos Laterais Práticos Para Armazenar Garrafas, Guarda-chuvas Ou Acesso Rápido Para Itens Pequenos. ✔️ Bolsa de Armazenamento Interno Para Organização E Proteção dos Itens. 💧 Material impermeável durável: Feito de tecido de alta qualidade, impermeável, resistente ao desgaste e fácil de limpar, pode proteger seus itens de chuva e umidade. 💪 Confortável e ergonômico: ✔️ Mangas acolchoadas compridas ajustáveis para conforto Superior. ✔️ Painel traseiro respirável respirável reduz o calor e melhora o conforto para uso diário. ✨ Pessoas a seguir adequadas para as pessoas a seguir: Uso diário adequado para escola, universidade, viagens, passeio, uso diário. Uma mochila prática, espaçosa, elegante e elegante Ideal para quem busca funcionalidade, conforto e proteção.', 394.71, 69.89, NULL, 'Men Bags > Backpacks', 'https://cf.shopee.com.br/file/sg-11134201-7rdx6-mcstl186drjrf6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F233364691%2F40910861286', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
