INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18998870968', 'Sensor de Posição Borboleta Megane 1.6 16v RT 1999 2000 2001 2002 2003 2004 2005 - Sensor TPS', '*** NÃO SERVE NO MODELO FLEX - NÃO SERVE NO MODELO GRAND THOUR *** Aplicação: Megane 1.6 16v 2000, 2001, 2002, 2003, 2004, 2005 Versões: 1.6 16v, RT Pino / Terminal: 3 Rotação: Anti-Horário Conversões: 7.077.710 | 9.945.634 | SS10689 | 404.062.02 | PF1C Garantia: 90 dias Usamos Fotos REAIS EM TODOS NOSSOS ANUNCIOS Produto com a qualidade Peças Premium Todos os nossos produtos acompanham nota fiscal Para compras com CNPJ de fora do Estado de São Paulo, o valor do imposto, (ST) Substituição Tributária NÃO ESTÁ INCLUSO NO VALOR DO PRODUTO ANUNCIADO, caso deseje comprar com CNPJ, após a emissão da nota fiscal, será calculado o valor do imposto de (ST), Substituição Tributária, que será COBRADO separadamente e antecipadamente. LEMBRANDO QUE O VALOR DO IMPOSTO, (ST) É COBRADO PELO ESTADO DE DESTINO e mercadoria só poderá ser despachada após o recolhimento antecipado. Peças Rápidas - O seu shopping de auto peças online!', 64.24, 64.24, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Others', 'https://cf.shopee.com.br/file/br-11134201-7r98o-lktnbjwp6thy8c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F513651190%2F18998870968', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19699840599', 'Kit Kmp Completo Cilindro Pistao Anel Junta CG 125 02 A 08', 'KIT KMP COMPLETO C/CILINDRO. PISTAO. ANEL E JUNTA KIT-A CG 125 2002 A 2008- BROS 125 2003 A 2005 Produto novo e de excelente qualidade, ideal para reposição do pistão original. O kit oferece excelente vedação, compressão e durabilidade para o motor, garantindo um ótimo desempenho e menor consumo de óleo. Fabricado de acordo com os padrões originais das montadoras, o conjunto oferece grande performance e estabilidade para sua motocicleta, além de um excelente custo-benefício. COMPATIBILIDADE: HONDA CG 125 CARGO 2002 HONDA CG 125 CARGO 2003 HONDA CG 125 CARGO 2004 HONDA CG 125 FAN 2005 HONDA CG 125 FAN 2006 HONDA CG 125 FAN 2007 HONDA CG 125 FAN 2008 HONDA CG 125 TITAN ES 2002 HONDA CG 125 TITAN ES 2003 HONDA CG 125 TITAN ES 2004 HONDA CG 125 TITAN ES 2005 HONDA CG 125 TITAN ES 2006 HONDA CG 125 TITAN ES 2007 HONDA CG 125 TITAN ES 2008 HONDA CG 125 TITAN KS 2002 HONDA CG 125 TITAN KS 2003 HONDA CG 125 TITAN KS 2004 HONDA CG 125 TITAN KSE 2002 HONDA CG 125 TITAN KSE 2003 HONDA CG 125 TITAN KSE 2004 HONDA BROS 125 NXR 2003 HONDA BROS 125 NXR 2004 HONDA BROS 125 NXR 2005 Contendo da Embalagem: Cilindro KMP; Pistão KMP com pino e trava; Jogo de Anéis KMP; Junta KMP; OBS: Recomendamos mão de obra especializada ---------------------------------- - Envio no máximo em 24 horas úteis. - Produto 100% original. - Devolução sem custo para o cliente (dentro do prazo de 7 dias ou em caso de garantia).', 329.9, 219.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-821dh-mggng9ti7s3ub7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F404353670%2F19699840599', NULL, NULL, '2026-07-28T02:11:31.708458+00:0