INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23593979040', 'Nicho Aéreo de Cozinha Garrafeiro 20cm Multimóveis CR20421', 'O Nicho Aéreo de Cozinha Garrafeiro 20cm Multimóveis CR20421 foi feito para tornar sua cozinha mais organizada e elegante. Produzido em madeira proveniente de reflorestamento (MDP) com acabamento em BP, ele oferece maior durabilidade e resistência, garantindo que você tenha uma peça de qualidade por muitos anos. Perfeito para acomodar suas garrafas de vinho, suporta até 3kg em cada prateleira. Conteúdo da Embalagem: 1 (um) Nicho Aéreo Garrafeiro Kit Ferragem Manual de Montagem Dimensões do Produto Montado: Altura: 80cm | Largura: 20cm | Profundidade: 30,3cm *Você pode consultar as medidas detalhadas na imagem técnica do produto. *As cores do produto podem sofrer variações de tonalidade de acordo com as configurações do seu dispositivo. Imagem meramente ilustrativa. Decoração não acompanha o produto. O produto será entregue desmontado e não disponibilizamos o serviço de montagem.', 199.99, 189.99, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-7rfhw-m9pyju4ouihi80', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F308628919%2F23593979040', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58208193182', 'Iluminador Baked Glass - Hbf1604 - Ruby Rose', 'Transforme sua maquiagem com o iluminador Baked da linha Glass da Ruby Rose, um produto que traz um brilho radiante e sofisticado para sua pele. Com uma textura "baked" (assada), esse iluminador oferece um acabamento mais suave e um glow natural, que se adapta ao seu tom de pele e ilumina de forma impecável. Perfeito para criar um look radiante tanto de dia quanto à noite, o iluminador garante um toque de elegância em cada detalhe. Aplique nas têmporas, no alto das maçãs do rosto, no arco do cupido e no centro da testa para um brilho iluminado e delicado, ou intensifique a aplicação para um efeito mais marcante e glamouroso. Uso externo.', 23.4, 17.99, NULL, 'Beauty > Makeup > Face', 'https://cf.shopee.com.br/file/sg-11134201-81zww-mmm21jrdtmgz39', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1784788471%2F58208193182', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
