INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21267876370', 'Água Micelar Loreal Paris Limpeza Facial Efeito Matte 200ml', 'A Água Micelar Efeito Matte Antioleosidade de L’Oréal Paris demaquila com facilidade e limpa profundamente a pele, removendo a poluição e a oleosidade, tonificando e reequilibrando a pele de forma eficaz e suave. A Água Micelar Efeito Matte de L’Oréal Paris remove efetivamente a maquiagem, limpa e purifica o rosto, olhos e lábios em um só gesto. Indicado para pele mista a oleosa. 1 produto, múltiplos benefícios: - Limpa profundamente - Demaquila sem agredir - Remove poluição e oleosidade - Age como um tônico, reequilibrando a pele - Suaviza e purifica - Remove o excesso de oleosidade Tecnologia: A Água Micelar de L''Oréal Paris é composta por partículas chamadas de micelas que agem como ímãs captando e eliminando as impurezas e a maquiagem da face. Fabricado no Brasil para a pele das brasileiras! Oftalmologicamente e dermatologicamente testado.', 56.47, 56.47, NULL, 'Beauty > Makeup > Makeup Removers', 'https://cf.shopee.com.br/file/br-11134207-7qukw-lgeegyqwo0la28', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F689225278%2F21267876370', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '51359775019', 'Berloque de Prata 925 Flor com Zircônia', 'Berloque de Prata 925 Flor com Zircônia Delicadeza e brilho em uma joia encantadora. O Berloque de Prata 925 Flor com Zircônia é perfeito para quem busca um toque feminino e sofisticado na pulseira. Com design inspirado na beleza das flores e detalhes em zircônia que proporcionam um brilho especial, essa peça combina elegância e leveza em cada detalhe. Detalhes do Berloque Tamanho: 1,2cm Peso aproximado: 0,7g Material: Prata 925 legítima Pedra: Zircônia Destaques da Joia Design em formato de flor, símbolo de beleza e renovação; Detalhes com zircônia que garantem brilho e sofisticação; Produzido em Prata de Lei 925, com alta durabilidade; Peça leve e confortável para o uso diário; Compatível com pulseiras estilo europeu; Ideal para presentear com elegância e significado. Cuidados com sua Joia Evite contato com produtos químicos, perfumes e cremes; Guarde em local seco e protegido da umidade; Limpe com flanela específica para prata para manter o brilho da peça. O Berloque de Prata 925 Flor com Zircônia é uma joia delicada que combina charme e sofisticação, perfeita para valorizar sua pulseira com um toque especial. Uma peça exclusiva da Aqua Joias, feita com qualidade e elegância.', 47.6, 39.99, NULL, 'Fashion Accessories > Additional Accessories > Charms, Pendants & Ornaments', 'https://cf.shopee.com.br/file/br-11134207-820lz-mnoon67egao2f3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328147687%2F51359775019', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
