INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18899034787', 'Brinquedo Educativo Mini Aramado Divertido Montanha Russa', 'O Aramado Divertido Pequeno é um brinquedo pedagógico interativo clássico que estimula o exercício da percepção de formas e cores. Possui 2 aramados para que a criança possa mover as peças fazendo movimentos com as mãos, além das peças coloridas em sua base de madeira, não tem peças soltas sendo assim é capaz de entreter toda a criançada com bastante segurança. Estimula a imaginação da criança, auxilia na coordenação motora fina e ajuda na percepção visual e na noção de espaço. _x000D_ _x000D_ **IMAGENS MERAMENTE ILUSTRATIVAS, AS CORES DO PRODUTO PODEM CONTER VARIAÇÕES**', 25.9, 18.91, NULL, 'Mom & Baby > Toys > Educational Toys', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m65fdcumuumdf8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436723291%2F18899034787', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23798042862', 'Mordedor Bebê Pais E Filhos Joystick', 'Mordedor Bebê Pais E Filhos Joystick O mordedor Pais E Filhos são ideais para bebês em fase de dentição. Este brinquedo é atóxico, não trazendo risco para o bebê, possui formato divertido, com diversas texturas e relevos que possibilitam massagear a gengiva, aliviando o desconforto. Ideal para aliviar e diminuir o desconforto do aparecimento dos primeiros dentinhos, os mordedores também são ótimos para fortalecerem a musculatura necessária para a mastigação do bebê. Informações Adicionais: Tamanho: Único Cores: Colorido Referência: 790729 Diferencial: Atóxico Marca: Pais E Filhos', 29.9, 29.9, NULL, 'Mom & Baby > Toys > Baby & Toddler Toys', 'https://cf.shopee.com.br/file/sg-11134201-7rfga-m30x6xzjiepjc4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1275097038%2F23798042862', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20399847628', 'Sunga Menino Listras Cores - Fakini', 'Sunga Menino Listras Cores - Fakini A sunga é composta em poliéster, elastano e forro em poliamida. Traz cós em elástico com amarração interna com elástico regulável. Além disso, possui tecnologia DRY que permite a evaporação do suor, ajuda a estabilizar a temperatura do corpo e seca com facilidade, junto a proteção UV50+ que oferece proteção solar bloqueando 90% dos raios UVA e UVB. Traz estampa de listras, perfeita para os pequenos! Características Gerais do Produto: • Composição Parte de Baixo: 90% algodão e 10% poliéster • Cor: Azul, Laranja e Verde Limao • Gênero: Masculino • Fechamento: Elástico regulável. • Modelagem: Normal • Outros: Conforto garantido! Modelagem padrão. Consulte a tabela de medidas.', 53.5, 53.5, NULL, 'Baby & Kids Fashion > Boy Clothes > Suits & Sets', 'https://cf.shopee.com.br/file/sg-11134201-7rdy3-mcc0ghja3i00b4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F688191470%2F20399847628', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
