INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22298067215', 'Livro De Banho Ciranda Cultural Dinossauros Animados', 'Livro De Banho Ciranda Cultural Dinossauros Animados O Livro de Banho Ciranda Cultural é a adição perfeita para tornar a hora do banho ainda mais divertida e educativa. Com páginas feitas de material resistente e à prova d''água, este livro é ideal para crianças que adoram explorar. As ilustrações coloridas e cativantes trazem dinossauros, estimulando a imaginação e a curiosidade dos pequenos. Cada página é projetada para suportar o uso diário, garantindo que o livro acompanhe os pequenos em suas aventuras aquáticas por muito tempo. Além de entreter, o livro de banho é uma ferramenta valiosa para o desenvolvimento infantil. Os pais podem usar a narrativa divertida para incentivar a linguagem e a criatividade, fazendo perguntas sobre os dinossauros e as situações em que se encontram. Por exemplo, "Qual é o nome desse dinossauro?" ou "O que você acha que ele está fazendo?". Esses diálogos ajudam a expandir o vocabulário e a promover o aprendizado de forma lúdica. Transforme o momento do banho em uma jornada emocionante ao passado, onde os dinossauros ganham vida e as histórias se tornam uma aventura diária. Informações Adicionais: Páginas: 6 Medidas aproximadas: 14cm x 14cm x 2cm Faixa etária: 0-3 anos Ilustrações: Shutterstock Material: Plástico Referência: 1192 Marca: Ciranda Cultural', 24.99, 24.99, NULL, 'Mom & Baby > Toys > Baby & Toddler Toys', 'https://cf.shopee.com.br/file/sg-11134201-7rfi5-m30wv2wohnukdf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1275097038%2F22298067215', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22993406253', 'Kit Cueiro Papi Karinho Tecido Flanela 80cmX60cm - 03 Peças', 'Kit Cueiro Papi Karinho Tecido Flanela 80cmX60cm- 03 Peças O Kit de Cueiros Papi Karinho é composto por três peças de cueiro com 80x60 cm, feitas em tecido flanela 100% algodão, garantindo um toque suave e aconchegante para o bebê. O algodão é conhecido por sua respirabilidade e conforto, o que é ideal para a pele sensível dos recém-nascidos. O tecido flanelado é macio e oferece calor, perfeito para manter o bebê aquecido em dias mais frescos. O kit é pensado para proporcionar praticidade e versatilidade no cuidado diário, sendo uma peça indispensável no enxoval. As cueiras possuem um acabamento delicado, com costuras reforçadas para maior durabilidade. Além disso, as cores e estampas são suaves e encantadoras, refletindo a delicadeza e o carinho que a marca Papi Karinho busca transmitir. Esse conjunto é ideal para envolver o bebê com conforto, podendo ser utilizado para proteger, aconchegar ou como um apoio durante a troca de fraldas ou no berço. Informações Adicionais: Tamanho: Único Cores: Azul Referência: 4136-375 Dimensão aproximada: 60cm x 80cm Marca: Papi Karinho', 31.8, 31.8, NULL, 'Mom & Baby > Diapering & Potty > Cloth Diapers & Accessories', 'https://cf.shopee.com.br/file/sg-11134201-7rdw7-mdby4x2c05zidc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1275097038%2F22993406253', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
