INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22293709714', 'Banheira Bebê Cajovil Fofura 28 Litros Verde', 'Banheira Bebê Cajovil Fofura 28 Litros A banheira Cajovil é ideal para um banho prático e confortável para o bebê. Este modelo possui conchinha que se encaixa na banheira e serve para enxaguar a cabecinha do bebê com mais facilidade, além disso, está banheira conta com espaço para colocar o sabonete e capacidade de 28 litros. Resistentes e estáveis, as banheiras são essenciais para a hora do banho, quanto mais confortável o bebê está na banheira, maior é a garantia da higiene e relaxamento. Informações Adicionais: Tamanho: Único Cores: Verde Claro Referência: 0808.036 Marca: Cajovil', 104.9, 104.9, NULL, 'Mom & Baby > Bath & Body Care > Bathing Tubs & Seats', 'https://cf.shopee.com.br/file/sg-11134201-7rbmf-m62w2hxnkub81c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1275097038%2F22293709714', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
