INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22693575039', 'Kit Colar Brincos Feminino Pizza Banhado a Our 18k Conjunto Caixa De Presente Namorados', '💖 💖 🥳 🥳 Bem-vindo a 《LOMISS》🥳 🥳 💖 💖 🎊🎊👍👍Somos uma empresa de joias grande e profissional. O endereço está localizado em São Paulo.Todos os produtos da loja são de alta qualidade. 👍👍🎊🎊 🚚 🚚🚀 🚀 Temos uma grande quantidade de estoque. Enviaremos seu pedido em até 48 horas após o pagamento. 🚀 🚀🚚 🚚 🎉🎉🎫 🎫Clique em ""SEGUIR"" e obtenha o cupom de desconto ""5%off""🎫 🎫🎉🎉 ---------------------------------------------------------------------------------------------------------------- 💖 💖Este produto virá em uma caixa de presente muito bonita💖 💖 💎- Tamanhos:1.15x1.15 💎- Material:Platina/Ouro 18k 💎- Gênero:Feminino 💎- Quantidade: Um Par De Brinco Com Um Colar *PVD - É uma tecnologia utilizada para a deposição de filmes metálicos finos sobre diversos tipos de substratos. O processo é realizado, sob vácuo, onde os metais a serem depositados são evaporados. É particularmente indicado para aqueles produtos inovadores e de qualidade que necessitam atender elevados padrões e permite ainda obter uma vasta gama de cores.', 80.96, 45.99, NULL, 'Fashion Accessories > Accessories Sets & Packages', 'https://cf.shopee.com.br/file/sg-11134201-7rfga-m3ek6qxh757r49', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F493729464%2F22693575039', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209476580', 'Coca-Cola Refrigerante 200ml', 'O Refrigerante Coca-Cola é perfeito para acompanhar refeições e matar a sede a qualquer hora do dia. Com a Coca-Cola Original 200ml, você pode levar seu refrigerante para onde quiser, pois a embalagem é prática e tem o tamanho ideal para ser transportada. Bebida de sabor único e refrescante, vendida em mais de 200 países e considerada uma das maiores marcas do mundo.', 1.99, 1.99, NULL, 'Food & Beverages > Beverages > Carbonated Drinks & Tonics', 'https://cf.shopee.com.br/file/sg-11134201-825a0-mqnekjvs0iyped', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1703290516%2F58209476580', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22697507409', 'Formula Infantil Aptamil AR 800g', 'Aptamil Ar Danone é um alimento próprio para bebes que sofrem com regurgitação e/ou refluxo, trazendo maior bem estar e qualidade de vida para o dia a dia do seu filho, pois em sua fórmula possui leite em pó, lactose, vitamina C, taurina, sulfato ferroso e diversos óleos. É Sempre indicado que o papai pergunte e questione ao seu pediatra ou nutricionista se ele pode ou não utilizar desse produto e se pode, a quantidade que ele precisa dar a seu filho, no entanto, ainda não se pode trocar Aptamil pelo leite materno. Caso possa tomar Aptamil, o bebê contará com mais benefícios como vitamina B12, vitamina A, sulfato de cobre e vitamina B1. O Ministério da Saúde informa: o aleitamento materno evita infecções e alergias e é recomendado até os 2 (dois) anos de idade ou mais. O Ministério da Saúde informa: após os 6 (seis) meses de idade continue amamentando seu filho e ofereça novos alimentos.', 125.82, 125.82, NULL, 'Mom & Baby > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rd72-lvdjuumybg72b6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1050887704%2F22697507409', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259906093', 'Red Bull Maçã Sugarfree Energético Lata', 'Energético Red Bull, Maçã, Sem Açúcar, 250ml RED BULL TE DÁ ASAS Inspirado por bebidas funcionais do Extremo Oriente, Dietrich Mateschitz fundou a Red Bull em meados dos anos 80. Ele criou a fórmula e desenvolveu o conceito de marketing exclusivo ao lançar o primeiro Red Bull Energy Drink em 1º de abril de 1987 na Áustria. Uma nova categoria de produtos – Energéticos - nascia. QUANDO BEBER O Red Bull Energy Drink é apreciado em todo o mundo por atletas de elite, profissionais dinâmicos, estudantes ativos e motoristas em viagens longas. O QUE EXISTE DENTRO DA LATA Cafeína: A cafeína já era conhecida por seus efeitos estimulantes pelas civilizações antigas, que a consumiam a partir de fontes naturais como o chá, café grãos de cacau e noz de cola. Taurina: Taurina é um aminoácido natural do corpo humano, que está presente na dieta diária das pessoas e está envolvida numa vasta gama de processos biológicos. Vitaminas do grupo B: As vitaminas são micronutrientes essenciais necessários para manter as funções normais do organismo. Sucralose e Acessulfame K: A Sucralose e o Acesulfame K estão entre os substitutos do açúcar mais testados e utilizados no mundo (sugarfree). Naturalmente, a água é um ingrediente crucial da Red Bull.', 10.99, 7.99, NULL, 'Food & Beverages > Beverages > Energy & Isotonic Drinks', 'https://cf.shopee.com.br/file/sg-11134201-8259z-mqnekfrasrgj1f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1703290582%2F58259906093', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
