INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22997694718', 'Filtro Saco Protetor Sanfona A262 Aspirar 80 Ipc - Sbn1332', 'Filtro Saco Protetor Sanfonado para Aspirador IPC Brasil SBN1332 Filtro saco sanfonado IPC Brasil SBN1332 em papel, com 23cm de profundidade. Protege o aspirador e extrator, garantindo maior reteno e vida til do equipamento O Filtro Saco Protetor Sanfonado para Aspirador e Extrator IPC Brasil SBN1332 a reposio ideal para manter seu equipamento trabalhando com mxima eficincia e segurana. Fabricado em papel de alta filtragem, ele retm poeiras e partculas finas com preciso, protegendo o motor e prolongando a vida til do aparelho. Com 23cm de profundidade, o filtro oferece excelente capacidade de reteno e encaixe adequado nos aspiradores e extratores IPC Brasil compatveis. Seu formato sanfonado otimiza o fluxo de ar, garantindo desempenho consistente durante toda a limpeza. Prtico, leve e essencial para uso profissional ou domstico, o IPC Brasil SBN1332 a escolha certa para quem busca filtragem eficiente, proteo e manuteno correta do aspirador. CdigoModelo: SBN1332 Marca: IPC Brasil Especificaes Tcnicas Material de Fabricao: Papel Profundidade: 23cm Itens Inclusos 01 - Filtro Saco Protetor Sanfonado para Aspirador IPC Brasil SBN1332 Prazo de Garantia 90 dias conforme especificaes do fabricante Imagens meramente ilustrativas Todas as informaes divulgadas so de responsabilidade do fabricantefornecedor Os preos anunciados neste site podem sofrer alteraes sem avisos prvios', 27.33, 27.33, NULL, 'Home Appliances > Small Household Appliances > Vacuum Cleaners & Floor Care Appliances', 'https://cf.shopee.com.br/file/sg-11134201-7rdw1-lydlakbc3qeaed', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1096473040%2F22997694718', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
