INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58201988614', 'Iogurte Natural Vigor Viv', 'O Iogurte Natural Vigor Viv é parcialmente desnatado e ideal para uma alimentação equilibrada. Feito com ingredientes simples como leite integral e/ou leite integral reconstituído, leite desnatado e fermento lácteo. É uma ótima fonte de cálcio e proteínas.', 4.49, 4.49, NULL, 'Food & Beverages > Dairy & Eggs > Yogurt & Cultured Milk', 'https://cf.shopee.com.br/file/sg-11134201-8258h-mqnelgfirvuq21', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1660302953%2F58201988614', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20398927439', 'Kit 2 Escova Papa Migalhas Vassoura Limpa Farelo De Mesa', '🧹✨ Kit com 2 Escovas Papa Migalhas – Mini Varredora Manual para Mesa e Estofados ✨🧹 Diga adeus às migalhas e sujeirinhas do dia a dia! A Mini Varredora Papa Migalhas é perfeita para limpar toalhas de mesa, sofás, cadeiras e estofados de forma rápida, prática e eficiente. Com escova rotativa interna, ao deslizar sobre a superfície ela recolhe farelos, migalhas e resíduos, armazenando tudo em um compartimento interno. Após a limpeza, basta abrir o reservatório e descartar a sujeira com facilidade — sem bagunça e sem esforço. Seu formato ergonômico proporciona melhor pegada, garantindo mais conforto e agilidade durante o uso. Um acessório simples, porém indispensável, para manter a casa sempre limpa e organizada. ✅ Principais Benefícios 🧹 Remove migalhas e sujeiras com facilidade 🔄 Escova rotativa interna – limpeza eficiente 🧼 Compartimento coletor – fácil de esvaziar 👌 Design ergonômico – conforto no manuseio 🏠 Versátil – ideal para mesas, toalhas e estofados 🔋 Manual – não precisa de pilhas ou energia 📐 Dimensões de Cada Unidade • Altura: 4 cm • Largura: 15 cm • Profundidade: 8 cm 📦 Conteúdo da Embalagem ✔ 2 Escovas Papa Migalhas (Mini Varredoras) ⚠️ Informações Importantes 🎨 Cor enviada conforme disponibilidade em estoque (não é possível escolher) 🛡️ Garantia do vendedor: 30 dias ✨ Mais praticidade e limpeza em poucos segundos! Garanta agora o Kit com 2 Escovas Papa Migalhas e facilite sua rotina 🧹✨', 30.83, 19.99, NULL, 'Home & Living > Home Care Supplies > Cleaning Brushes', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lqc7lnbq8bvr8f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F408653169%2F20398927439', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
