INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '6859752809', 'Creme De Avelã Nutella Pote Grande 700g Ferrero Rocher', 'O sabor inconfundível de Nutella em um pote grande para você aproveitar ao máximo! Desfrute do famoso creme de avelã Nutella em uma embalagem generosa de 700g, perfeita para quem ama o sabor suave e cremoso de Nutella. Ideal para lanches, acompanhamentos de pães, torradas, panquecas, waffles ou até mesmo para usar em receitas e sobremesas. Creme de Avelã Premium: Feito com avelãs selecionadas e cacau de alta qualidade. Versátil: Perfeito para acompanhar pães, bolos, frutas ou até mesmo para receitas deliciosas. Embalagem Prática: Pote grande que conserva o sabor fresco e cremoso por mais tempo. Fácil de Usar: Ideal para quem deseja praticidade sem abrir mão do sabor incrível. Ingredientes: Açúcar, gordura de palma, avelãs (1 3%), leite desnatado em pó (8,7 %), cacau magro (7,4 %), emulsionantes: lecitina (soja), vanilina. Somos uma loja especializada em artigos de festa, confeitaria, embalagens e atacado em doces com lojas físicas no estado de São Paulo, desde 2002. Imagens meramente ilustrativas, de acordo com nossos fornecedores que nos fornecem. Todas as Informações divulgadas são de responsabilidade do fabricante/fornecedor.', 76.99, 76.99, NULL, 'Food & Beverages > Breakfast Cereals & Spread > Jam & Spread', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m3ggbbqpik0r32', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F318555124%2F6859752809', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
