INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '29395158460', 'Junco Balas de Coco Sabor Tutti-Frutti 400g', 'As Balas de Coco Tutti Frutti Junco combinam uma textura macia com um delicioso sabor de coco, morango, abacaxi e tutti frutti. Elas derretem na boca e são perfeitas para quem busca um doce saboroso para qualquer ocasião. Ideais para servir em festas, decorar mesas de doces, montar lembrancinhas, abastecer potes de balas ou simplesmente saborear no dia a dia. Suas cores delicadas deixam qualquer comemoração ainda mais bonita e divertida. Mix de sabores: coco, morango, abacaxi e tutti frutti. Ideal para festas, eventos e lembrancinhas. Perfeita para expor em baleiros e potes. Embalagem prática de 400g. Ingredientes: Açúcar, água e gordura vegetal. Antiumectante talco alimentício (INS 553iii), aroma idêntico ao natural de morango, aroma artificial de abacaxi, aroma artificial de tutti frutti, aroma idêntico ao natural de coco, estabilizante tartarato ácido de potássio (cremor de tártaro) (INS 11), corante vermelho 40 (INS 129), corante amarelo tartrazina (INS 102), corante amarelo crepúsculo (INS 110), corante amaranto (INS 123), corante ponceau (INS 124) e emulsificante lecitina de soja (INS 322). ALÉRGICOS: CONTÉM DERIVADOS DE SOJA. NÃO CONTÉM GLÚTEN. Somos uma loja especializada em artigos de festa, confeitaria, embalagens e atacados em doces com lojas físicas no estado de São Paulo, desde 2002.', 13.99, 13.99, NULL, 'Food & Beverages > Snacks > Sweets & Candy', 'https://cf.shopee.com.br/file/br-11134207-820lf-mpxldt7h9hxda1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F318555124%2F29395158460', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22399212448', 'Kit Revisão Filtros Master 2.3 2022 2023 2024 2025 Wega Óleo - Ar Cabine - Ar Motor - Combustível', 'APLICAÇÃO: RENAULT: MASTER EXTRA PRÓ L3H2 / FURGÃO /GRAN PRO L2H2 / MINIBUS / PRO L1H1 2.3 16V TURBO 2022 EM DIANTE CARACTERISTICAS: COMBUSTIVEL: DIESEL TRANSMISSÃO: MANUAL REFERENCIAS: WKU580 / FAP3271/4 / WOE506 / FCD2173 / AKX1201-2 FAVOR CONSULTAR O VENDEDOR SE REALMENTE É COMPATÍVEL COM SEU VEÍCULO! • VALOR REFERENTE AO KIT • PRODUTO NOVO E ORIGINAL • ENVIO DO PEDIDO COM NOTA FISCAL • COM GARANTIA DE FÁBRICA • ANTES DE EFETUAR O PEDIDO FAVOR TIRAR AS DÚVIDAS NO CAMPO DE PERGUNTAS CUIDAR DO SEU CARRO DE MANEIRA PREVENTIVA GERA ECONOMIA E ACIMA DE TUDO GARANTE SUA SEGURANÇA PARA DIRIGIR TRANQUILO. A NOVA VIA TRABALHA PARA OFERECER MELHOR EM AUTOPEÇAS, COM UM ESTOQUE DE MAIS DE VINTE MIL ITENS PARA QUE VOCÊ ENCONTRE SEMPRE O QUE PRECISAR. DISTRIBUÍMOS AUTOPEÇAS DAS MAIORES E MELHORES MARCAS DO MERCADO, COM UM ATENDIMENTO QUALIFICADO DE PROFISSIONAIS QUE ATUAM HÁ MAIS DE VINTE ANOS NO SEGMENTO. NOVA VIA AUTOPEÇAS: SEMPRE O MELHOR PARA SEU CARRO!', 378.8, 359.86, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-82253-mhmahdbc3c3maf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F714090968%2F22399212448', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
