INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23094428056', 'Biscoito Decorado Astronauta Menino 45g | Biscoitê', 'O Decorado Avulso Astronauta Menino 45g é um biscoito decorado artesanalmente pela Biscoitê, feito com massa amanteigada e decoração em glacê real — combinação perfeita de beleza e sabor. Encante-se com nossos Astronautas!Feitos com biscoito amanteigado e decorados com glacê colorido, eles levam sabor e diversão em cada detalhe. Perfeitos para garantir o sorriso dos pequenos exploradores e transformar qualquer momento em uma aventura mais doce! • ✔ Decoração artesanal em glacê real feita à mão • ✔ Massa amanteigada irresistível • ✔ Perfeito como lembrancinha, presente ou enfeite • ✔ Ideal para festas, datas especiais e presentear crianças Encante crianças e adultos com esses biscoitos decorados artesanais. Um presente delicioso que agrada a todos e torna qualquer momento mais especial. Peso: 0.54 Ideal para: lembrancinhas de festa, decoração de mesa, presentes infantis, festas temáticas, aniversários e datas comemorativas.', 29.9, 29.9, NULL, 'Food & Beverages > Snacks > Biscuits, Cookies & Wafers', 'https://cf.shopee.com.br/file/sg-11134201-82582-meymxymdy7lvad', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1592297263%2F23094428056', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23192659150', 'Mochila Bolsa Masculina Notebook Executiva Reforçada Viagem', 'Mochila Bolsa Masculina Executiva Reforçada – Para Notebook e Viagem A Crosswave combina tradição e inovação para oferecer praticidade, segurança e estilo no seu dia a dia, onde quer que você vá. Características: •Versátil e Funcional: Pode ser usada como mochila ou bolsa de mão, adaptando-se a diferentes ocasiões – do escritório ao aeroporto. •Espaço para Notebook: Compartimento acolchoado compatível com notebooks de até 15,6", garantindo proteção contra impactos. •Design Executivo e Moderno: Visual sóbrio e elegante, ideal para ambientes corporativos e reuniões de negócios. •Estrutura Reforçada: Produzida com material de alta resistência e acabamento premium, ideal para o uso frequente. •Amplo Espaço Interno: Capacidade para transportar roupas, livros, pastas, acessórios eletrônicos e objetos pessoais com total organização. •Conforto no Transporte: Alças ajustáveis e acolchoadas, alça de mão superior reforçada e painel traseiro respirável para maior conforto em viagens longas. Especificações: •Material: Poliéster reforçado ou couro sintético (PU) •Tamanho (A x L x P): 45x32x16 cm •Peso: 0,80 kg | Capacidade: 23L •SKU:CR9107Z Envio: Seu pedido será enviado pelas transportadoras parceiras da Shopee ou pelos Correios. O rastreamento fica disponível no aplicativo, e os prazos variam conforme sua localização. Conservação: Limpeza com pano úmido, sem produtos químicos. Não expor ao sol. Garantia: 3 meses para defeitos de fabricação Pronta entrega | Nota Fiscal | Produto original', 299.9, 179.9, NULL, 'Men Bags > Laptop Bags > Laptop Backpacks', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m7valxnyyjia14', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F441209003%2F2319