INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22693421712', 'Filtro de Ar para Fiat Tempra 2.0 (1993 a 1999)', 'Filtro de Ar para Fiat Tempra 2.0 (1993 a 1999) Este filtro de ar foi projetado especificamente para o Fiat Tempra 2.0 (produzido entre 1993 e 1999), garantindo uma filtragem eficiente do ar que entra no motor, promovendo a queima de combustível mais limpa e aumentando a performance do veículo. Feito com materiais de alta qualidade, o filtro protege o motor contra partículas e impurezas, contribuindo para a economia de combustível e maior durabilidade do motor. Fácil de instalar, é essencial para manter o bom funcionamento do veículo.', 59.99, 59.99, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m143htvjxx7202', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1021060335%2F22693421712', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22736353142', 'Detergente Desengraxante Pine 5L Max', 'Detergente desengraxante que promove alto poder de limpeza, oferecendo excelentes resultados na remoção das sujidades mais pesadas, como: graxas, óleos e gorduras. Sua formulação concentrada garante economia através de alto rendimento. Desenvolvido com matérias primas de alta qualidade, contém óleo de pinho, um solvente natural que reduz os maus odores e proporciona uma agradável fragrância ao ambiente. Indicado para limpeza de fachadas, calçadas, estacionamentos, garagens, compactadores de lixo, lixeiras, docas, pisos em geral (com exceção de pisos com tratamento), banheiros, azulejos, vidros, plásticos, fórmicas e outras superfícies laváveis em geral. Cor: Amarelo Fragrância: Pinho Diluição: - Limpeza Pesada: 01 parte do produto para 200 partes de água; - Limpeza Geral: 01 parte do produto para 400 partes de água. Embalagem: 01 unidade com 5L', 164.33, 164.33, NULL, 'Home & Living > Home Care Supplies > Laundry Care', 'https://cf.shopee.com.br/file/sg-11134201-7rblv-lm91n58n7j1fb7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F946161700%2F22736353142', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
