INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41971640162', 'Soquete Hexagonal 1/2'''' x 12mm (44845/112) - Tramontina Pro', 'O Soquete Hexagonal 1/2'''' x 12mm (44845/112) - Tramontina Pro, é produzido e testado para garantir total segurança e agilidade na colocação e retirada de parafusos com perfis internos. Escolha o tamanho e perfil ideal para a sua necessidade e mãos à obra. Descrição do Produto: • Soquete forjado em aço cromo vanádio e temperado. • Ponteira em aço ferramenta S2. • Soquete com acabamento cromado. • Ponteira fosfatizada. • DIN 7422. • Suporte plástico. • Os soquetes são submetidos a testes rigorosos de torque e de dureza para atender a norma DIN 1711-1. • Afrouxar e apertar parafusos com perfil sextavado interno. • As ferramentas são produzidas e testadas conforme normas específicas. Referência: 44845/112. Cód. de Fábrica: 44845/112. Marca: Tramontina Pro.', 40.5, 40.5, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-824gl-mf3xzaz0bkeka1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F41971640162', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '51353900333', 'Bancada de Cozinha Ilha Gourmet Americana 2 Prateleiras 130cm Gaia CO8000 Marrom - Decibal Móveis', 'Bancada de Cozinha Ilha Gourmet 130cm com Nichos e Prateleiras Gaia Naturalle – Decibal Se você procura uma bancada de cozinha moderna, funcional e perfeita para ambientes integrados, a Bancada Ilha Gourmet Gaia da Decibal é a escolha ideal. Com design estilo cozinha americana, ela oferece amplo espaço para preparo de alimentos, refeições rápidas e organização de utensílios, deixando sua cozinha mais prática e elegante. Seu tampo espaçoso de 128,6 cm proporciona conforto para o dia a dia, podendo ser utilizada como bancada de apoio, ilha gourmet, mesa auxiliar ou divisor de ambientes entre cozinha e sala. Além disso, conta com 2 Prateleiras e 3 Nichos, ideais para acomodar temperos, eletroportáteis, utensílios ou itens decorativos. Fabricada em MDP de 15mm com Pintura UV de alta resistência, essa bancada garante durabilidade, estabilidade e ótimo acabamento, sendo perfeita para quem busca qualidade, organização e estilo em um único móvel. A cor Naturalle (madeirado) traz um visual sofisticado e aconchegante, combinando facilmente com cozinhas planejadas, cozinhas modernas, áreas gourmet e espaços compactos. Perfeita para quem quer otimizar espaço sem abrir mão de beleza e praticidade. PRINCIPAIS BENEFÍCIOS: Design moderno estilo Ilha Gourmet / Cozinha Americana Tampo amplo ideal para preparar alimentos ou servir refeições 3 Nichos e 2 Prateleiras para melhor organização Estrutura resistente em MDP 15mm Pintura UV que aumenta a durabilidade do móvel Ideal para cozinhas pequenas, cozinhas planejadas e áreas gourmet Cor Naturalle elegante e fácil de combinar DIMENSÕES DA BANCADA: Comprimento: 128,6 cm Largura: 52,5 cm Altura: 92,5 cm Peso: 25,5 kg ESPECIFICAÇÕES TÉCNICAS: Marca: Decibal Móveis Linha: Gaia Material: MDP 15 mm Acabamento: Pintura UV Cor: Naturalle (Madeirado) Prateleiras: 02 Nichos: 03 Montagem: Média (Recomenda-se montador) IDEAL PARA: Cozinha Americana Ilha Gourmet Cozinha Pequena Área Gourmet Cozinhas Modernas Espaços Integrados Sala e Cozinha CONTEÚDO DA EMBALAGEM: 01 Bancada Gourmet Gaia Kit de Ferragens Manual de Montagem OBSERVAÇÕES IMPORTANTES: Objetos decorativos não acompanham o produto. As cores podem variar levemente conforme a tela ou iluminação do ambiente. DICAS DE USO: Combine essa bancada com banquetas altas para criar um espaço perfeito para café da manhã, refeições rápidas ou momentos especiais com amigos e família.', 429.9, 369.9, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/br-11134207-820lv-mlxyrmzl0d8neb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F390327339%2F51353900333', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
