INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23793898195', 'Frontal da Gaveta Legumes para Geladeira Brastemp W10287547', 'Frontal da Gaveta Legumes para Geladeira Brastemp W10287547 A Frontal da Gaveta de Legumes para Geladeira Brastemp W10287547 é a escolha ideal para quem busca restaurar o visual interno do refrigerador com praticidade e eficiência. Fabricada com material resistente e acabamento transparente, ela se encaixa perfeitamente no compartimento de legumes, proporcionando visualização clara dos alimentos armazenados. Seu design funcional contribui para a organização e conservação dos vegetais, mantendo tudo em ordem e ao alcance das mãos. Compatível com modelos específicos da linha Brastemp, essa peça é essencial para quem deseja manter a funcionalidade e estética da geladeira como no primeiro dia. A estrutura foi pensada para facilitar a limpeza e o manuseio diário, evitando acúmulo de sujeira e garantindo maior higiene na rotina da cozinha. A substituição é simples e rápida, dispensando ferramentas complexas ou assistência técnica para instalação. Além de restaurar a funcionalidade da gaveta, essa frontal agrega valor ao eletrodoméstico, contribuindo para sua durabilidade e bom desempenho. Ideal para quem preza por organização e praticidade, ela é uma solução eficiente para danos como trincas ou quebras que comprometam o fechamento correto da gaveta. Garanta já a peça certa para manter sua geladeira completa, funcional e com visual renovado. Modelos Compatíveis: BRM38EB, BRM39EKANA, BRM39EKBNA, BRM39ERANA, BRM39ERBNA, BRM42EKANA, BRM42EKBNA, BRM42EBANA, BRM42EBBNA, BRM39E', 169.9, 169.9, NULL, 'Home Appliances > Large Household Appliances > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rdwr-mdbruyydbvwcf8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1398462025%2F23793898195', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23898201667', 'Calço de Borracha Quadrado Maciço 100X100X25 Hulter HT1CBQM0', 'Calço de Borracha Quadrado Maciço 100X100X25 Hulter HT1CBQM0 Produto de alta qualidade e versatilidade, projetado para atender diversas necessidades industriais e comerciais. Fabricado com borracha sólida de alta densidade, este calço possui um design quadrado que proporciona estabilidade e segurança para uma variedade de aplicações. Sua composição robusta e durável oferece resistência a impactos, abrasão e variações de temperatura, tornando-o ideal para ambientes internos e externos. Além disso, suas dimensões precisas e sua superfície antiderrapante garantem um ajuste seguro para estabilização de equipamentos, veículos ou estruturas diversas. O Calço de Borracha Quadrado Maciço é uma solução confiável para o suporte de cargas e proporciona uma base firme e segura, disponível para venda, atendendo às necessidades de setores industriais, logísticos e comerciais, onde a estabilidade e segurança são fundamentais.', 17.9, 17.9, NULL, 'Home Appliances > Large Household Appliances > Cooling', 'https://cf.shopee.com.br/file/sg-11134201-7rdx1-mcgrqwbpgj3nd5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1398462025%2F23898201667', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21899308125', 'Saco Para Lixo Banheiro & Pia Dover-Roll Branco 50 Sacos 34Cm X 40Cm', 'SUA CASA SEMPRE LIMPA! Dover-Roll Banheiro & Pia foi feito para ajudar no dia a dia sem perder a estética, na medida perfeita de cestas menores, usadas em pias de cozinha e nos banheiros. Vêm com um tubo para eventual uso em porta-rolos doméstico. Ele é branco e destacável, criado especialmente para conforto de quem não deixa de lado a qualidade e praticidade! ------------------------------------------------------------ DIMENSÕES: Comprimento: 40 cm Largura: 34 cm', 20.45, 20.45, NULL, 'Home & Living > Home Care Supplies > Plastic Bags & Trash Bags', 'https://cf.shopee.com.br/file/sg-11134201-7rdwh-lyclaxamijc207', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F590473480%2F21899308125', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23798215259', 'Expositor de Bebidas Venax 300 Litros Branco VV300 - 220V', 'Expositor de Bebidas Venax 300 Litros Branco VV300 - 220V Equipamento ideal para aqueles que buscam uma solução eficiente para a exposição e resfriamento de bebidas não alcoólicas, como águas, sucos e refrigerantes. Com uma capacidade generosa de 300 litros, este expositor proporciona um espaço amplo e bem organizado para acomodar uma variedade de produtos. Seu sistema de resfriamento é eficaz, com um controlador de temperatura mecânico que pode ser ajustado no intervalo de 0°C a 5°C, garantindo que suas bebidas sejam mantidas na temperatura perfeita. O vidro duplo transparente permite uma visão clara dos produtos e ajuda a manter a temperatura interna estável. Além disso, a iluminação interna com LED branco realça a apresentação dos produtos, tornando-os mais atraentes para os clientes. O expositor também oferece prateleiras reguláveis e ajustáveis, permitindo uma organização flexível do espaço interno. Com o degelo natural e o sistema de refrigeração por compressor, este produto é uma escolha confiável e conveniente para estabelecimentos comerciais que desejam manter suas bebidas sempre frescas e prontas para consumo.', 4346.74, 3259.0, NULL, 'Home Appliances > Kitchen Appliances > Refrigerators', 'https://cf.shopee.com.br/file/sg-11134201-824j5-mpdxy56jzpqj55', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1398462025%2F23798215259', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
