INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22797126025', 'Filtro Óleo Ford Ecosport Fiesta Ka Ranger MANN-FILTER W7800', 'NÃO VENDEMOS PARA PESSOA JURÍDICA CONSUMIDOR. PRODUTO NOVO. APLICAÇÃO: Ecosport 1.5 Dragon 2018 a 2021 Ecosport 1.6 (Sigma) 2017 Ecosport 2.0 Duratec 2017 a 2021 Fiesta 1.25i 16V 1996 a 2002 Fiesta 1.4 16V Gasolina 1996 a 1999 Fiesta 1.6 16V 2016 a 2019 Fusion 2.0 16V Hybrid / Ecoboost (CNG) 2016 a 2021 Ka 1.0 12V Flex (New Ka/ SE/ SE Plus/ SEL) 2014 a 2021 Ka 1.5 12V Flex (Freestyle, SE, SE Plus, Titanium) 2018 a 2021 Ka 1.5 16V Flex (New Ka/ SE/ SE Plus/ SEL) 2014 a 2018 Ranger 2.5 16V Flex (Sport 4X2 CS) 2014 a 2016 V50 1.6 2004 a 2012 CONTEÚDO DA EMBALAGEM: 1 Filtro de Óleo CARACTERÍSTICAS Código do Fabricante: W7800 Código da Montadora: EM5G/ 6714/ AA Tipo de Veículo: Carros / SUV''s e Caminhonetes Tipo de Aplicação: Peças Tipo de Combustível: Gasolina, Flex O PRODUTO Com a finalidade de remover os resíduos indesejáveis que podem estar contidos no óleo do motor, o filtro de óleo é feito com um papel especial, que está contido dentro da carcaça do filtro. O óleo sujo pode causar entupimento do motor do seu Ka, Fiesta, Fusion ou Ranger podendo causar até a fundição do mesmo. GARANTIA 3 meses > >', 15.49, 15.49, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rbkj-lo3te0c0m7yg66', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F817551928%2F22797126025', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
