INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58213345047', 'Capa para iPhone 17 Pro Max - Raptor - Gshield', 'DESCRIÇÃO O futuro da proteção para smartphones é o mais próximo do que você imagina! A Capa Tática Raptor para Capa Magsafe para iPhone 17 Pro Max - Raptor - Gshield da Gshield é uma combinação de proteção máxima aliada a funcionalidades inovadoras. Desenvolvida para garantir a segurança do seu dispositivo, essa capa proporciona resistência superior contra impactos e danos, mantendo seu celular protegido. O grande diferencial da capacidade é o anel multifuncional MagSafe, que além de ser compatível com carregadores magnéticos, também atua como um suporte kickstand ajustável, permitindo apoiar o celular em posição vertical ou horizontal para assistir vídeos, fazer videochamadas ou até mesmo trabalhar com mais conforto. E para ainda mais praticidade, o Raptor traz um recurso inovador: o Dente Raptor embutido no anel MagSafe, que é uma ponta pequena e estratégica projetada para abrir caixas, cortar fitas adesivas e auxiliar na abertura de embalagens com facilidade, um detalhe que faz toda a diferença no dia a dia. Seu design robusto inclui laterais laterais, um diferencial essencial para evitar que a capa escorregue. Com esse detalhe, seu celular fica mais seguro nas mãos, reduzindo o risco de quedas durante o uso diário. Além disso, a lateral também possui um espaço dedicado para acoplar um cordão ou alça de pulso, oferecendo mais segurança ao transportar seu dispositivo. Fabricado com materiais de alta qualidade, o Raptor conta com bordas elevadas que absorvem impactos e protegem tanto a tela quanto a traseira do aparelho. Certificado pelo padrão Us Military, o modelo garante durabilidade e minimiza danos em caso de quedas. Com um design moderno, resistente e funcional, a Capa Tática Raptor da Gshield é a escolha ideal para quem busca proteção, praticidade e tecnologia! ESPECIFICAÇÕES Marca: Gshield Material: Policarbonato e TPU Dimensões: Dimensões exatas do aparelho Proteção: Contra impactos e riscos Controles laterais: Maior aderência e segurança no conjunto Bordas ultra elevadas: Proteção extra contra impactos Anel MagSafe com suporte kickstand: Conforto para visualizar conteúdos Dente Raptor embutido: Facilidade para abrir caixas e embalagens Espaço para alça de pulso: Praticidade para o dia a dia Certificações: Us Military', 150.7, 150.7, NULL, 'Mobile & Gadgets > Accessories > Cases, Covers, & Skins', 'https://cf.shopee.com.br/file/sg-11134201-824is-mq04cjfr7dot1a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F58213345047', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22093682749', 'Película para Samsung Galaxy S23 Ultra - Privacidade Hydrogel - Gshield', 'DESCRIÇÃO Aumente a resistência com a película para o seu Samsung Galaxy S23 Ultra A Película Privacidade de Hydrogel para Samsung Galaxy S23 Ultra, da Gshield, garante proteção extra para a tela do seu dispositivo e garante sua privacidade. Produzida com a tecnologia hidro nano pet + material semelhante ao silicone, são ultra resistentes contra riscos e com revestimento oleofóbico, atenuando as marcas de digitais na tela do aparelho e impedindo que o conteúdo da tela seja visto lateralmente; a película se adapta às extremidades curvadas, cobrindo todo o visor. ESPECIFICAÇÕES Material: Hidro nano pet + TPU Soft Gel Marca: Gshield - ( Gorila Shiel d ) Espessura: 0,19mm Proteção: Contra pequenos impactos e riscos à tela Dimensões: Cobre todas as dimensões do aparelho, podendo haver pequenos recuos para melhor a aderências nas laterais. Certificações: US Military', 79.97, 79.97, NULL, 'Mobile & Gadgets > Accessories > Screen Protectors', 'https://cf.shopee.com.br/file/sg-11134201-7qvd3-lk5fegdafaza6a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F339198085%2F22093682749', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
