INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58200522026', 'Kit 2x Whey Protein Concentrado 1KG - FTW', 'Whey Concentrado FTW é um suplemento alimentar em pó à base de proteína do soro do leite concentrada, uma opção prática para quem deseja incluir mais proteína na rotina de forma saborosa e variada. É uma proteína em pó obtida do soro do leite, usada para complementar a ingestão diária de proteínas Fornece cerca de 15g de proteína por porção (40g), além de aminoácidos essenciais (EAA''s) Contém lactose e não contém glúten. Sabores Disponíveis - Baunilha - Chocolate - Cookies - Doce de Leite - Leite - Morango Ingredientes Proteína de soro do leite concentrada (WPC), aromatizante idêntico ao natural (variam de acordo com o sabor), espessante goma xantana, edulcorantes sucralose e acessulfame de potássio. Apresentação Refil com 1 Kg Porção: 40g (2 medidas dosadoras) Rendimento: Cerca de 25 porções. Como Consumir Dissolver 2 medidas dosadoras (40g) em 1 copo de 200ml de água ou leite gelado, e agitar com coqueteleira, liquidificador ou qualquer outra forma de misturador de seu gosto. Consumir 1 vez ao dia. Informações Adicionais Produto indicado para adultos maiores de 19 anos; Este produto não deve ser consumido por gestantes, lactantes ou crianças; Mantenha fora do alcance de crianças; Não exceder a recomendação diária de consumo indicada na embalagem; Conservar em local seco e fresco, ao abrigo da luz e umidade; Após aberto consumir em até 30 dias; Este produto não é um medicamento. Certificação Suplemento alimentar dispensado de registro conforme Resolução RDC nº 240/2018. Alegações baseadas no Anexo V da IN 28 Anvisa.', 274.9, 149.9, NULL, 'Health > Food Supplement > Fitness', 'https://cf.shopee.com.br/file/br-11134207-820lb-mm0m4eev9dkw54', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1397772996%2F58200522026', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
