INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22893230904', 'Kit 30m² Forro de PVC 8MMX20CMX3M(6m²) p/Cx Preto Bariri Preto', '"O forro PVC, também conhecido no mercado como teto de PVC, é o produto ideal para forrações e acabamentos de teto, mas é também muito utilizado para aplicação em paredes, pois deixa o ambiente mais requintado. <br> Esse modelo de forro PVC da Bariri é comercializado em várias cores como branco, mogno, cerejeira, imbuia muitos outros. <br> O forro PVC Preto tem um preço muito acessível, sendo uma das soluções mais econômicas para sua obra. Ainda é possível economizar na instalação, pois mesmo pode ser instalado sem um profissional credenciado.<br> Possui normas técnica .<br> NBR 14285, índice de propagação de chamas NBR 9442 - classe - A , densidade óptica de fumaça ASTM E662 resultado 221 DM." Garantia: 12 Meses Largura (cm): 20 Rendimento: 30 m² por caixa: 6 Espessura (mm): 8 Comprimento (cm): 300 Profundidade (cm): 300 Origem do Produto: Nacional Permite Reutilização: Sim Acompanha Ficha Técnica: Não Porte do Ambiente Indicado: Médio Porte Acompanha Manual de Instalação: Não Informações Complementares (Novo): Não requer pintura, resistente a cupim, isolante térmico, acústico Material Principal Construção e Acabamento: PVC Marca: Bariri Modelo: Forro Bariri Cor: Preto Meio Ambiente: Material reciclado Cor do Produto: Preto Itens Inclusos: Embalagem plástica, cantoneira de papelão Cor Predominante: Preto Linha ou Coleção: Bariri Tipo de Certificado: NBR14285 Tamanho do Produto: 8mm x 20cm x 3,00m', 1324.11, 1324.11, NULL, 'Home & Living > Tools & Home Improvement > Roofing & Flooring', 'https://cf.shopee.com.br/file/sg-11134201-820lq-mo1uh0bg9bsw28', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F855489892%2F22893230904', NULL, NULL, '2026-07-28T02:11:31.708458+00