INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19097691198', 'Roda Speedmax Aro 22.5 YF28B16 Aço Disco 22.5x8.25 10 Furos', '*Nossas vendas são realizadas apenas para consumidor final, sendo vetada a comercialização para CNPJ de revendedores. Sobre a SpeedMax A SpeedMax produz pneus para todos os tipos de veículo, com qualidade e custo que ao encontro com a sua busca por um pneu com ótima dirigibilidade, desempenho e economia para ter o máximo em qualquer situação - do campo ao asfalto. Pensados em Centros de Pesquisa e Desenvolvimento em países como China, Vietnã, Índia e Paquistão, a SpeedMax também tem produção feita no México e é homologada nos principais mercados, como Brasil e Estados Unidos.', 613.52, 564.44, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Truck Wheels', 'https://cf.shopee.com.br/file/sg-11134201-7rd3o-lvnkcl49wz3404', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F549724933%2F19097691198', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
