INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23292133526', 'Descontaminante Ferroso Izer Limpa Rodas 500ml Vonixx', 'Este anúncio contém: 1 (um) Descontaminante ferroso Izer 500ml original da marca Vonixx. Código do Fabricante: Izer/2011040; Código Universal: 7898511028094. Sobre o produto: Izer é um descontaminante ferroso de pH neutro que remove fuligem de freio oxidado em rodas, age na eliminação de oxidação de material ferroso da pintura e demais partes externas do veículo e ajuda na remoção de pontos de ferrugem em partes cromadas. No motor, auxilia na remoção da oxidação de partes metálicas, deixando-o com aspecto renovado. O produto não é indicado para uso em superfícies zincadas. Modo de usar: Certifique-se que a superfície esteja fria; Pulverize uma pequena quantidade de produto na superfície a ser descontaminada; Aguarde de 2 a 3 minutos e observe a formação de uma cor roxa ou mais escura; Com o auxílio de escova para caixas de rodas, pincel para detalhamento ou luva de microfibra, esfregue de maneira uniforme para ajudar na completa remoção dos contaminantes; Enxágue em seguida com a ajuda de uma lavadora de alta pressão. Dúvidas frequentes: 1 - Trabalhamos apenas com produtos novos, e com garantia; 2 - Produto a pronta entrega; 3 - Seus produtos serão enviados em até 24 horas úteis após a confirmação do pagamento. Sobre a empresa: Somos uma Auto Peças fundada em 1980, atuamos no mercado varejista de peças e acessórios, tendo como principais clientes oficinas mecânicas e consumidor final. Não achou o que procura? Ficou com alguma dúvida sobre o produto? Fale conosco através do campo de perguntas.', 47.78, 43.01, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Degreasers', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lkjj01y7jbs8a1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fs