INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23094040546', 'Luva Ciclismo HUPI Eco Dedo Curto Bike Brain', 'Luva Ciclismo HUPI Eco Dedo Curto Bike Brain As luvas para ciclismo são obrigatórias para quem quer ter cuidado com as mãos e o corpo. São confortáveis para provas longas e treinos, tem função de amortecer o impacto com o chão em quedas ou proteger as mãos de possíveis galhos soltos nas trilhas de bike. As luvas de bike ajudam a manter a mão firme no guidão, evitando aquele atrito que causa calos e bolhas, ou ainda uma lesão mais grave além das mãos, ombros ou costas. As luvas de meio dedo são ótimas, pois ventilam melhor as mãos. Os modelos de luvas de ciclismo da HUPI são especialmente desenhados para proteção nos locais mais sensíveis da mão, são pontos estratégicos com mais impacto durante a prova ou treino. Os modelos de meio dedo ainda tem menos pressão na mão e são mais fáceis de colocar e tirar. Quando pedalamos transpiramos bastante e as luvas não deixam que o suor dos seus braços desçam, evitando assim que suas mãos escorreguem. CARACTERÍSTICAS: * Composição: Poliéster |Nylon |Algodão |Lycra |Spandex; * Palma com Grip; * Lavável; * Resistente. Combine luvas com manguitos, meias, macaquinho de ciclismo ou bandanas.', 87.16, 71.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/sg-11134201-7rasq-ma2ybse0kf1250', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F524728336%2F23094040546', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
