INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58210087510', 'Baú Plástico Abs Reforçado 45 litros Preto com Forro/Alça e Base', 'Baú Moto 45L Universal com Base e Chaves – ABS Reforçado Baú traseiro ideal para quem busca praticidade, segurança e espaço no dia a dia ou em viagens. Fabricado em ABS de alta resistência, oferece excelente durabilidade e proteção contra chuva, poeira e impactos. Com capacidade de 45 litros, permite transportar capacete, jaqueta, luvas e diversos objetos com segurança e organização. Compatibilidade Compatível com motos que possuem bagageiro traseiro: Honda, Yamaha, Suzuki, Kawasaki, BMW, Triumph e outras. Encaixe universal com base inclusa. Características Capacidade: 45 Litros Material: ABS reforçado Cor: Preto Peso aproximado: 7kg Dimensões: 41 x 33 x 30,5 cm Diferenciais 100% impermeável (proteção contra chuva e poeira) Duplo sistema de trava com chave Base com engate rápido Alta resistência a impactos Design moderno e robusto Refletores para melhor visibilidade Instalação Instalação simples com base universal inclusa. Sistema de encaixe rápido, fácil de travar e remover. Recomenda-se seguir corretamente a posição dos parafusos e arruelas para melhor fixação. Caso haja vibração, pode ser feito ajuste com borracha para eliminar folgas entre base e baú. Conteúdo da Embalagem 1 Baú traseiro 45L 1 Base universal 1 Kit de instalação completo 2 Chaves 4 Adesivos refletivos 1 Forro interno Manual Observações Produto novo e testado antes do envio Pode haver variação de 1 a 3 cm nas medidas Pequenas variações de cor podem ocorrer devido à iluminação', 497.09, 321.97, NULL, 'Spare Parts and Accessories for Vehicles > Accessories for Motorcycles > Cases', 'https://cf.shopee.com.br/file/br-11134207-820ma-mnuhc6crjmkhf0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F166