INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20115502517', 'Exaustor para banheiro diâmetro de 150 mm - EXB Ventisol', 'Produto: Exaustor para banheiro diâmetro de 150 mm - EXB Marca: Ventisol Voltagem: 110V/220V Descrição: O Exaustor para banheiro diâmetro de 150 mm EXB da Ventisol foi desenvolvido para remover o ar impuro, vapor e fumaça de ambientes fechados. É adequado para banheiros e recintos pequenos. Com vazão de 75 m³/h, o Exaustor EXB pode ser ligado em conjunto com a lâmpada do banheiro e é adaptável a tubos de PVC 150 mm. Recomendável para ambientes de até 10 m². Características: • Motor BLDC: Baixo consumo e alto rendimento; • Elimina odor e vapor; • Fácil instalação; • Grade anti-inseto; • Uso doméstico. Especificações: Potência: 5 Watts Velocidade: 1350 rpm Dimensões (C x L x A): 20.00 x 8.60 x 20.00 centímetros Peso: 0.74 Kg', 145.93, 132.9, NULL, 'Home Appliances > Large Household Appliances > Cooling', 'https://cf.shopee.com.br/file/sg-11134201-8259s-mr4miecl83d1b8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F489001115%2F20115502517', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
