INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18199028760', 'Cabo Embreagem Fiat Palio 1996 a 2000 - 100335 - 3312', 'Cabo Embreagem Fiat Palio 1996 a 2000 100335 3312 MOTOR 1.0 MPI (698mm) O processo se inicia quando o pedal de embreagem é pressionado, esse movimento é transmitido pelo cabo, ou varão de embreagem, até o garfo do rolamento, que pressionará a mola membrana, ou alavancas, do platô. Isso fará com que o disco de embreagem seja liberado e, dessa maneira, o torque do motor deixa de ser transmitido ao câmbio. Nesse momento, é criada uma diferença de rotação entre o motor do veículo e seu sistema de transmissão.', 68.73, 68.73, NULL, 'Automobiles > Automobile Spare Parts > Drivetrain, Transmission & Clutches', 'https://cf.shopee.com.br/file/sg-11134201-7reon-m8gg9soosuxj30', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F18199028760', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
