INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22897292919', 'Kit Esmalte Impala Perolado Lua (5 unidades)', 'Esmalte Impala: Unhas deslumbrantes e tendência com durabilidade e brilho prolongado Descubra o poder transformador dos esmaltes Impala e experimente o apogeu da tecnologia cosmética em suas unhas. Formulados com a mais alta qualidade, nossos esmaltes seguem as últimas tendências e garantem resultados surpreendentes, valorizando suas mãos, pés e, acima de tudo, sua beleza única. Com ação duradoura e brilho prolongado, os esmaltes Impala permitem que você crie looks duradouros e deslumbrantes. Experimente a facilidade de aplicação e a cobertura completa que permite uma ou duas camadas, dependendo da intensidade desejada. Benefícios: - Fórmula de alta qualidade com durabilidade estendida e brilho intenso; - Tendências atualizadas para manter suas unhas sempre modernas; - Variedade de cores para combinar com seu estilo; - Fácil aplicação e cobertura completa; - Ação duradoura que permite mãos e pés impecáveis por mais tempo. Modo de usar: 1. Prepare suas unhas limpando-as cuidadosamente. 2. Aplique uma camada do esmalte Impala desejado, começando pela base da unha e seguindo até a ponta. 3. Para uma cobertura mais intensa, aplique uma segunda camada após a primeira secar. 4. Deixe o esmalte secar completamente antes de realizar qualquer atividade. Experimente agora os esmaltes Impala e eleve suas unhas ao próximo nível de beleza e tendência! Kit contem 5 unidades do Esmalte Impala Perolado Lua', 38.45, 38.45, NULL, 'Beauty > Hand, Foot & Nail Care > Nail Care', 'https://cf.shopee.com.br/file/sg-11134201-7rbn9-lqm1fvyks1fe63', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F22897292919', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
